-- ----------------------------
-- Table structure for eza_card
-- ----------------------------
DROP TABLE IF EXISTS `eza_card`;
CREATE TABLE `eza_card`  (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID (UUID)',
  `card_id` bigint NOT NULL COMMENT '卡片ID',
  `card_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '卡片名称',
  `step` tinyint NOT NULL COMMENT '极限阶段',
  `title` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '卡片描述',
  `type` int NULL DEFAULT NULL COMMENT '属性 (0:超系 1:极系)',
  `prop_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '具体属性',
  `cost` int NULL DEFAULT NULL COMMENT 'cost值',
  `rarity` int NULL DEFAULT NULL COMMENT '稀有度',
  `lv_max` int NULL DEFAULT NULL COMMENT '满级',
  `hp_value` bigint NULL DEFAULT NULL COMMENT '生命值',
  `atk_value` bigint NULL DEFAULT NULL COMMENT '攻击值',
  `def_value` bigint NULL DEFAULT NULL COMMENT '防御值',
  `passive_skill_id` bigint NOT NULL COMMENT '被动技能id',
  `passive_skill_desc` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '被动具体信息',
  `leader_skill_id` bigint NULL DEFAULT NULL COMMENT '队长技id',
  `leader_skill` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '队长技信息',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `attributes` json NULL COMMENT '扩展属性',
  `creator` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modifier` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '极限卡牌表' ROW_FORMAT = Dynamic;

