INSERT INTO `eza_card` VALUES ('0860c5d940804a41', 1007681, '贝吉达(巨猿)', 7, '压制死斗的力量', 200, '20', 46, 4, 140, 11081, 11120, 6244, 2603, '*基本效果*\n‧ATK与DEF80%{passiveImg:up_g}\n‧有机率巨猿化(最多2次)\n*气力值12以上攻击时*\n‧ATK与DEF80%{passiveImg:up_g}\n*HP80%以下*\n‧ATK80%{passiveImg:up_g}', 1007681, '全属性的气力+3、HP、ATK、DEF提升70%', '2021-10-06 16:00:00', '{\"leaderSkill\": \"全属性的气力+3、HP、ATK、DEF提升70%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1007681, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF80%{passiveImg:up_g}\\n‧有机率巨猿化(最多2次)\\n*气力值12以上攻击时*\\n‧ATK与DEF80%{passiveImg:up_g}\\n*HP80%以下*\\n‧ATK80%{passiveImg:up_g}\", \"passiveSkillName\": \"愤怒的超级菁英\", \"passiveSkillSetId\": 2603}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('08c75cb869b24f3a', 1004651, '完美赛鲁', 8, '凌驾于万物', 200, '21', 42, 4, 140, 12589, 11007, 7443, 4527, '*基本效果*\n‧气珠变化：速气珠→技气珠\n‧随机气珠变化：速气珠与技气珠以外的任一属性气珠→彩虹珠\n‧取得彩虹珠时气力再+2\n‧发动奋力一击的机率与伤害减轻率20%{passiveImg:up_g}\n‧必可发动追加攻击且高机率发动必杀技\n*敌方有超系的角色时*\n‧伤害减轻率20%{passiveImg:up_g}\n‧敌方全体的ATK20%{passiveImg:down_y}\n*参加攻击中的我方除了自己以外，有极系的角色时*\n‧我方全体的DEF40%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\n*每取得1个气珠*\n‧ATK与DEF50%{passiveImg:up_g}\n*每取得1个彩虹珠*\n‧发动奋力一击的机率与伤害减轻率10%{passiveImg:up_g}\n*攻击时*\n‧ATK与DEF200%{passiveImg:up_g}', 1004651, '技属性的气力+3、HP、ATK、DEF提升70%', '2025-02-16 16:00:00', '{\"leaderSkill\": \"技属性的气力+3、HP、ATK、DEF提升70%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1004651, \"passiveSkillDesc\": \"*基本效果*\\n‧气珠变化：速气珠→技气珠\\n‧随机气珠变化：速气珠与技气珠以外的任一属性气珠→彩虹珠\\n‧取得彩虹珠时气力再+2\\n‧发动奋力一击的机率与伤害减轻率20%{passiveImg:up_g}\\n‧必可发动追加攻击且高机率发动必杀技\\n*敌方有超系的角色时*\\n‧伤害减轻率20%{passiveImg:up_g}\\n‧敌方全体的ATK20%{passiveImg:down_y}\\n*参加攻击中的我方除了自己以外，有极系的角色时*\\n‧我方全体的DEF40%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\\n*每取得1个气珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n*每取得1个彩虹珠*\\n‧发动奋力一击的机率与伤害减轻率10%{passiveImg:up_g}\\n*攻击时*\\n‧ATK与DEF200%{passiveImg:up_g}\", \"passiveSkillName\": \"憎恶的化身\", \"passiveSkillSetId\": 4527}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('090f03e2a7284b63', 1010161, '魔人贝吉达', 4, '凄绝之光的彼端', 200, '20', 77, 5, 150, 16050, 15870, 9763, 4742, '*基本效果*\n‧气力+6、ATK与DEF250%{passiveImg:up_g}\n‧发动奋力一击的机率与伤害减轻率30%{passiveImg:up_g}\n‧随机气珠变化：速气珠以外的任一属性气珠→速气珠\n*队伍里有3名以上超系的角色时*\n‧我方全体的气力+3、DEF80%{passiveImg:up_g}\n*队伍里有3名以上极系的角色时*\n‧攻击时ATK150%{passiveImg:up_g}\n*气力值12以上*\n‧攻击时ATK200%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\n‧受到攻击时DEF150%{passiveImg:up_g}、伤害减轻率20%{passiveImg:up_g}\n*气力值18以上*\n‧攻击时ATK250%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\n‧受到攻击时DEF150%{passiveImg:up_g}、伤害减轻率20%{passiveImg:up_g}\n*HP60%以下*\n‧ATK200%{passiveImg:up_g}\n‧必可发动奋力一击\n‧{passiveImg:once}敌方或是参加攻击中的我方除自身以外，\n有「魔人普乌篇」类别的角色时，\n或是敌方或是队伍里有名称含有\n「布马」或「特南克斯(幼年期)」或\n「孙悟空」(不包含奇纽、Jr.等)的角色时，\n气力+12、ATK600%{passiveImg:up_g}', 1010161, '速属性的气力+4、HP、ATK、DEF提升120%', '2025-10-15 16:00:00', '{\"leaderSkill\": \"速属性的气力+4、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1010161, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+6、ATK与DEF250%{passiveImg:up_g}\\n‧发动奋力一击的机率与伤害减轻率30%{passiveImg:up_g}\\n‧随机气珠变化：速气珠以外的任一属性气珠→速气珠\\n*队伍里有3名以上超系的角色时*\\n‧我方全体的气力+3、DEF80%{passiveImg:up_g}\\n*队伍里有3名以上极系的角色时*\\n‧攻击时ATK150%{passiveImg:up_g}\\n*气力值12以上*\\n‧攻击时ATK200%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\\n‧受到攻击时DEF150%{passiveImg:up_g}、伤害减轻率20%{passiveImg:up_g}\\n*气力值18以上*\\n‧攻击时ATK250%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\\n‧受到攻击时DEF150%{passiveImg:up_g}、伤害减轻率20%{passiveImg:up_g}\\n*HP60%以下*\\n‧ATK200%{passiveImg:up_g}\\n‧必可发动奋力一击\\n‧{passiveImg:once}敌方或是参加攻击中的我方除自身以外，\\n有「魔人普乌篇」类别的角色时，\\n或是敌方或是队伍里有名称含有\\n「布马」或「特南克斯(幼年期)」或\\n「孙悟空」(不包含奇纽、Jr.等)的角色时，\\n气力+12、ATK600%{passiveImg:up_g}\", \"passiveSkillName\": \"为了心爱的人\", \"passiveSkillSetId\": 4742}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
