INSERT INTO `eza_card` VALUES ('0b189865cee7486b', 1019681, '老八', 7, '最大的愤怒与力量', 100, '13', 36, 4, 140, 10211, 11092, 5269, 4278, '*登场后1回合内*\n‧伤害减轻率30%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK100%{passiveImg:up_g}\n*受到攻击后*\n‧5回合内气力+3、ATK180%{passiveImg:up_g}、防御所有攻击\n*每次受到攻击时*\n‧{passiveImg:forever}伤害减轻率10%{passiveImg:up_g}(最高40%)\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高80%)\n*战斗中受到8次攻击前*\n‧DEF180%{passiveImg:up_g}\n*战斗中受到8次以上攻击后*\n‧{passiveImg:forever}下一个进攻回合起，我方全体「少年篇」类别的\nATK与DEF20%{passiveImg:up_g}，若有包含名称含有「孙悟空(少年期)」\n的角色，气力+2、ATK与DEF再20%{passiveImg:up_g}\n*队伍里有「孙悟空的家谱」类别的角色时*\n‧ATK与DEF180%{passiveImg:up_g}', 1019682, '力属性的气力+3、HP、ATK、DEF提升100%', '2024-10-17 16:00:00', '{\"leaderSkill\": \"力属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019682, \"passiveSkillDesc\": \"*登场后1回合内*\\n‧伤害减轻率30%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK100%{passiveImg:up_g}\\n*受到攻击后*\\n‧5回合内气力+3、ATK180%{passiveImg:up_g}、防御所有攻击\\n*每次受到攻击时*\\n‧{passiveImg:forever}伤害减轻率10%{passiveImg:up_g}(最高40%)\\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高80%)\\n*战斗中受到8次攻击前*\\n‧DEF180%{passiveImg:up_g}\\n*战斗中受到8次以上攻击后*\\n‧{passiveImg:forever}下一个进攻回合起，我方全体「少年篇」类别的\\nATK与DEF20%{passiveImg:up_g}，若有包含名称含有「孙悟空(少年期)」\\n的角色，气力+2、ATK与DEF再20%{passiveImg:up_g}\\n*队伍里有「孙悟空的家谱」类别的角色时*\\n‧ATK与DEF180%{passiveImg:up_g}\", \"passiveSkillName\": \"对孙悟空的感谢\", \"passiveSkillSetId\": 4278}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
