INSERT INTO `eza_card` VALUES ('0c4fb7a77a07426d', 1023571, '布罗利', 7, '为生存培养的力量', 200, '23', 40, 4, 140, 12952, 12811, 5300, 4720, '*基本效果*\n‧气力+1、ATK与DEF260%{passiveImg:up_g}\n‧对全属性造成属性克制伤害\n‧随机气珠变化：力气珠以外的任一属性气珠→彩虹珠\n*气力值12以上攻击时*\n‧ATK与DEF160%{passiveImg:up_g}\n‧伤害减轻率40%{passiveImg:up_g}\n*取得2个以上气珠攻击时*\n‧DEF100%{passiveImg:up_g}\n‧伤害减轻率20%{passiveImg:up_g}\n‧使敌方防御无效\n*取得6个以上气珠攻击时*\n‧ATK100%{passiveImg:up_g}\n‧必可追加发动必杀技\n*攻击时目标的HP80%以下*\n‧ATK与DEF50%{passiveImg:up_g}\n‧高机率发动奋力一击\n*攻击时目标的HP50%以下*\n‧ATK与DEF50%{passiveImg:up_g}\n‧必可追加发动必杀技\n*给予敌人致命一击后*\n‧回合结束时完全回复HP', 1023571, '「剧场版BOSS」类别的\n气力+3、HP、ATK、DEF提升150%', '2025-09-16 16:00:00', '{\"leaderSkill\": \"「剧场版BOSS」类别的\\n气力+3、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023571, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+1、ATK与DEF260%{passiveImg:up_g}\\n‧对全属性造成属性克制伤害\\n‧随机气珠变化：力气珠以外的任一属性气珠→彩虹珠\\n*气力值12以上攻击时*\\n‧ATK与DEF160%{passiveImg:up_g}\\n‧伤害减轻率40%{passiveImg:up_g}\\n*取得2个以上气珠攻击时*\\n‧DEF100%{passiveImg:up_g}\\n‧伤害减轻率20%{passiveImg:up_g}\\n‧使敌方防御无效\\n*取得6个以上气珠攻击时*\\n‧ATK100%{passiveImg:up_g}\\n‧必可追加发动必杀技\\n*攻击时目标的HP80%以下*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧高机率发动奋力一击\\n*攻击时目标的HP50%以下*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧必可追加发动必杀技\\n*给予敌人致命一击后*\\n‧回合结束时完全回复HP\", \"passiveSkillName\": \"求生之战\", \"passiveSkillSetId\": 4720}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
