INSERT INTO `eza_card` VALUES ('0de4bb83e6844fd6', 1023621, '孙悟空(界王拳)', 3, '挑战极限', 100, '13', 77, 5, 150, 14138, 16295, 10188, 4524, '*自身的进攻回合开始时，\n敌方有名称含有「贝吉达」的角色时\n(不包含幼年期、Jr.等)，\n发动登场时动画*\n‧{passiveImg:once}{passiveImg:forever}气力+3、ATK100%{passiveImg:up_g}\n*基本效果*\n‧ATK与DEF200%{passiveImg:up_g}\n‧超高机率发动奋力一击\n‧随机气珠变化：力气珠以外的任一属性气珠→力气珠\n‧取得力气珠时气力再+2\n*登场后7回合内*\n‧气力+10、DEF100%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF159%{passiveImg:up_g}\n*气力值18以上攻击时*\n‧ATK159%{passiveImg:up_g}\n*每取得1个力气珠*\n‧伤害减轻率4%{passiveImg:up_g}\n*发动主动技能时，\n或是气力值24攻击时*\n‧必可发动奋力一击', 1023621, '「全力奋斗」或是「最后的杀手锏」类别的\n气力+4、HP、ATK、DEF提升170%', '2025-02-20 16:00:00', '{\"leaderSkill\": \"「全力奋斗」或是「最后的杀手锏」类别的\\n气力+4、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023621, \"passiveSkillDesc\": \"*自身的进攻回合开始时，\\n敌方有名称含有「贝吉达」的角色时\\n(不包含幼年期、Jr.等)，\\n发动登场时动画*\\n‧{passiveImg:once}{passiveImg:forever}气力+3、ATK100%{passiveImg:up_g}\\n*基本效果*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧超高机率发动奋力一击\\n‧随机气珠变化：力气珠以外的任一属性气珠→力气珠\\n‧取得力气珠时气力再+2\\n*登场后7回合内*\\n‧气力+10、DEF100%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF159%{passiveImg:up_g}\\n*气力值18以上攻击时*\\n‧ATK159%{passiveImg:up_g}\\n*每取得1个力气珠*\\n‧伤害减轻率4%{passiveImg:up_g}\\n*发动主动技能时，\\n或是气力值24攻击时*\\n‧必可发动奋力一击\", \"passiveSkillName\": \"威力倍增的招式\", \"passiveSkillSetId\": 4524}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
