INSERT INTO `eza_card` VALUES ('128d9b995ea7491b', 1015841, '象帕', 7, '由破坏而生的主导权', 200, '24', 40, 4, 140, 13375, 10387, 6454, 3916, '*基本效果*\n‧DEF160%{passiveImg:up_g}\n‧我方全体「第6宇宙」类别的气力+2、ATK与DEF\n40%{passiveImg:up_g}，若HP为60%以下，ATK与DEF再20%{passiveImg:up_g}\n‧高机率使ATK400%{passiveImg:up_g}\n‧中等机率使ATK600%{passiveImg:up_g}\n‧低机率发动奋力一击\n*攻击时*\n‧DEF120%{passiveImg:up_g}', 1015841, '「第6宇宙」类别的\n气力+3、HP、ATK、DEF提升130%，\n或是体属性的气力+3、HP、ATK、DEF提升90%', '2024-02-06 16:00:00', '{\"leaderSkill\": \"「第6宇宙」类别的\\n气力+3、HP、ATK、DEF提升130%，\\n或是体属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015841, \"passiveSkillDesc\": \"*基本效果*\\n‧DEF160%{passiveImg:up_g}\\n‧我方全体「第6宇宙」类别的气力+2、ATK与DEF\\n40%{passiveImg:up_g}，若HP为60%以下，ATK与DEF再20%{passiveImg:up_g}\\n‧高机率使ATK400%{passiveImg:up_g}\\n‧中等机率使ATK600%{passiveImg:up_g}\\n‧低机率发动奋力一击\\n*攻击时*\\n‧DEF120%{passiveImg:up_g}\", \"passiveSkillName\": \"独特的提案\", \"passiveSkillSetId\": 3916}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('12c4cc15047a4b3c', 1019461, '超级赛亚人孙悟天(幼年期)', 7, '所有的力量', 100, '12', 40, 4, 140, 13083, 11655, 6670, 4127, '*基本效果*\n‧ATK与DEF180%{passiveImg:up_g}\n‧伤害减轻率50%{passiveImg:up_g}\n*参加攻击中的我方有名称含有「特南克斯(幼年期)」\n或是「克林」(不包含少年期)的角色时*\n‧气力值12以上攻击时ATK120%{passiveImg:up_g}、伤害减轻率30%{passiveImg:up_g}\n*处于该回合第一攻击顺位时*\n‧我方全体「龟派气功」类别的气力+1、\nATK50%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\n*处于该回合第二攻击顺位时*\n‧我方全体「龟派气功」类别的气力+2、\nATK70%{passiveImg:up_g}、发动奋力一击的机率30%{passiveImg:up_g}\n*处于该回合第三攻击顺位时*\n‧气力+3\n‧气力值12以上攻击时ATK120%{passiveImg:up_g}、高机率发动奋力一击', 1019461, '「龟派气功」类别的\n气力+3、HP、ATK、DEF提升120%，\n或是知与体属性的\n气力+3、HP、ATK、DEF提升90%', '2024-05-13 16:00:00', '{\"leaderSkill\": \"「龟派气功」类别的\\n气力+3、HP、ATK、DEF提升120%，\\n或是知与体属性的\\n气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019461, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF180%{passiveImg:up_g}\\n‧伤害减轻率50%{passiveImg:up_g}\\n*参加攻击中的我方有名称含有「特南克斯(幼年期)」\\n或是「克林」(不包含少年期)的角色时*\\n‧气力值12以上攻击时ATK120%{passiveImg:up_g}、伤害减轻率30%{passiveImg:up_g}\\n*处于该回合第一攻击顺位时*\\n‧我方全体「龟派气功」类别的气力+1、\\nATK50%{passiveImg:up_g}、发动奋力一击的机率20%{passiveImg:up_g}\\n*处于该回合第二攻击顺位时*\\n‧我方全体「龟派气功」类别的气力+2、\\nATK70%{passiveImg:up_g}、发动奋力一击的机率30%{passiveImg:up_g}\\n*处于该回合第三攻击顺位时*\\n‧气力+3\\n‧气力值12以上攻击时ATK120%{passiveImg:up_g}、高机率发动奋力一击\", \"passiveSkillName\": \"勇气全开\", \"passiveSkillSetId\": 4127}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('12dbe20c79dc4048', 1018841, '超级赛亚人孙悟饭(青年期)', 7, '街谈巷议的正义战士', 100, '13', 40, 4, 140, 12745, 10376, 6581, 4106, '*基本效果*\n‧ATK与DEF158%{passiveImg:up_g}\n‧伤害减轻率58%{passiveImg:up_g}\n‧我方全体超系的气力+3、ATK与DEF30%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF58%{passiveImg:up_g}\n*敌方有极系的角色时*\n‧ATK与DEF58%{passiveImg:up_g}\n‧使攻击过的敌人2回合内ATK20%{passiveImg:down_y}', 1018842, '超系的气力+3、HP、ATK、DEF提升77%', '2024-06-27 16:00:00', '{\"leaderSkill\": \"超系的气力+3、HP、ATK、DEF提升77%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1018842, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF158%{passiveImg:up_g}\\n‧伤害减轻率58%{passiveImg:up_g}\\n‧我方全体超系的气力+3、ATK与DEF30%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF58%{passiveImg:up_g}\\n*敌方有极系的角色时*\\n‧ATK与DEF58%{passiveImg:up_g}\\n‧使攻击过的敌人2回合内ATK20%{passiveImg:down_y}\", \"passiveSkillName\": \"暗中惩治恶人\", \"passiveSkillSetId\": 4106}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('131431ed70a84759', 1024661, '合体扎马斯', 3, '理想世界的开端', 200, '22', 77, 5, 150, 17750, 16210, 8488, 4646, '*自身登场时，我方队伍除了自己以外，\n有「波特拉」类别的角色时，\n发动登场时动画*\n‧{passiveImg:once}5回合内取得气珠时气力再+1、\n气珠变化：技气珠→彩虹珠\n*基本效果*\n‧取得气珠时气力再+1\n‧随机气珠变化：知气珠与技气珠以外的任一属性气珠→知气珠\n‧ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率30%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF50%{passiveImg:up_g}\n‧追加发动必杀技\n*气力值18以上攻击时*\n‧ATK与DEF50%{passiveImg:up_g}\n‧对全属性造成属性克制伤害\n‧追加发动必杀技\n*气力值24攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n‧必可发动奋力一击\n*每次受到攻击或是回避敌人的攻击时*\n‧该回合伤害减轻率10%{passiveImg:up_g}(最高30%)\n‧{passiveImg:forever}气力+1(最高+5)\n*战斗中每次受到3次以上攻击\n或是回避敌人的攻击3次以上时*\n‧回合结束时HP回复10%(该回合最多1次)\n*受到敌人的格斗系必杀技攻击时*\n‧超高机率使其无效，并以超绝大威力反击\n‧取得10个以上气珠时\n必可使其无效，并以超绝大威力反击', 1024661, '「世界的乱源」或是「波特拉」类别的\n气力+4、HP、ATK、DEF提升170%', '2025-07-16 16:00:00', '{\"leaderSkill\": \"「世界的乱源」或是「波特拉」类别的\\n气力+4、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1024661, \"passiveSkillDesc\": \"*自身登场时，我方队伍除了自己以外，\\n有「波特拉」类别的角色时，\\n发动登场时动画*\\n‧{passiveImg:once}5回合内取得气珠时气力再+1、\\n气珠变化：技气珠→彩虹珠\\n*基本效果*\\n‧取得气珠时气力再+1\\n‧随机气珠变化：知气珠与技气珠以外的任一属性气珠→知气珠\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率30%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧追加发动必杀技\\n*气力值18以上攻击时*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧对全属性造成属性克制伤害\\n‧追加发动必杀技\\n*气力值24攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧必可发动奋力一击\\n*每次受到攻击或是回避敌人的攻击时*\\n‧该回合伤害减轻率10%{passiveImg:up_g}(最高30%)\\n‧{passiveImg:forever}气力+1(最高+5)\\n*战斗中每次受到3次以上攻击\\n或是回避敌人的攻击3次以上时*\\n‧回合结束时HP回复10%(该回合最多1次)\\n*受到敌人的格斗系必杀技攻击时*\\n‧超高机率使其无效，并以超绝大威力反击\\n‧取得10个以上气珠时\\n必可使其无效，并以超绝大威力反击\", \"passiveSkillName\": \"扎马斯才是宇宙的力量\", \"passiveSkillSetId\": 4646}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('1323afa30aa1467b', 1025181, '金属克维拉[知]', 7, '钢铁战鬼', 200, '22', 32, 4, 140, 9126, 9638, 6200, 2995, '*基本效果*\n‧回合开始时HP回复10%\n*回合开始时，处于该回合第一顺位时*\n‧气珠变化：技气珠→彩虹珠\n*队伍里每多1名「最凶恶的一族」类别的角色*\n‧ATK与DEF40%{passiveImg:up_g}(最高200%)\n*参加攻击中的我方除了自己以外，有\n名称含有「金属克维拉」的角色时*\n‧每取得1个气珠ATK与DEF10%{passiveImg:up_g}\n‧取得3个以上彩虹珠时回合结束时HP回复5%', 1025182, '「目标孙悟空」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是全属性的气力+3、HP、ATK、DEF提升40%', '2022-09-21 16:00:00', '{\"leaderSkill\": \"「目标孙悟空」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是全属性的气力+3、HP、ATK、DEF提升40%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1025182, \"passiveSkillDesc\": \"*基本效果*\\n‧回合开始时HP回复10%\\n*回合开始时，处于该回合第一顺位时*\\n‧气珠变化：技气珠→彩虹珠\\n*队伍里每多1名「最凶恶的一族」类别的角色*\\n‧ATK与DEF40%{passiveImg:up_g}(最高200%)\\n*参加攻击中的我方除了自己以外，有\\n名称含有「金属克维拉」的角色时*\\n‧每取得1个气珠ATK与DEF10%{passiveImg:up_g}\\n‧取得3个以上彩虹珠时回合结束时HP回复5%\", \"passiveSkillName\": \"肉体补足\", \"passiveSkillSetId\": 2995}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('142e6a9dfef14b58', 1011151, '巴达克', 7, '赛亚人的最终抗战', 100, '10', 40, 4, 140, 12684, 10159, 5827, 3333, '*基本效果*\n‧ATK与DEF130%{passiveImg:up_g}\n‧我方全体速与力属性的气力+3、ATK50%{passiveImg:up_g}\n*每次发动必杀技时*\n‧{passiveImg:forever}ATK与DEF40%{passiveImg:up_g}(最高80%)\n*HP70%以下*\n‧对全属性造成属性克制伤害', 1011152, '速与力属性的气力+3、HP、ATK、DEF提升90%', '2023-04-20 16:00:00', '{\"leaderSkill\": \"速与力属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011152, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF130%{passiveImg:up_g}\\n‧我方全体速与力属性的气力+3、ATK50%{passiveImg:up_g}\\n*每次发动必杀技时*\\n‧{passiveImg:forever}ATK与DEF40%{passiveImg:up_g}(最高80%)\\n*HP70%以下*\\n‧对全属性造成属性克制伤害\", \"passiveSkillName\": \"闪耀于黑暗的光芒\", \"passiveSkillSetId\": 3333}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
