INSERT INTO `eza_card` VALUES ('1d3e798a23fd4a37', 4014771, '超级赛亚人2孙悟空', 7, '热烈震荡的力量', 100, '10', 58, 4, 140, 14182, 16019, 7154, 2506, '*基本效果*\n‧ATK与DEF120%{passiveImg:up_g}\n‧伤害减轻率22%{passiveImg:up_g}\n*攻击极系的敌人后*\n‧气力+3\n‧ATK20%{passiveImg:up_g}\n‧DEF30%{passiveImg:up_g}\n*下一个进攻回合起*\n‧进行变身', 1014761, '超系的气力+3、HP、ATK、DEF提升130%', NULL, '{\"leaderSkill\": \"超系的气力+3、HP、ATK、DEF提升130%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1014761, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF120%{passiveImg:up_g}\\n‧伤害减轻率22%{passiveImg:up_g}\\n*攻击极系的敌人后*\\n‧气力+3\\n‧ATK20%{passiveImg:up_g}\\n‧DEF30%{passiveImg:up_g}\\n*下一个进攻回合起*\\n‧进行变身\", \"passiveSkillName\": \"超越超级赛亚人的超级赛亚人\", \"passiveSkillSetId\": 2506}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('1ddccf4f1b7a4942', 1021481, '人造人17号(第7宇宙队伍)', 3, '第7宇宙的总体战', 100, '12', 77, 5, 150, 19025, 16040, 8063, 4189, '*基本效果*\n‧ATK与DEF177%{passiveImg:up_g}\n‧取得彩虹珠时气力再+3\n*队伍里每多1名「第7宇宙代表」类别的角色*\n‧气力+1(最高+5)\n‧伤害减轻率与发动奋力一击的机率7%{passiveImg:up_g}(最高35%)\n*队伍里有5名以上「第7宇宙代表」类别的角色时*\n‧ATK与DEF77%{passiveImg:up_g}\n‧伤害减轻率与发动奋力一击的机率17%{passiveImg:up_g}\n*HP77%以下*\n‧{passiveImg:once}随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\n*气力值17以上攻击时*\n‧ATK与DEF77%{passiveImg:up_g}\n*气力值22以上攻击时*\n‧ATK与DEF77%{passiveImg:up_g}\n‧追加发动必杀技\n*每取得1个彩虹珠*\n‧发动奋力一击的机率7%{passiveImg:up_g}\n‧除自身以外的我方全体的气力+1、ATK与DEF7%{passiveImg:up_g}', 1021481, '「第7宇宙代表」类别的\n气力+4、HP、ATK、DEF提升170%，\n或是超知属性的气力+4、HP、ATK、DEF提升100%', '2024-08-07 16:00:00', '{\"leaderSkill\": \"「第7宇宙代表」类别的\\n气力+4、HP、ATK、DEF提升170%，\\n或是超知属性的气力+4、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1021481, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF177%{passiveImg:up_g}\\n‧取得彩虹珠时气力再+3\\n*队伍里每多1名「第7宇宙代表」类别的角色*\\n‧气力+1(最高+5)\\n‧伤害减轻率与发动奋力一击的机率7%{passiveImg:up_g}(最高35%)\\n*队伍里有5名以上「第7宇宙代表」类别的角色时*\\n‧ATK与DEF77%{passiveImg:up_g}\\n‧伤害减轻率与发动奋力一击的机率17%{passiveImg:up_g}\\n*HP77%以下*\\n‧{passiveImg:once}随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\\n*气力值17以上攻击时*\\n‧ATK与DEF77%{passiveImg:up_g}\\n*气力值22以上攻击时*\\n‧ATK与DEF77%{passiveImg:up_g}\\n‧追加发动必杀技\\n*每取得1个彩虹珠*\\n‧发动奋力一击的机率7%{passiveImg:up_g}\\n‧除自身以外的我方全体的气力+1、ATK与DEF7%{passiveImg:up_g}\", \"passiveSkillName\": \"像个人类\", \"passiveSkillSetId\": 4189}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
