INSERT INTO `eza_card` VALUES ('26effcb59aaa43fa', 1023241, '超级赛亚人神特南克斯(超宇宙)', 7, '守护时空的神战士', 100, '11', 40, 4, 140, 12535, 13191, 5023, 4328, '*队伍里每多1名「七龙珠英雄」或是「超越时空之人」\n类别的角色(以其中人数较多之类别计算)*\n‧气力+1、ATK与DEF50%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n‧超高机率发动奋力一击\n*参加攻击中的我方全体皆属于「七龙珠英雄」\n或是「超越时空之人」类别时*\n‧随机气珠变化：任一属性气珠→彩虹珠\n‧气力值12以上攻击时DEF50%{passiveImg:up_g}\n*我方全体皆属于「七龙珠英雄」或是「超越时空之人」类别时*\n‧必可发动2次追加攻击且高机率发动必杀技', 1023241, '「七龙珠英雄」类别的\n气力+4、HP、ATK、DEF提升180%', '2024-11-05 16:00:00', '{\"leaderSkill\": \"「七龙珠英雄」类别的\\n气力+4、HP、ATK、DEF提升180%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023241, \"passiveSkillDesc\": \"*队伍里每多1名「七龙珠英雄」或是「超越时空之人」\\n类别的角色(以其中人数较多之类别计算)*\\n‧气力+1、ATK与DEF50%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧超高机率发动奋力一击\\n*参加攻击中的我方全体皆属于「七龙珠英雄」\\n或是「超越时空之人」类别时*\\n‧随机气珠变化：任一属性气珠→彩虹珠\\n‧气力值12以上攻击时DEF50%{passiveImg:up_g}\\n*我方全体皆属于「七龙珠英雄」或是「超越时空之人」类别时*\\n‧必可发动2次追加攻击且高机率发动必杀技\", \"passiveSkillName\": \"神的守护者\", \"passiveSkillSetId\": 4328}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('27016d414eb84903', 1020771, '撒旦先生/魔人普乌(善)', 7, '好友的决断', 100, '10', 32, 4, 140, 10168, 10097, 5106, 2222, '*基本效果*\n‧中等机率回避敌人的攻击\n‧我方全体「魔人普乌篇」类别的气力+2、ATK与DEF20%{passiveImg:up_g}\n*HP40%以上*\n‧伤害减轻率40%{passiveImg:up_g}\n*战斗中受到5次以上攻击后*\n‧进入下一个进攻回合时与魔人普乌(善)交替', 1020772, '「魔人普乌篇」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是速属性的气力+3、HP、ATK、DEF提升50%', '2020-09-14 16:00:00', '{\"leaderSkill\": \"「魔人普乌篇」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是速属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020772, \"passiveSkillDesc\": \"*基本效果*\\n‧中等机率回避敌人的攻击\\n‧我方全体「魔人普乌篇」类别的气力+2、ATK与DEF20%{passiveImg:up_g}\\n*HP40%以上*\\n‧伤害减轻率40%{passiveImg:up_g}\\n*战斗中受到5次以上攻击后*\\n‧进入下一个进攻回合时与魔人普乌(善)交替\", \"passiveSkillName\": \"我的气势之力\", \"passiveSkillSetId\": 2222}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('27f234404abd4797', 1020651, '超级赛亚人4贝吉特(超宇宙)', 7, '贯穿一切的合体能量', 100, '14', 42, 4, 140, 18475, 16489, 6466, 3944, '*基本效果*\n‧ATK与DEF180%{passiveImg:up_g}\n‧我方全体「跨界」类别的气力+1、ATK与DEF30%{passiveImg:up_g}\n‧我方全体「巨猿力量」类别的气力+1、ATK与DEF30%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF60%{passiveImg:up_g}\n*队伍里每多1名「跨界」或是「巨猿力量」\n类别的角色(以其中人数较多之类别计算)*\n‧伤害减轻率5%{passiveImg:up_g}\n*受到敌人的必杀技攻击时*\n‧高机率使其无效，并以超绝大威力反击', 1020651, '「跨界」类别的\n气力+3、HP、ATK、DEF提升180%', '2023-11-21 16:00:00', '{\"leaderSkill\": \"「跨界」类别的\\n气力+3、HP、ATK、DEF提升180%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020651, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF180%{passiveImg:up_g}\\n‧我方全体「跨界」类别的气力+1、ATK与DEF30%{passiveImg:up_g}\\n‧我方全体「巨猿力量」类别的气力+1、ATK与DEF30%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF60%{passiveImg:up_g}\\n*队伍里每多1名「跨界」或是「巨猿力量」\\n类别的角色(以其中人数较多之类别计算)*\\n‧伤害减轻率5%{passiveImg:up_g}\\n*受到敌人的必杀技攻击时*\\n‧高机率使其无效，并以超绝大威力反击\", \"passiveSkillName\": \"最强的对抗手段\", \"passiveSkillSetId\": 3944}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('27f9259395614d84', 1008091, '魔人普乌(吸收终极悟饭后)', 8, '通往绝望的倒数计时', 200, '22', 48, 4, 140, 12532, 11876, 5056, 4506, '*基本效果*\n‧ATK与DEF200%{passiveImg:up_g}\n‧必可追加发动必杀技\n‧气珠变化：技气珠→彩虹珠\n‧回合结束时HP回复15%\n*气力值12以上攻击时*\n‧ATK与DEF200%{passiveImg:up_g}\n*战斗开始后第5回合起*\n‧随机气珠变化：技气珠以外的任一属性气珠→知气珠\n*每取得1个气珠*\n‧ATK40%{passiveImg:up_g}、DEF30%{passiveImg:up_g}\n‧HP回复12000\n*每取得1个彩虹珠*\n‧发动奋力一击的机率33%{passiveImg:up_g}\n‧伤害减轻率22%{passiveImg:up_g}(最高66%)\n*敌方有超系的角色时*\n‧ATK与DEF100%{passiveImg:up_g}\n‧除自身以外的我方全体的气力+3、ATK30%{passiveImg:up_g}\n*敌方有极系的角色时*\n‧ATK与DEF50%{passiveImg:up_g}\n‧除自身以外的我方全体的气力+2、ATK20%{passiveImg:up_g}', 1008091, '知属性的气力+4、HP、ATK、DEF提升100%', '2025-01-30 16:00:00', '{\"leaderSkill\": \"知属性的气力+4、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1008091, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧必可追加发动必杀技\\n‧气珠变化：技气珠→彩虹珠\\n‧回合结束时HP回复15%\\n*气力值12以上攻击时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n*战斗开始后第5回合起*\\n‧随机气珠变化：技气珠以外的任一属性气珠→知气珠\\n*每取得1个气珠*\\n‧ATK40%{passiveImg:up_g}、DEF30%{passiveImg:up_g}\\n‧HP回复12000\\n*每取得1个彩虹珠*\\n‧发动奋力一击的机率33%{passiveImg:up_g}\\n‧伤害减轻率22%{passiveImg:up_g}(最高66%)\\n*敌方有超系的角色时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧除自身以外的我方全体的气力+3、ATK30%{passiveImg:up_g}\\n*敌方有极系的角色时*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧除自身以外的我方全体的气力+2、ATK20%{passiveImg:up_g}\", \"passiveSkillName\": \"胜利就是一切\", \"passiveSkillSetId\": 4506}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
