INSERT INTO `eza_card` VALUES ('2f994910a84a4dd3', 1011641, '特南克斯(幼年期)&孙悟天(幼年期)', 4, '希望之星', 100, '10', 77, 5, 150, 14988, 16040, 10081, 4679, '*基本效果*\n‧气力随机+5～10\n‧ATK与DEF250%{passiveImg:up_g}\n‧高机率回避敌人的攻击\n*气力值12以上攻击时*\n‧ATK与DEF200%{passiveImg:up_g}\n‧高机率使ATK100%{passiveImg:up_g}\n*气力值18以上攻击时*\n‧ATK100%{passiveImg:up_g}\n‧高机率发动奋力一击\n*每次发动必杀技时*\n‧{passiveImg:forever}ATK与DEF77%{passiveImg:up_g}(最高200%)\n*队伍里有3名以上\n「少年、少女」类别的角色时*\n‧气珠变化：力气珠→速气珠\n‧我方全体的发动奋力一击的机率10%{passiveImg:up_g}\n*队伍里有3名以上\n「混血赛亚人」类别的角色时*\n‧气珠变化：技气珠→彩虹珠\n‧我方全体的发动奋力一击的机率10%{passiveImg:up_g}\n*参加攻击中的我方全体皆属于超系时*\n‧ATK与DEF150%{passiveImg:up_g}\n‧回避率27%{passiveImg:up_g}\n*参加攻击中的我方有极系的角色时*\n‧ATK200%{passiveImg:up_g}、DEF100%{passiveImg:up_g}\n‧发动奋力一击的机率27%{passiveImg:up_g}', 1011641, '超速属性的气力+4、HP、ATK、DEF提升120% & \n极速属性的气力+3、HP、ATK、DEF提升90%', '2025-08-07 16:00:00', '{\"leaderSkill\": \"超速属性的气力+4、HP、ATK、DEF提升120% & \\n极速属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011641, \"passiveSkillDesc\": \"*基本效果*\\n‧气力随机+5～10\\n‧ATK与DEF250%{passiveImg:up_g}\\n‧高机率回避敌人的攻击\\n*气力值12以上攻击时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧高机率使ATK100%{passiveImg:up_g}\\n*气力值18以上攻击时*\\n‧ATK100%{passiveImg:up_g}\\n‧高机率发动奋力一击\\n*每次发动必杀技时*\\n‧{passiveImg:forever}ATK与DEF77%{passiveImg:up_g}(最高200%)\\n*队伍里有3名以上\\n「少年、少女」类别的角色时*\\n‧气珠变化：力气珠→速气珠\\n‧我方全体的发动奋力一击的机率10%{passiveImg:up_g}\\n*队伍里有3名以上\\n「混血赛亚人」类别的角色时*\\n‧气珠变化：技气珠→彩虹珠\\n‧我方全体的发动奋力一击的机率10%{passiveImg:up_g}\\n*参加攻击中的我方全体皆属于超系时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧回避率27%{passiveImg:up_g}\\n*参加攻击中的我方有极系的角色时*\\n‧ATK200%{passiveImg:up_g}、DEF100%{passiveImg:up_g}\\n‧发动奋力一击的机率27%{passiveImg:up_g}\", \"passiveSkillName\": \"背负的希望\", \"passiveSkillSetId\": 4679}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
