INSERT INTO `eza_card` VALUES ('30863cfb266348d7', 1014741, '人造人16号', 7, '新的身体与觉悟', 100, '11', 42, 4, 140, 12155, 10628, 6411, 2629, '*基本效果*\n‧ATK与DEF100%{passiveImg:up_g}\n‧高机率防御所有攻击\n*队伍里每多1名「人造人」类别的角色*\n‧DEF40%{passiveImg:up_g}(最高160%)\n*每次防御成功时*\n‧{passiveImg:forever}ATK16%{passiveImg:up_g}(最高80%)', 1014741, '超技属性的气力+3、HP、ATK、DEF提升110%', '2021-11-24 16:00:00', '{\"leaderSkill\": \"超技属性的气力+3、HP、ATK、DEF提升110%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1014741, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧高机率防御所有攻击\\n*队伍里每多1名「人造人」类别的角色*\\n‧DEF40%{passiveImg:up_g}(最高160%)\\n*每次防御成功时*\\n‧{passiveImg:forever}ATK16%{passiveImg:up_g}(最高80%)\", \"passiveSkillName\": \"屹立不摇的精神\", \"passiveSkillSetId\": 2629}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
