INSERT INTO `eza_card` VALUES ('316073870c43438f', 1020751, '达列斯军团', 3, '宇宙第一的破坏者', 200, '23', 77, 5, 150, 18175, 15230, 9125, 4218, '*基本效果*\n‧ATK与DEF180%{passiveImg:up_g}\n‧我方全体「恐怖的征服者」或是「行星破坏」\n类别的气力+3、ATK与DEF50%{passiveImg:up_g}\n*队伍里每多1名「恐怖的征服者」或是「行星破坏」\n类别的角色(以其中人数较多之类别计算)*\n‧气力+1(最高+5)\n‧ATK10%{passiveImg:up_g}(最高50%)\n‧伤害减轻率10%{passiveImg:up_g}(最高50%)\n*气力值12以上攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n‧敌方有「地球长大的战士」类别的角色时，ATK再50%{passiveImg:up_g}\n*攻击时目标的状态：{passiveImg:atk_down}或是{passiveImg:stun}*\n‧气力+6\n‧对全属性造成属性克制伤害\n*气力值20以上攻击时*\n‧对全属性造成属性克制伤害\n*气力值24攻击时*\n‧必可发动奋力一击\n‧追加发动必杀技', 1020751, '「恐怖的征服者」类别的\n气力+4、HP、ATK、DEF提升150%，\n或是极力属性的气力+4、HP、ATK、DEF提升100%', '2024-08-22 16:00:00', '{\"leaderSkill\": \"「恐怖的征服者」类别的\\n气力+4、HP、ATK、DEF提升150%，\\n或是极力属性的气力+4、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020751, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF180%{passiveImg:up_g}\\n‧我方全体「恐怖的征服者」或是「行星破坏」\\n类别的气力+3、ATK与DEF50%{passiveImg:up_g}\\n*队伍里每多1名「恐怖的征服者」或是「行星破坏」\\n类别的角色(以其中人数较多之类别计算)*\\n‧气力+1(最高+5)\\n‧ATK10%{passiveImg:up_g}(最高50%)\\n‧伤害减轻率10%{passiveImg:up_g}(最高50%)\\n*气力值12以上攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧敌方有「地球长大的战士」类别的角色时，ATK再50%{passiveImg:up_g}\\n*攻击时目标的状态：{passiveImg:atk_down}或是{passiveImg:stun}*\\n‧气力+6\\n‧对全属性造成属性克制伤害\\n*气力值20以上攻击时*\\n‧对全属性造成属性克制伤害\\n*气力值24攻击时*\\n‧必可发动奋力一击\\n‧追加发动必杀技\", \"passiveSkillName\": \"超级战斗集团\", \"passiveSkillSetId\": 4218}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
