INSERT INTO `eza_card` VALUES ('323cb3908d144114', 4018131, '超级赛亚人孙悟饭(未来)', 7, '正义与勇气的战士', 100, '12', 58, 4, 140, 17292, 16936, 6459, 3579, '*基本效果*\n‧气力+3、ATK与DEF158%{passiveImg:up_g}\n‧伤害减轻率58%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF58%{passiveImg:up_g}\n*参加攻击中的我方每多1名「师徒的羁绊」类别的角色*\n‧气力+1、ATK与DEF40%{passiveImg:up_g}\n*参加攻击中的我方有名称含有「特南克斯」\n的角色时(不包含幼年期、GT)*\n‧必可发动追加攻击且高机率发动必杀技\n*敌方有「人造人」或是「未来篇」类别的角色时*\n‧必可追加发动必杀技', 1018121, '「师徒的羁绊」或是「混血赛亚人」类别的\n气力+3、HP、ATK、DEF提升170%', NULL, '{\"leaderSkill\": \"「师徒的羁绊」或是「混血赛亚人」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1018121, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3、ATK与DEF158%{passiveImg:up_g}\\n‧伤害减轻率58%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF58%{passiveImg:up_g}\\n*参加攻击中的我方每多1名「师徒的羁绊」类别的角色*\\n‧气力+1、ATK与DEF40%{passiveImg:up_g}\\n*参加攻击中的我方有名称含有「特南克斯」\\n的角色时(不包含幼年期、GT)*\\n‧必可发动追加攻击且高机率发动必杀技\\n*敌方有「人造人」或是「未来篇」类别的角色时*\\n‧必可追加发动必杀技\", \"passiveSkillName\": \"对人造人的愤怒\", \"passiveSkillSetId\": 3579}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
