INSERT INTO `eza_card` VALUES ('3283dc0ba18547ac', 4017641, '超级赛亚人2孙悟饭(少年期)', 3, '苏醒的真正力量', 100, '10', 77, 5, 150, 18813, 16890, 7106, 3116, '*基本效果*\n‧ATK与DEF158%{passiveImg:up_g}\n‧取得气珠时气力再+1\n*登场后4回合内*\n‧气珠变化：技气珠→速气珠\n*每取得1个气珠*\n‧ATK20%{passiveImg:up_g}\n‧DEF10%{passiveImg:up_g}\n*只有1名敌人时*\n‧随机气珠变化：速气珠与技气珠以外的任一属性气珠→彩虹珠\n*攻击时敌人有2名以上时*\n‧追加发动必杀技\n*HP58%以下*\n‧高机率追加发动必杀技\n‧高机率发动奋力一击\n*参加攻击中的我方有「超级赛亚人孙悟空」时*\n‧气力值18以上攻击时ATK59%{passiveImg:up_g}，\n若HP为59%以上，追加发动必杀技', 1017631, '「龟派气功」类别的气力+3、\nHP、ATK、DEF提升180%，\n或是超速属性的气力+3、\nHP、ATK、DEF提升130%', NULL, '{\"leaderSkill\": \"「龟派气功」类别的气力+3、\\nHP、ATK、DEF提升180%，\\n或是超速属性的气力+3、\\nHP、ATK、DEF提升130%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1017631, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF158%{passiveImg:up_g}\\n‧取得气珠时气力再+1\\n*登场后4回合内*\\n‧气珠变化：技气珠→速气珠\\n*每取得1个气珠*\\n‧ATK20%{passiveImg:up_g}\\n‧DEF10%{passiveImg:up_g}\\n*只有1名敌人时*\\n‧随机气珠变化：速气珠与技气珠以外的任一属性气珠→彩虹珠\\n*攻击时敌人有2名以上时*\\n‧追加发动必杀技\\n*HP58%以下*\\n‧高机率追加发动必杀技\\n‧高机率发动奋力一击\\n*参加攻击中的我方有「超级赛亚人孙悟空」时*\\n‧气力值18以上攻击时ATK59%{passiveImg:up_g}，\\n若HP为59%以上，追加发动必杀技\", \"passiveSkillName\": \"爆碎\", \"passiveSkillSetId\": 3116}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
