INSERT INTO `eza_card` VALUES ('3ba7990d6c9d4e0b', 1022631, '超级赛亚人孙悟空', 3, '倾注所有愤怒的一击', 100, '12', 77, 5, 150, 16050, 16975, 8381, 4518, '*基本效果*\n‧气力+3、ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率20%{passiveImg:up_g}\n*每当回合开始时*\n‧{passiveImg:forever}气力+1(最高+3)\n*受到攻击后*\n‧4回合内追加发动必杀技\n*每次受到攻击时*\n‧{passiveImg:forever}气力+1(最高+3)\n‧{passiveImg:forever}ATK与DEF20%{passiveImg:up_g}(最高59%)\n*处于该回合第一顺位时*\n‧ATK59%{passiveImg:up_g}\n‧伤害减轻率30%{passiveImg:up_g}\n*处于该回合第二或是第三攻击顺位时*\n‧ATK100%{passiveImg:up_g}、追加发动必杀技\n*登场后6回合内*\n‧防御所有攻击\n*敌方有极系的角色时*\n‧ATK59%{passiveImg:up_g}\n‧高机率发动奋力一击\n*敌方有名称含有「弗力札」的角色时\n(不包含士兵)*\n‧必可发动奋力一击', 1022631, '「传说的存在」或是「超级赛亚人」类别的\n气力+3、HP、ATK、DEF提升180%', '2025-02-09 16:00:00', '{\"leaderSkill\": \"「传说的存在」或是「超级赛亚人」类别的\\n气力+3、HP、ATK、DEF提升180%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1022631, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3、ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率20%{passiveImg:up_g}\\n*每当回合开始时*\\n‧{passiveImg:forever}气力+1(最高+3)\\n*受到攻击后*\\n‧4回合内追加发动必杀技\\n*每次受到攻击时*\\n‧{passiveImg:forever}气力+1(最高+3)\\n‧{passiveImg:forever}ATK与DEF20%{passiveImg:up_g}(最高59%)\\n*处于该回合第一顺位时*\\n‧ATK59%{passiveImg:up_g}\\n‧伤害减轻率30%{passiveImg:up_g}\\n*处于该回合第二或是第三攻击顺位时*\\n‧ATK100%{passiveImg:up_g}、追加发动必杀技\\n*登场后6回合内*\\n‧防御所有攻击\\n*敌方有极系的角色时*\\n‧ATK59%{passiveImg:up_g}\\n‧高机率发动奋力一击\\n*敌方有名称含有「弗力札」的角色时\\n(不包含士兵)*\\n‧必可发动奋力一击\", \"passiveSkillName\": \"超级赛亚人的最终大激战\", \"passiveSkillSetId\": 4518}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
