INSERT INTO `eza_card` VALUES ('3c88920fdff047aa', 1023491, '魔人普乌(纯粹)', 7, '引导破灭的魔人', 200, '23', 58, 4, 140, 24273, 13989, 6653, 4493, '*基本效果*\n‧气力+3、ATK与DEF250%{passiveImg:up_g}\n‧必可发动追加攻击且高机率发动必杀技\n‧高机率发动奋力一击\n‧伤害减轻率20%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}ATK与DEF40%{passiveImg:up_g}(最高160%)\n*队伍里每多1名「魔人之力」或是「魔人普乌篇」\n类别的角色(以其中人数较多之类别计算)*\n‧ATK与DEF40%{passiveImg:up_g}(最高120%)\n‧伤害减轻率10%{passiveImg:up_g}(最高30%)\n*战斗中自身受到6次攻击前*\n‧DEF100%{passiveImg:up_g}\n‧伤害减轻率20%{passiveImg:up_g}\n*受到攻击后*\n‧回合结束时HP回复20%\n*登场后3回合内*\n‧受到敌人的格斗系必杀技攻击时使其无效\n*登场后第4回合起*\n‧受到敌人的格斗系必杀技攻击时超高机率使其无效', 1023491, '「赌上命运的战斗」或是「魔人普乌篇」类别的\n气力+3、HP、ATK、DEF提升170%', '2025-01-06 16:00:00', '{\"leaderSkill\": \"「赌上命运的战斗」或是「魔人普乌篇」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1023491, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3、ATK与DEF250%{passiveImg:up_g}\\n‧必可发动追加攻击且高机率发动必杀技\\n‧高机率发动奋力一击\\n‧伤害减轻率20%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}ATK与DEF40%{passiveImg:up_g}(最高160%)\\n*队伍里每多1名「魔人之力」或是「魔人普乌篇」\\n类别的角色(以其中人数较多之类别计算)*\\n‧ATK与DEF40%{passiveImg:up_g}(最高120%)\\n‧伤害减轻率10%{passiveImg:up_g}(最高30%)\\n*战斗中自身受到6次攻击前*\\n‧DEF100%{passiveImg:up_g}\\n‧伤害减轻率20%{passiveImg:up_g}\\n*受到攻击后*\\n‧回合结束时HP回复20%\\n*登场后3回合内*\\n‧受到敌人的格斗系必杀技攻击时使其无效\\n*登场后第4回合起*\\n‧受到敌人的格斗系必杀技攻击时超高机率使其无效\", \"passiveSkillName\": \"永无止尽的灾厄\", \"passiveSkillSetId\": 4493}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
