INSERT INTO `eza_card` VALUES ('3e549c02b17345c4', 1019141, '巴达克', 7, '怒涛汹涌的反击', 100, '10', 58, 4, 140, 16904, 15773, 8108, 4083, '*基本效果*\n‧气力+2、ATK与DEF150%{passiveImg:up_g}\n*攻击时*\n‧ATK50%{passiveImg:up_g}\n*队伍里每多1名「下级战士」类别的角色*\n‧ATK20%{passiveImg:up_g}(最高100%)\n‧伤害减轻率10%{passiveImg:up_g}(最高50%)\n*敌方有「最凶恶的一族」类别的角色时*\n‧ATK50%{passiveImg:up_g}\n‧对全属性造成属性克制伤害\n*参加攻击中的我方除了自己以外，有「下级战士」类别的角色时*\n‧必可发动追加攻击且高机率发动必杀技', 1019141, '「复仇」或是「下级战士」类别的\n气力+4、HP、ATK、DEF提升170%', '2024-06-06 16:00:00', '{\"leaderSkill\": \"「复仇」或是「下级战士」类别的\\n气力+4、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1019141, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2、ATK与DEF150%{passiveImg:up_g}\\n*攻击时*\\n‧ATK50%{passiveImg:up_g}\\n*队伍里每多1名「下级战士」类别的角色*\\n‧ATK20%{passiveImg:up_g}(最高100%)\\n‧伤害减轻率10%{passiveImg:up_g}(最高50%)\\n*敌方有「最凶恶的一族」类别的角色时*\\n‧ATK50%{passiveImg:up_g}\\n‧对全属性造成属性克制伤害\\n*参加攻击中的我方除了自己以外，有「下级战士」类别的角色时*\\n‧必可发动追加攻击且高机率发动必杀技\", \"passiveSkillName\": \"命中注定的对手\", \"passiveSkillSetId\": 4083}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('3e5ef53882b74806', 1023661, '比尔维斯', 7, '无边神力', 100, '14', 40, 4, 140, 12540, 11988, 6536, 2714, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n‧气珠变化：技气珠+知气珠→体气珠\n*取得3个以上气珠*\n‧我方全体「融合」或是「神次元」类别的ATK与DEF30%{passiveImg:up_g}\n*取得5个以上气珠*\n‧高机率回避敌人的攻击\n*取得7个以上气珠攻击时*\n‧ATK与DEF70%{passiveImg:up_g}', 1023661, '体属性的气力+3、HP、ATK、DEF提升100%', '2022-02-21 16:00:00', '{\"leaderSkill\": \"体属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023661, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧气珠变化：技气珠+知气珠→体气珠\\n*取得3个以上气珠*\\n‧我方全体「融合」或是「神次元」类别的ATK与DEF30%{passiveImg:up_g}\\n*取得5个以上气珠*\\n‧高机率回避敌人的攻击\\n*取得7个以上气珠攻击时*\\n‧ATK与DEF70%{passiveImg:up_g}\", \"passiveSkillName\": \"镇抚\", \"passiveSkillSetId\": 2714}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
