INSERT INTO `eza_card` VALUES ('423141f04f7c4d07', 1010971, '克林', 7, '充满创意的战线回归', 100, '11', 42, 4, 140, 11818, 10285, 6858, 3021, '*基本效果*\n‧我方全体技属性的气力+2、ATK与DEF30%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF120%{passiveImg:up_g}\n*取得3个以上气珠*\n‧ATK与DEF30%{passiveImg:up_g}\n‧回合结束时HP回复10%\n*取得5个以上气珠*\n‧ATK与DEF50%{passiveImg:up_g}\n*取得3个以上技气珠*\n‧我方全体技属性的ATK与DEF10%{passiveImg:up_g}', 1010972, '技属性的气力+3、HP、ATK、DEF提升90%', '2023-02-07 16:00:00', '{\"leaderSkill\": \"技属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1010972, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体技属性的气力+2、ATK与DEF30%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF120%{passiveImg:up_g}\\n*取得3个以上气珠*\\n‧ATK与DEF30%{passiveImg:up_g}\\n‧回合结束时HP回复10%\\n*取得5个以上气珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n*取得3个以上技气珠*\\n‧我方全体技属性的ATK与DEF10%{passiveImg:up_g}\", \"passiveSkillName\": \"关键时刻的活跃\", \"passiveSkillSetId\": 3021}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('42c23c44ea934bd6', 1025801, '亚姆', 7, '地球顶尖的精锐', 100, '12', 58, 4, 140, 19425, 14532, 8398, 4631, '*自身登场时，我方队伍除了自己以外，\n有「地球长大的战士」类别的角色时，\n发动登场时动画*\n‧{passiveImg:once}1回合内回避率20%{passiveImg:up_g}\n‧{passiveImg:once}5回合内气力+3、ATK与DEF200%{passiveImg:up_g}\n*基本效果*\n‧气力+3、ATK与DEF200%{passiveImg:up_g}\n‧高机率发动奋力一击\n‧高机率回避敌人的攻击\n‧必可发动追加攻击且超高机率发动必杀技\n‧随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\n*每取得1个彩虹珠*\n‧发动攻击前DEF40%{passiveImg:up_g}、回避率10%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}ATK与DEF40%{passiveImg:up_g}(最高200%)\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\n*成功回避敌人的攻击后*\n‧该回合必可发动2次追加攻击且高机率发动必杀技\n*处于该回合第二或是第三攻击顺位时*\n‧必可发动追加攻击且高机率发动必杀技\n*每次发动必杀技时*\n‧该回合回避率10%{passiveImg:up_g}', 1025801, '「地球长大的战士」或是「赛亚人篇」\n类别的气力+3、HP、ATK、DEF提升170%，\n若有包含「地球人」或是「龟仙流」类别，\n气力再+1、HP、ATK、DEF再提升30%', '2025-06-18 16:00:00', '{\"leaderSkill\": \"「地球长大的战士」或是「赛亚人篇」\\n类别的气力+3、HP、ATK、DEF提升170%，\\n若有包含「地球人」或是「龟仙流」类别，\\n气力再+1、HP、ATK、DEF再提升30%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1025801, \"passiveSkillDesc\": \"*自身登场时，我方队伍除了自己以外，\\n有「地球长大的战士」类别的角色时，\\n发动登场时动画*\\n‧{passiveImg:once}1回合内回避率20%{passiveImg:up_g}\\n‧{passiveImg:once}5回合内气力+3、ATK与DEF200%{passiveImg:up_g}\\n*基本效果*\\n‧气力+3、ATK与DEF200%{passiveImg:up_g}\\n‧高机率发动奋力一击\\n‧高机率回避敌人的攻击\\n‧必可发动追加攻击且超高机率发动必杀技\\n‧随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\\n*每取得1个彩虹珠*\\n‧发动攻击前DEF40%{passiveImg:up_g}、回避率10%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}ATK与DEF40%{passiveImg:up_g}(最高200%)\\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\\n*成功回避敌人的攻击后*\\n‧该回合必可发动2次追加攻击且高机率发动必杀技\\n*处于该回合第二或是第三攻击顺位时*\\n‧必可发动追加攻击且高机率发动必杀技\\n*每次发动必杀技时*\\n‧该回合回避率10%{passiveImg:up_g}\", \"passiveSkillName\": \"操气爆发\", \"passiveSkillSetId\": 4631}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('445182bf8b4d445e', 1008871, '超级赛亚人特南克斯(未来)', 7, '人类的希望', 100, '11', 42, 4, 140, 11035, 10904, 6089, 2644, '*基本效果*\n‧ATK与DEF80%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK80%{passiveImg:up_g}\n*只有1名敌人时*\n‧ATK与DEF80%{passiveImg:up_g}\n*敌人有2名以上时*\n‧DEF160%{passiveImg:up_g}\n‧中等机率防御所有攻击', 1008871, '全属性的气力+3、HP、ATK、DEF提升60%', '2022-02-28 16:00:00', '{\"leaderSkill\": \"全属性的气力+3、HP、ATK、DEF提升60%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1008871, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF80%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK80%{passiveImg:up_g}\\n*只有1名敌人时*\\n‧ATK与DEF80%{passiveImg:up_g}\\n*敌人有2名以上时*\\n‧DEF160%{passiveImg:up_g}\\n‧中等机率防御所有攻击\", \"passiveSkillName\": \"反击之刃\", \"passiveSkillSetId\": 2644}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
