INSERT INTO `eza_card` VALUES ('44edd5954a5d4bf1', 1005051, '超级邪念波', 8, '地狱的罗刹鬼', 200, '22', 42, 4, 140, 9215, 11685, 4495, 4504, '*基本效果*\n‧气力+2\n‧ATK与DEF200%{passiveImg:up_g}\n‧防御所有攻击\n‧高机率回避敌人的攻击\n*自身发动攻击前*\n‧回避率20%{passiveImg:up_g}\n*处于该回合第一或是第三顺位并取得气珠时*\n‧回避率20%{passiveImg:up_g}\n‧我方全体的气力+2、DEF40%{passiveImg:up_g}\n*受到攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n*每次受到攻击或是回避敌人的攻击时*\n‧{passiveImg:forever}ATK50%{passiveImg:up_g}(最高200%)\n*成功回避敌人的攻击后*\n‧4回合内必可追加发动必杀技\n*敌方有超系的角色时*\n‧DEF200%{passiveImg:up_g}\n‧对全属性造成属性克制伤害\n*敌方有极系的角色时*\n‧DEF100%{passiveImg:up_g}\n‧超高机率对全属性造成属性克制伤害', 1005051, '知属性的气力+3、HP、ATK、DEF提升90%', '2025-02-04 16:00:00', '{\"leaderSkill\": \"知属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1005051, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧防御所有攻击\\n‧高机率回避敌人的攻击\\n*自身发动攻击前*\\n‧回避率20%{passiveImg:up_g}\\n*处于该回合第一或是第三顺位并取得气珠时*\\n‧回避率20%{passiveImg:up_g}\\n‧我方全体的气力+2、DEF40%{passiveImg:up_g}\\n*受到攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*每次受到攻击或是回避敌人的攻击时*\\n‧{passiveImg:forever}ATK50%{passiveImg:up_g}(最高200%)\\n*成功回避敌人的攻击后*\\n‧4回合内必可追加发动必杀技\\n*敌方有超系的角色时*\\n‧DEF200%{passiveImg:up_g}\\n‧对全属性造成属性克制伤害\\n*敌方有极系的角色时*\\n‧DEF100%{passiveImg:up_g}\\n‧超高机率对全属性造成属性克制伤害\", \"passiveSkillName\": \"空间的支配\", \"passiveSkillSetId\": 4504}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
