INSERT INTO `eza_card` VALUES ('458bcfa2f03243cd', 1015901, '魔人贝吉达', 7, '无法退让的胜负', 200, '23', 40, 4, 140, 10334, 12611, 5696, 2008, '*基本效果*\n‧气珠变化：速气珠→力气珠\n*每取得1个气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n‧敌方有「孙悟空的家谱」类别的角色时，ATK与DEF再5%{passiveImg:up_g}', 1015901, '「贝吉达的家谱」类别的\n气力+3、HP、ATK、DEF提升130%，\n或是力属性的气力+3、HP、ATK、DEF提升100%', '2020-05-14 16:00:00', '{\"leaderSkill\": \"「贝吉达的家谱」类别的\\n气力+3、HP、ATK、DEF提升130%，\\n或是力属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015901, \"passiveSkillDesc\": \"*基本效果*\\n‧气珠变化：速气珠→力气珠\\n*每取得1个气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n‧敌方有「孙悟空的家谱」类别的角色时，ATK与DEF再5%{passiveImg:up_g}\", \"passiveSkillName\": \"觉悟之力\", \"passiveSkillSetId\": 2008}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
