INSERT INTO `eza_card` VALUES ('45b60bb2d808426f', 1015471, '黑悟空', 7, '崇高美丽的巅峰', 200, '22', 58, 4, 140, 17345, 14764, 6138, 3854, '*基本效果*\n‧气力+2\n‧ATK与DEF80%{passiveImg:up_g}\n*每当回合开始时*\n‧{passiveImg:forever}ATK40%{passiveImg:up_g}(最高120%)\n‧{passiveImg:forever}DEF30%{passiveImg:up_g}(最高60%)\n*每次受到攻击时*\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高40%)\n*敌方有超系的角色时*\n‧必可发动2次追加攻击且高机率发动必杀技\n*战斗开始后第4回合起，HP60%以上*\n‧进行变身', 1015471, '「超越时空之人」类别的\n气力+3、HP、ATK、DEF提升170%，\n或是极知属性的气力+3、HP、ATK、DEF提升120%', '2023-09-21 16:00:00', '{\"leaderSkill\": \"「超越时空之人」类别的\\n气力+3、HP、ATK、DEF提升170%，\\n或是极知属性的气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1015471, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2\\n‧ATK与DEF80%{passiveImg:up_g}\\n*每当回合开始时*\\n‧{passiveImg:forever}ATK40%{passiveImg:up_g}(最高120%)\\n‧{passiveImg:forever}DEF30%{passiveImg:up_g}(最高60%)\\n*每次受到攻击时*\\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高40%)\\n*敌方有超系的角色时*\\n‧必可发动2次追加攻击且高机率发动必杀技\\n*战斗开始后第4回合起，HP60%以上*\\n‧进行变身\", \"passiveSkillName\": \"神的力量与赛亚人的力量\", \"passiveSkillSetId\": 3854}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
