INSERT INTO `eza_card` VALUES ('493e6a44c2c44969', 1008851, '黑悟空', 7, '漆黑的威胁', 200, '24', 48, 4, 140, 13995, 13091, 5960, 1504, '*基本效果*\n‧我方全体极系的气力+3\n*每取得1个气珠*\n‧ATK与DEF15%{passiveImg:up_g}\n*每次受到攻击时*\n‧{passiveImg:forever}气力+1(最高+5)\n*敌方有「孙悟空的家谱」类别的角色时*\n‧随机气珠变化：任一属性气珠→彩虹珠\n‧每取得1个气珠ATK与DEF5%{passiveImg:up_g}', 1008851, '体属性的气力+3、HP、ATK、DEF提升120%', '2019-11-24 16:00:00', '{\"leaderSkill\": \"体属性的气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1008851, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体极系的气力+3\\n*每取得1个气珠*\\n‧ATK与DEF15%{passiveImg:up_g}\\n*每次受到攻击时*\\n‧{passiveImg:forever}气力+1(最高+5)\\n*敌方有「孙悟空的家谱」类别的角色时*\\n‧随机气珠变化：任一属性气珠→彩虹珠\\n‧每取得1个气珠ATK与DEF5%{passiveImg:up_g}\", \"passiveSkillName\": \"战斗的手感\", \"passiveSkillSetId\": 1504}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('4a77a4ff54e94548', 1015211, '希特', 7, '因应强大而进化', 200, '23', 42, 4, 140, 14093, 12022, 7682, 4014, '*基本效果*\n‧我方全体力属性的气力+3、ATK与DEF10%{passiveImg:up_g}\n‧我方全体极力属性的ATK与DEF50%{passiveImg:up_g}\n‧随机气珠变化：力气珠以外的任一属性气珠→力气珠\n*每取得1个气珠*\n‧ATK与DEF50%{passiveImg:up_g}\n*每取得1个力气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n‧发动奋力一击的机率10%{passiveImg:up_g}\n*我方队伍除了自己以外，有2名以上极系的角色时*\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→力气珠\n*我方队伍除了自己以外，有3名以上力属性的角色时*\n‧登场后4回合内防御所有攻击', 1015211, '极力属性的气力+4、HP、ATK、DEF提升150%', '2024-04-11 16:00:00', '{\"leaderSkill\": \"极力属性的气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015211, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体力属性的气力+3、ATK与DEF10%{passiveImg:up_g}\\n‧我方全体极力属性的ATK与DEF50%{passiveImg:up_g}\\n‧随机气珠变化：力气珠以外的任一属性气珠→力气珠\\n*每取得1个气珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n*每取得1个力气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n‧发动奋力一击的机率10%{passiveImg:up_g}\\n*我方队伍除了自己以外，有2名以上极系的角色时*\\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→力气珠\\n*我方队伍除了自己以外，有3名以上力属性的角色时*\\n‧登场后4回合内防御所有攻击\", \"passiveSkillName\": \"进化带来的对抗\", \"passiveSkillSetId\": 4014}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
