INSERT INTO `eza_card` VALUES ('4f3c2646d90c4b6a', 1005441, '生化布罗利', 7, '恶魔的复活', 200, '21', 30, 4, 140, 10620, 9781, 5852, 4242, '*基本效果*\n‧气力+8\n‧ATK与DEF102%{passiveImg:up_g}\n‧伤害减轻率60%{passiveImg:up_g}\n*每经过2回合*\n‧{passiveImg:forever}气力-2(最高-6)\n‧{passiveImg:forever}伤害减轻率20%{passiveImg:down_r}(最高60%)\n*只有1名敌人时*\n‧伤害减轻率30%{passiveImg:up_g}\n*敌人有2名以上时*\n‧必可发动奋力一击\n*气力值12以上攻击时*\n‧ATK与DEF180%{passiveImg:up_g}\n*受到攻击后，下一个进攻回合起*\n‧{passiveImg:forever}回合开始时HP回复10%\n‧{passiveImg:forever}ATK100%{passiveImg:up_g}\n*登场后第10回合起*\n‧{passiveImg:once}ATK与DEF100%{passiveImg:up_g}\n‧{passiveImg:once}伤害减轻率40%{passiveImg:up_g}', 1005442, '「剧场版BOSS」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是技属性的气力+3、HP、ATK、DEF提升50%', '2024-09-19 16:00:00', '{\"leaderSkill\": \"「剧场版BOSS」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是技属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1005442, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+8\\n‧ATK与DEF102%{passiveImg:up_g}\\n‧伤害减轻率60%{passiveImg:up_g}\\n*每经过2回合*\\n‧{passiveImg:forever}气力-2(最高-6)\\n‧{passiveImg:forever}伤害减轻率20%{passiveImg:down_r}(最高60%)\\n*只有1名敌人时*\\n‧伤害减轻率30%{passiveImg:up_g}\\n*敌人有2名以上时*\\n‧必可发动奋力一击\\n*气力值12以上攻击时*\\n‧ATK与DEF180%{passiveImg:up_g}\\n*受到攻击后，下一个进攻回合起*\\n‧{passiveImg:forever}回合开始时HP回复10%\\n‧{passiveImg:forever}ATK100%{passiveImg:up_g}\\n*登场后第10回合起*\\n‧{passiveImg:once}ATK与DEF100%{passiveImg:up_g}\\n‧{passiveImg:once}伤害减轻率40%{passiveImg:up_g}\", \"passiveSkillName\": \"无差别破坏\", \"passiveSkillSetId\": 4242}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('4f42b27f6cea411c', 4022431, '超级赛亚人4悟吉达', 3, '究极力量的赛亚人战士', 100, '14', 77, 5, 150, 16688, 17185, 7425, 4523, '*基本效果*\n‧{passiveImg:once}1回合内伤害减轻率77%{passiveImg:up_g}\n‧ATK与DEF300%{passiveImg:up_g}\n‧取得气珠时气力再+2\n‧对全属性造成属性克制伤害\n‧防御所有攻击\n‧高机率发动奋力一击\n‧追加发动必杀技\n‧看穿敌方必杀技\n*登场后4回合内*\n‧随机气珠变化：任一属性气珠→彩虹珠\n*每取得1个气珠*\n‧ATK与DEF10%{passiveImg:up_g}(最高100%)\n*每取得1个彩虹珠*\n‧发动奋力一击的机率与伤害减轻率10%{passiveImg:up_g}\n*发动主动技能时，\n或是气力值24攻击时*\n‧ATK50%{passiveImg:up_g}\n*受到攻击时*\n‧{passiveImg:once}若自身的HP为50%以下，\n该回合伤害减轻率50%{passiveImg:up_g}\n*受到敌人的必杀技攻击时*\n‧超高机率使其无效，并以超绝大威力反击\n‧{passiveImg:once}若只有1名敌人且敌人的HP为50%以下，\n必可使其无效，并以超绝大威力反击', 1022421, '「融合/合体战士」或是「GT HERO」\n类别的气力+3、HP、ATK、DEF提升170%，\n若有包含「龟派气功」类别，\n气力再+1、HP、ATK、DEF再提升30%', NULL, '{\"leaderSkill\": \"「融合/合体战士」或是「GT HERO」\\n类别的气力+3、HP、ATK、DEF提升170%，\\n若有包含「龟派气功」类别，\\n气力再+1、HP、ATK、DEF再提升30%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1022421, \"passiveSkillDesc\": \"*基本效果*\\n‧{passiveImg:once}1回合内伤害减轻率77%{passiveImg:up_g}\\n‧ATK与DEF300%{passiveImg:up_g}\\n‧取得气珠时气力再+2\\n‧对全属性造成属性克制伤害\\n‧防御所有攻击\\n‧高机率发动奋力一击\\n‧追加发动必杀技\\n‧看穿敌方必杀技\\n*登场后4回合内*\\n‧随机气珠变化：任一属性气珠→彩虹珠\\n*每取得1个气珠*\\n‧ATK与DEF10%{passiveImg:up_g}(最高100%)\\n*每取得1个彩虹珠*\\n‧发动奋力一击的机率与伤害减轻率10%{passiveImg:up_g}\\n*发动主动技能时，\\n或是气力值24攻击时*\\n‧ATK50%{passiveImg:up_g}\\n*受到攻击时*\\n‧{passiveImg:once}若自身的HP为50%以下，\\n该回合伤害减轻率50%{passiveImg:up_g}\\n*受到敌人的必杀技攻击时*\\n‧超高机率使其无效，并以超绝大威力反击\\n‧{passiveImg:once}若只有1名敌人且敌人的HP为50%以下，\\n必可使其无效，并以超绝大威力反击\", \"passiveSkillName\": \"超级悟吉达诞生！\", \"passiveSkillSetId\": 4523}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('4f430565387b4047', 1026631, '机械桃白白', 7, '积累愤怒之砲击', 200, '23', 32, 4, 140, 11966, 11132, 6191, 3448, '*基本效果*\n‧气力+1\n‧ATK与DEF100%{passiveImg:up_g}\n‧超高机率使气力+1、ATK与DEF100%{passiveImg:up_g}\n*敌方有「龟仙流」类别的角色时*\n‧追加发动必杀技\n‧气力值9以上攻击时ATK与DEF50%{passiveImg:up_g}\n*攻击时目标的状态：{passiveImg:stun}或是{passiveImg:astute}*\n‧ATK50%{passiveImg:up_g}\n‧高机率发动奋力一击', 1026632, '力与速属性的气力+3、HP、ATK、DEF提升70%', '2023-04-27 16:00:00', '{\"leaderSkill\": \"力与速属性的气力+3、HP、ATK、DEF提升70%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1026632, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+1\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧超高机率使气力+1、ATK与DEF100%{passiveImg:up_g}\\n*敌方有「龟仙流」类别的角色时*\\n‧追加发动必杀技\\n‧气力值9以上攻击时ATK与DEF50%{passiveImg:up_g}\\n*攻击时目标的状态：{passiveImg:stun}或是{passiveImg:astute}*\\n‧ATK50%{passiveImg:up_g}\\n‧高机率发动奋力一击\", \"passiveSkillName\": \"无视规则的凶器\", \"passiveSkillSetId\": 3448}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
