INSERT INTO `eza_card` VALUES ('50091e4c88bb4fab', 1017261, '赛亚超人4号', 7, '拯救世界的英雄', 100, '13', 32, 4, 140, 9021, 10846, 4741, 3042, '*基本效果*\n‧ATK与DEF120%{passiveImg:up_g}\n‧我方全体超系的气力+2、DEF30%{passiveImg:up_g}\n‧我方全体「少年、少女」类别的ATK30%{passiveImg:up_g}\n‧高机率追加发动必杀技\n*攻击时*\n‧DEF30%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)', 1017262, '「少年、少女」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是超系的气力+3、HP、ATK、DEF提升40%', '2022-11-21 16:00:00', '{\"leaderSkill\": \"「少年、少女」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是超系的气力+3、HP、ATK、DEF提升40%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1017262, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF120%{passiveImg:up_g}\\n‧我方全体超系的气力+2、DEF30%{passiveImg:up_g}\\n‧我方全体「少年、少女」类别的ATK30%{passiveImg:up_g}\\n‧高机率追加发动必杀技\\n*攻击时*\\n‧DEF30%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\", \"passiveSkillName\": \"赤红身影的新英雄\", \"passiveSkillSetId\": 3042}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('5026b2428f944e12', 1015231, '潘(GT)', 7, '胜利的微笑', 100, '10', 42, 4, 140, 14996, 12203, 7005, 4016, '*基本效果*\n‧我方全体速属性的气力+3、ATK与DEF10%{passiveImg:up_g}\n‧我方全体超速属性的ATK与DEF50%{passiveImg:up_g}\n‧随机气珠变化：速气珠以外的任一属性气珠→速气珠\n*每取得1个气珠*\n‧ATK与DEF50%{passiveImg:up_g}\n*每取得1个速气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n‧发动奋力一击的机率10%{passiveImg:up_g}\n*我方队伍除了自己以外，有2名以上超系的角色时*\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→速气珠\n*我方队伍除了自己以外，有3名以上速属性的角色时*\n‧登场后4回合内防御所有攻击', 1015231, '超速属性的气力+4、HP、ATK、DEF提升150%', '2024-04-11 16:00:00', '{\"leaderSkill\": \"超速属性的气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015231, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体速属性的气力+3、ATK与DEF10%{passiveImg:up_g}\\n‧我方全体超速属性的ATK与DEF50%{passiveImg:up_g}\\n‧随机气珠变化：速气珠以外的任一属性气珠→速气珠\\n*每取得1个气珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n*每取得1个速气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n‧发动奋力一击的机率10%{passiveImg:up_g}\\n*我方队伍除了自己以外，有2名以上超系的角色时*\\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→速气珠\\n*我方队伍除了自己以外，有3名以上速属性的角色时*\\n‧登场后4回合内防御所有攻击\", \"passiveSkillName\": \"冒险的序曲\", \"passiveSkillSetId\": 4016}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
