INSERT INTO `eza_card` VALUES ('50da5b06794e4c48', 4020381, '魔人普乌(吸收终极悟饭后)', 3, '无敌的吸收型态', 200, '24', 77, 5, 150, 19663, 14975, 9656, 4038, '*基本效果*\n‧回合开始时HP回复20%\n‧气力+5、ATK与DEF250%{passiveImg:up_g}\n‧防御所有攻击\n‧高机率回避敌人的攻击\n‧必可追加发动必杀技\n‧取得气珠时气力再+2\n‧{passiveImg:once}封锁攻击过的敌人的必杀技5回合\n*登场后3回合内*\n‧必可追加发动必杀技\n*登场后5回合内*\n‧ATK与DEF50%{passiveImg:up_g}\n‧使气力值18以上攻击过的敌人行动中断\n*登场后第6回合起*\n‧ATK与DEF100%{passiveImg:up_g}\n*回合结束时HP50%以上*\n‧下次自身发动攻击时，暂时使ATK50%{passiveImg:up_g}\n*回合结束时HP50%以下*\n‧HP回复10%', 1020371, '「吸收力量」或是「魔人之力」类别的\n气力+4、HP、ATK、DEF提升180%', NULL, '{\"leaderSkill\": \"「吸收力量」或是「魔人之力」类别的\\n气力+4、HP、ATK、DEF提升180%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020371, \"passiveSkillDesc\": \"*基本效果*\\n‧回合开始时HP回复20%\\n‧气力+5、ATK与DEF250%{passiveImg:up_g}\\n‧防御所有攻击\\n‧高机率回避敌人的攻击\\n‧必可追加发动必杀技\\n‧取得气珠时气力再+2\\n‧{passiveImg:once}封锁攻击过的敌人的必杀技5回合\\n*登场后3回合内*\\n‧必可追加发动必杀技\\n*登场后5回合内*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧使气力值18以上攻击过的敌人行动中断\\n*登场后第6回合起*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*回合结束时HP50%以上*\\n‧下次自身发动攻击时，暂时使ATK50%{passiveImg:up_g}\\n*回合结束时HP50%以下*\\n‧HP回复10%\", \"passiveSkillName\": \"邪恶的可能性\", \"passiveSkillSetId\": 4038}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
