INSERT INTO `eza_card` VALUES ('59ba5dad8b04444d', 1009101, '克维拉(最终型态)', 7, '极恶的猛袭', 200, '21', 42, 4, 140, 12551, 10678, 6107, 2938, '*基本效果*\n‧气力+2\n‧ATK与DEF150%{passiveImg:up_g}\n‧必可发动追加攻击且中等机率发动必杀技\n*攻击时目标的状态：{passiveImg:stun}*\n‧超高机率发动奋力一击\n*每次发动必杀技时*\n‧{passiveImg:forever}ATK与DEF20%{passiveImg:up_g}(最高50%)\n*敌方有名称含有「孙悟空」的角色时(不包含少年期、奇纽、Jr.等)*\n‧{passiveImg:once}必可使攻击过的敌人晕眩', 1009101, '速、技、体属性的气力+3、HP、ATK、DEF提升80%', '2022-09-01 16:00:00', '{\"leaderSkill\": \"速、技、体属性的气力+3、HP、ATK、DEF提升80%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1009101, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧必可发动追加攻击且中等机率发动必杀技\\n*攻击时目标的状态：{passiveImg:stun}*\\n‧超高机率发动奋力一击\\n*每次发动必杀技时*\\n‧{passiveImg:forever}ATK与DEF20%{passiveImg:up_g}(最高50%)\\n*敌方有名称含有「孙悟空」的角色时(不包含少年期、奇纽、Jr.等)*\\n‧{passiveImg:once}必可使攻击过的敌人晕眩\", \"passiveSkillName\": \"宇宙最强宣言\", \"passiveSkillSetId\": 2938}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('59d31e0900374606', 1019171, '多达布', 7, '无尽的威力', 100, '10', 32, 4, 140, 6893, 9296, 4224, 2791, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n*只有1名敌人时*\n‧ATK与DEF100%{passiveImg:up_g}\n*敌人有2名以上时*\n‧必可追加发动必杀技\n*参加攻击中的我方除了自己以外，有「巴达克小队」类别的角色时*\n‧高机率发动奋力一击', 1019172, '「下级战士」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是速属性的气力+3、HP、ATK、DEF提升50%', '2022-05-30 16:00:00', '{\"leaderSkill\": \"「下级战士」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是速属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019172, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*只有1名敌人时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*敌人有2名以上时*\\n‧必可追加发动必杀技\\n*参加攻击中的我方除了自己以外，有「巴达克小队」类别的角色时*\\n‧高机率发动奋力一击\", \"passiveSkillName\": \"寡言的进击\", \"passiveSkillSetId\": 2791}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('59f0462a0e5241f0', 1019851, '达布尔', 7, '兄弟再会', 100, '10', 32, 4, 140, 11798, 9734, 6348, 2833, '*基本效果*\n‧ATK与DEF100%{passiveImg:up_g}\n‧气珠变化：力气珠→速气珠\n‧我方全体「亲手足的羁绊」类别的气力+2、ATK与DEF30%{passiveImg:up_g}\n*我方队伍除了自己以外，有2名以\n上「贝吉达的家谱」类别的角色时*\n‧回避率30%{passiveImg:up_g}\n*取得3个以上气珠*\n‧回避率5%{passiveImg:up_g}\n‧攻击时ATK与DEF50%{passiveImg:up_g}\n*取得5个以上气珠*\n‧回避率5%{passiveImg:up_g}\n‧攻击时ATK与DEF50%{passiveImg:up_g}', 1019852, '「亲手足的羁绊」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是全属性的气力+3、HP、ATK、DEF提升40%', '2022-08-14 16:00:00', '{\"leaderSkill\": \"「亲手足的羁绊」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是全属性的气力+3、HP、ATK、DEF提升40%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019852, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧气珠变化：力气珠→速气珠\\n‧我方全体「亲手足的羁绊」类别的气力+2、ATK与DEF30%{passiveImg:up_g}\\n*我方队伍除了自己以外，有2名以\\n上「贝吉达的家谱」类别的角色时*\\n‧回避率30%{passiveImg:up_g}\\n*取得3个以上气珠*\\n‧回避率5%{passiveImg:up_g}\\n‧攻击时ATK与DEF50%{passiveImg:up_g}\\n*取得5个以上气珠*\\n‧回避率5%{passiveImg:up_g}\\n‧攻击时ATK与DEF50%{passiveImg:up_g}\", \"passiveSkillName\": \"与哥哥联手\", \"passiveSkillSetId\": 2833}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('5ab8a5c080434a67', 1023361, '人造人17号(未来)&18号(未来)', 7, '夺命游戏', 200, '21', 58, 4, 140, 13995, 16626, 8496, 4768, '*基本效果*\n‧ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率17%{passiveImg:up_g}\n‧回避率18%{passiveImg:up_g}\n‧随机气珠变化：技气珠以外的任一属性气珠→技气珠\n‧取得技气珠或是彩虹珠时气力再+1\n‧追加发动必杀技\n*每取得1个气珠*\n‧ATK与DEF35%{passiveImg:up_g}\n*每取得1个技气珠*\n‧ATK18%{passiveImg:up_g}\n‧DEF17%{passiveImg:up_g}\n*取得2个以上技气珠，或是取得1个以上彩虹珠*\n‧发动奋力一击的机率、伤害减轻率、回避率35%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF150%{passiveImg:up_g}\n*HP35%以下*\n‧伤害减轻率17%{passiveImg:up_g}\n‧回避率18%{passiveImg:up_g}\n*受到敌人的气弹系必杀技攻击时*\n‧HP35%以上，或是取得7个以上气珠时使其无效\n‧取得8个以上气珠时，\n2回合内我方全体「人造人」类别的\nATK与DEF15%{passiveImg:up_g}', 1023361, '「世界的乱源」或是「未来篇」类别的\n气力+3、HP、ATK、DEF提升180%', '2025-12-01 16:00:00', '{\"leaderSkill\": \"「世界的乱源」或是「未来篇」类别的\\n气力+3、HP、ATK、DEF提升180%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1023361, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率17%{passiveImg:up_g}\\n‧回避率18%{passiveImg:up_g}\\n‧随机气珠变化：技气珠以外的任一属性气珠→技气珠\\n‧取得技气珠或是彩虹珠时气力再+1\\n‧追加发动必杀技\\n*每取得1个气珠*\\n‧ATK与DEF35%{passiveImg:up_g}\\n*每取得1个技气珠*\\n‧ATK18%{passiveImg:up_g}\\n‧DEF17%{passiveImg:up_g}\\n*取得2个以上技气珠，或是取得1个以上彩虹珠*\\n‧发动奋力一击的机率、伤害减轻率、回避率35%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*HP35%以下*\\n‧伤害减轻率17%{passiveImg:up_g}\\n‧回避率18%{passiveImg:up_g}\\n*受到敌人的气弹系必杀技攻击时*\\n‧HP35%以上，或是取得7个以上气珠时使其无效\\n‧取得8个以上气珠时，\\n2回合内我方全体「人造人」类别的\\nATK与DEF15%{passiveImg:up_g}\", \"passiveSkillName\": \"经年累月的期待\", \"passiveSkillSetId\": 4768}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
