INSERT INTO `eza_card` VALUES ('66336c288d1b4fa7', 1021621, '龟仙人', 3, '气势与执著的突破极限', 100, '14', 59, 5, 150, 13062, 13131, 7105, 2363, '*基本效果*\n‧DEF120%{passiveImg:up_g}\n‧中等机率回避敌人的攻击\n‧我方全体「龟仙流」类别的气力+3、ATK与DEF40%{passiveImg:up_g}\n*我方队伍除了自己以外，有2名以上「龟仙流」类别的角色，\n且HP50%以下时，参加攻击中的我方角色(包含自身)被KO*\n‧{passiveImg:once}复活并回复HP60%', 1021621, '「龟仙流」类别的\n气力+3、HP、ATK、DEF提升120%', '2021-07-29 16:00:00', '{\"leaderSkill\": \"「龟仙流」类别的\\n气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1021621, \"passiveSkillDesc\": \"*基本效果*\\n‧DEF120%{passiveImg:up_g}\\n‧中等机率回避敌人的攻击\\n‧我方全体「龟仙流」类别的气力+3、ATK与DEF40%{passiveImg:up_g}\\n*我方队伍除了自己以外，有2名以上「龟仙流」类别的角色，\\n且HP50%以下时，参加攻击中的我方角色(包含自身)被KO*\\n‧{passiveImg:once}复活并回复HP60%\", \"passiveSkillName\": \"师父与弟子\", \"passiveSkillSetId\": 2363}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
