INSERT INTO `eza_card` VALUES ('6cf5be8b17264398', 1009351, '黑悟空(超级赛亚人桃红)', 8, '身染蔷薇色的超级赛亚人', 200, '20', 48, 4, 140, 14038, 12416, 5845, 4655, '*基本效果*\n‧ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率20%{passiveImg:up_g}\n‧我方全体的气力+3、ATK与DEF30%{passiveImg:up_g}\n‧追加发动必杀技\n*受到攻击时*\n‧DEF200%{passiveImg:up_g}\n‧若HP为70%以下，DEF再100%{passiveImg:up_g}\n*每次受到攻击时*\n‧{passiveImg:forever}ATK60%{passiveImg:up_g}(最高300%)\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\n‧该回合伤害减轻率25%{passiveImg:up_g}(最高50%)\n*参加攻击中的我方全体皆属于极系时，\n或是参加攻击中的我方除了自己以外，\n有「未来篇」类别的角色时*\n‧防御所有攻击\n‧我方全体超系的发动奋力一击的机率20%{passiveImg:up_g}\n‧2回合内我方全体极系的发动奋力一击的机率20%{passiveImg:up_g}', 1009351, '极系的气力+4、HP、ATK、DEF提升80%', '2025-07-09 16:00:00', '{\"leaderSkill\": \"极系的气力+4、HP、ATK、DEF提升80%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1009351, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率20%{passiveImg:up_g}\\n‧我方全体的气力+3、ATK与DEF30%{passiveImg:up_g}\\n‧追加发动必杀技\\n*受到攻击时*\\n‧DEF200%{passiveImg:up_g}\\n‧若HP为70%以下，DEF再100%{passiveImg:up_g}\\n*每次受到攻击时*\\n‧{passiveImg:forever}ATK60%{passiveImg:up_g}(最高300%)\\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\\n‧该回合伤害减轻率25%{passiveImg:up_g}(最高50%)\\n*参加攻击中的我方全体皆属于极系时，\\n或是参加攻击中的我方除了自己以外，\\n有「未来篇」类别的角色时*\\n‧防御所有攻击\\n‧我方全体超系的发动奋力一击的机率20%{passiveImg:up_g}\\n‧2回合内我方全体极系的发动奋力一击的机率20%{passiveImg:up_g}\", \"passiveSkillName\": \"力量的熟练\", \"passiveSkillSetId\": 4655}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
