INSERT INTO `eza_card` VALUES ('6f73d326f83f4ede', 4015061, '魔人普乌(吸收终极悟饭后)', 7, '惊人的吸收能力', 200, '23', 58, 4, 140, 17172, 14625, 6399, 3348, '*基本效果*\n‧回合开始时HP回复12%\n‧气力+2\n‧ATK与DEF180%{passiveImg:up_g}\n*剩余HP越多*\n‧DEF{passiveImg:up_g}(最高120%)\n*攻击时*\n‧ATK80%{passiveImg:up_g}\n*登场后6回合内*\n‧必可发动追加攻击且高机率发动必杀技\n‧超高机率防御所有攻击\n*登场后第7回合起*\n‧高机率防御所有攻击', 1015051, '「变身强化」类别的气力+3、\nHP、ATK、DEF提升170%，\n或是极力属性的气力+3、HP、ATK、DEF提升120%', NULL, '{\"leaderSkill\": \"「变身强化」类别的气力+3、\\nHP、ATK、DEF提升170%，\\n或是极力属性的气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015051, \"passiveSkillDesc\": \"*基本效果*\\n‧回合开始时HP回复12%\\n‧气力+2\\n‧ATK与DEF180%{passiveImg:up_g}\\n*剩余HP越多*\\n‧DEF{passiveImg:up_g}(最高120%)\\n*攻击时*\\n‧ATK80%{passiveImg:up_g}\\n*登场后6回合内*\\n‧必可发动追加攻击且高机率发动必杀技\\n‧超高机率防御所有攻击\\n*登场后第7回合起*\\n‧高机率防御所有攻击\", \"passiveSkillName\": \"以防万一的措施\", \"passiveSkillSetId\": 3348}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('6fe398c1ba2e4235', 1022681, '玛卡莉塔', 7, '正义的宇宙指导者', 100, '10', 18, 4, 140, 10351, 11694, 6257, 4215, '*基本效果*\n‧ATK与DEF110%{passiveImg:up_g}\n‧高机率回避敌人的攻击\n‧我方全体「第11宇宙」类别的气力+3、ATK与DEF50%{passiveImg:up_g}\n‧我方全体「神次元」、「亲手足的羁绊」、\n「师徒的羁绊」类别的ATK与DEF20%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}ATK与DEF55%{passiveImg:up_g}(最高110%)\n*参加攻击中的我方除自身以外，有「第11宇宙」\n或是「师徒的羁绊」类别的角色时*\n‧回避率20%{passiveImg:up_g}\n‧随机气珠变化：任一属性气珠→彩虹珠\n*参加攻击中的我方全体皆属于「第11宇宙」类别时*\n‧伤害减轻率30%{passiveImg:up_g}\n‧{passiveImg:once}处于该回合第三顺位时我方全体的伤害减轻率11%{passiveImg:up_g}', 1022681, '「第11宇宙」类别的\n气力+3、HP、ATK、DEF提升150%', '2024-10-27 16:00:00', '{\"leaderSkill\": \"「第11宇宙」类别的\\n气力+3、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1022681, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF110%{passiveImg:up_g}\\n‧高机率回避敌人的攻击\\n‧我方全体「第11宇宙」类别的气力+3、ATK与DEF50%{passiveImg:up_g}\\n‧我方全体「神次元」、「亲手足的羁绊」、\\n「师徒的羁绊」类别的ATK与DEF20%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}ATK与DEF55%{passiveImg:up_g}(最高110%)\\n*参加攻击中的我方除自身以外，有「第11宇宙」\\n或是「师徒的羁绊」类别的角色时*\\n‧回避率20%{passiveImg:up_g}\\n‧随机气珠变化：任一属性气珠→彩虹珠\\n*参加攻击中的我方全体皆属于「第11宇宙」类别时*\\n‧伤害减轻率30%{passiveImg:up_g}\\n‧{passiveImg:once}处于该回合第三顺位时我方全体的伤害减轻率11%{passiveImg:up_g}\", \"passiveSkillName\": \"玛卡莉塔的劝告\", \"passiveSkillSetId\": 4215}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('701fdfa65a324619', 1015101, '撒旦先生', 7, '宇宙第一的毅力', 100, '12', 40, 4, 140, 15004, 8051, 8208, 4113, '*基本效果*\n‧高机率回避敌人的攻击\n*HP50%以上*\n‧回避率10%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF150%{passiveImg:up_g}\n*剩余HP越少*\n‧伤害减轻率{passiveImg:up_g}(50%～90%)\n*参加攻击中的我方除自身以外，每\n多1名「魔人普乌篇」类别的角色*\n‧ATK与DEF50%{passiveImg:up_g}\n‧敌方全体的ATK与DEF10%{passiveImg:down_y}', 1015101, '超知属性的气力+3、HP、ATK、DEF提升110%', '2024-05-13 16:00:00', '{\"leaderSkill\": \"超知属性的气力+3、HP、ATK、DEF提升110%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015101, \"passiveSkillDesc\": \"*基本效果*\\n‧高机率回避敌人的攻击\\n*HP50%以上*\\n‧回避率10%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*剩余HP越少*\\n‧伤害减轻率{passiveImg:up_g}(50%～90%)\\n*参加攻击中的我方除自身以外，每\\n多1名「魔人普乌篇」类别的角色*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧敌方全体的ATK与DEF10%{passiveImg:down_y}\", \"passiveSkillName\": \"王者的强运\", \"passiveSkillSetId\": 4113}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('70dc609c3e2646ab', 4023121, '超级赛亚人特南克斯(青年期)', 7, '改变命运的使者', 100, '10', 58, 4, 140, 16128, 16548, 7526, 4811, '*基本效果*\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\n‧超高机率发动奋力一击\n‧必可发动追加攻击且超高机率发动必杀技\n‧超高机率发动追加攻击且超高机率发动必杀技\n‧气珠变化：体气珠→速气珠\n‧高机率回避敌人的攻击\n‧超高机率使攻击过的敌人晕眩2回合\n*取得速气珠时*\n‧追加发动必杀技\n*取得速气珠以外的属性气珠时*\n‧超高机率发动追加攻击且高机率发动必杀技\n‧高机率发动追加攻击且超高机率发动必杀技\n*气力值12以上攻击时*\n‧ATK与DEF200%{passiveImg:up_g}\n‧{passiveImg:once}必可发动奋力一击\n*每次发动攻击时*\n‧该回合回避率5%{passiveImg:up_g}\n*每次发动必杀技时*\n‧该回合回避率5%{passiveImg:up_g}\n*受到攻击时*\n‧DEF200%{passiveImg:up_g}\n*我方队伍除了自己以外，\n有「被托付的意志」或是「人造人/赛鲁篇」类别的角色时*\n‧我方全体的气力+2、ATK与DEF60%{passiveImg:up_g}', 1023111, '「被托付的意志」或是「人造人/赛鲁篇」类别的\n气力+3、HP、ATK、DEF提升170%', NULL, '{\"leaderSkill\": \"「被托付的意志」或是「人造人/赛鲁篇」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023111, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\\n‧超高机率发动奋力一击\\n‧必可发动追加攻击且超高机率发动必杀技\\n‧超高机率发动追加攻击且超高机率发动必杀技\\n‧气珠变化：体气珠→速气珠\\n‧高机率回避敌人的攻击\\n‧超高机率使攻击过的敌人晕眩2回合\\n*取得速气珠时*\\n‧追加发动必杀技\\n*取得速气珠以外的属性气珠时*\\n‧超高机率发动追加攻击且高机率发动必杀技\\n‧高机率发动追加攻击且超高机率发动必杀技\\n*气力值12以上攻击时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧{passiveImg:once}必可发动奋力一击\\n*每次发动攻击时*\\n‧该回合回避率5%{passiveImg:up_g}\\n*每次发动必杀技时*\\n‧该回合回避率5%{passiveImg:up_g}\\n*受到攻击时*\\n‧DEF200%{passiveImg:up_g}\\n*我方队伍除了自己以外，\\n有「被托付的意志」或是「人造人/赛鲁篇」类别的角色时*\\n‧我方全体的气力+2、ATK与DEF60%{passiveImg:up_g}\", \"passiveSkillName\": \"三年后的预言\", \"passiveSkillSetId\": 4811}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('71371230e2664dbe', 1024551, '超级赛亚人神SS贝吉达&\n超级赛亚人特南克斯(未来)', 3, '骄傲与希望的力量', 100, '12', 77, 5, 150, 17750, 15910, 8488, 4688, '*自身登场时，我方队伍除了自己以外，\n有「亲子的羁绊」类别的角色时，\n发动登场时动画*\n‧{passiveImg:once}5回合内气力+7、DEF100%{passiveImg:up_g}\n‧{passiveImg:once}3回合内伤害减轻率10%{passiveImg:up_g}、\n随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\n*基本效果*\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\n‧防御所有攻击\n‧伤害减轻率20%{passiveImg:up_g}\n‧必可发动追加攻击且超高机率发动必杀技\n*气力值18以上攻击时*\n‧追加发动必杀技\n*发动主动技能时，\n或是气力值24攻击时*\n‧我方全体「亲子的羁绊」类别的DEF30%{passiveImg:up_g}\n*每次受到攻击或是回避敌人的攻击时*\n‧{passiveImg:forever}气力+2(最高+10)\n‧{passiveImg:forever}ATK20%{passiveImg:up_g}(最高100%)\n‧{passiveImg:forever}DEF50%{passiveImg:up_g}(最高150%)\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\n*处于该回合第一顺位时*\n‧ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率30%{passiveImg:up_g}', 1024551, '「亲子的羁绊」或是「未来篇」类别的\n气力+3、HP、ATK、DEF提升170%，\n若有包含「赌上命运的战斗」类别，\n气力再+1、HP、ATK、DEF再提升30%', '2025-07-31 16:00:00', '{\"leaderSkill\": \"「亲子的羁绊」或是「未来篇」类别的\\n气力+3、HP、ATK、DEF提升170%，\\n若有包含「赌上命运的战斗」类别，\\n气力再+1、HP、ATK、DEF再提升30%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1024551, \"passiveSkillDesc\": \"*自身登场时，我方队伍除了自己以外，\\n有「亲子的羁绊」类别的角色时，\\n发动登场时动画*\\n‧{passiveImg:once}5回合内气力+7、DEF100%{passiveImg:up_g}\\n‧{passiveImg:once}3回合内伤害减轻率10%{passiveImg:up_g}、\\n随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\\n*基本效果*\\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\\n‧防御所有攻击\\n‧伤害减轻率20%{passiveImg:up_g}\\n‧必可发动追加攻击且超高机率发动必杀技\\n*气力值18以上攻击时*\\n‧追加发动必杀技\\n*发动主动技能时，\\n或是气力值24攻击时*\\n‧我方全体「亲子的羁绊」类别的DEF30%{passiveImg:up_g}\\n*每次受到攻击或是回避敌人的攻击时*\\n‧{passiveImg:forever}气力+2(最高+10)\\n‧{passiveImg:forever}ATK20%{passiveImg:up_g}(最高100%)\\n‧{passiveImg:forever}DEF50%{passiveImg:up_g}(最高150%)\\n‧{passiveImg:forever}发动奋力一击的机率10%{passiveImg:up_g}(最高50%)\\n*处于该回合第一顺位时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率30%{passiveImg:up_g}\", \"passiveSkillName\": \"守护未来的父子\", \"passiveSkillSetId\": 4688}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('715512776e964fa7', 1015571, '弗力札(全力)', 3, '赌上存活的最终攻击', 200, '23', 77, 5, 150, 14563, 16550, 9656, 2931, '*基本效果*\n‧气力+4\n‧ATK与DEF120%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧DEF40%{passiveImg:up_g}\n*气力值18以上攻击时*\n‧对全属性造成属性克制伤害\n*HP80%以下*\n‧气力+2\n‧ATK40%{passiveImg:up_g}\n*HP60%以下*\n‧气力+2\n‧ATK40%{passiveImg:up_g}\n*HP40%以下*\n‧必可发动奋力一击\n*HP40%以下攻击时*\n‧{passiveImg:once}使攻击过的敌人行动中断', 1015571, '「力量全开」类别的\n气力+4、HP、ATK、DEF提升150%，\n或是极力属性的气力+4、HP、ATK、DEF提升100%', '2022-09-01 16:00:00', '{\"leaderSkill\": \"「力量全开」类别的\\n气力+4、HP、ATK、DEF提升150%，\\n或是极力属性的气力+4、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015571, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+4\\n‧ATK与DEF120%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧DEF40%{passiveImg:up_g}\\n*气力值18以上攻击时*\\n‧对全属性造成属性克制伤害\\n*HP80%以下*\\n‧气力+2\\n‧ATK40%{passiveImg:up_g}\\n*HP60%以下*\\n‧气力+2\\n‧ATK40%{passiveImg:up_g}\\n*HP40%以下*\\n‧必可发动奋力一击\\n*HP40%以下攻击时*\\n‧{passiveImg:once}使攻击过的敌人行动中断\", \"passiveSkillName\": \"增幅的愤怒\", \"passiveSkillSetId\": 2931}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('71f1ce9659574ad2', 1022721, '凯葳', 7, '小恶魔的奇袭', 100, '11', 18, 4, 140, 9976, 11161, 6943, 4216, '*基本效果*\n‧气力+4\n‧ATK与DEF140%{passiveImg:up_g}\n‧超高机率使攻击过的敌人晕眩\n‧高机率追加发动必杀技\n‧高机率回避敌人的攻击\n*我方队伍除了自己以外，有「活泼女孩」类别的角色时*\n‧ATK与DEF140%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF140%{passiveImg:up_g}\n‧超高机率使ATK与DEF40%{passiveImg:up_g}\n‧目标的状态：{passiveImg:atk_down}或是{passiveImg:def_down}或是{passiveImg:astute}时，\nDEF40%{passiveImg:up_g}、对全属性造成属性克制伤害\n‧目标的状态：{passiveImg:stun}时，必可发动奋力一击、追加发动必杀技\n*敌方有「大会参赛者」类别的角色时*\n‧回避率20%{passiveImg:up_g}', 1022721, '「活泼女孩」类别的\n气力+3、HP、ATK、DEF提升150%', '2024-10-27 16:00:00', '{\"leaderSkill\": \"「活泼女孩」类别的\\n气力+3、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1022721, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+4\\n‧ATK与DEF140%{passiveImg:up_g}\\n‧超高机率使攻击过的敌人晕眩\\n‧高机率追加发动必杀技\\n‧高机率回避敌人的攻击\\n*我方队伍除了自己以外，有「活泼女孩」类别的角色时*\\n‧ATK与DEF140%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF140%{passiveImg:up_g}\\n‧超高机率使ATK与DEF40%{passiveImg:up_g}\\n‧目标的状态：{passiveImg:atk_down}或是{passiveImg:def_down}或是{passiveImg:astute}时，\\nDEF40%{passiveImg:up_g}、对全属性造成属性克制伤害\\n‧目标的状态：{passiveImg:stun}时，必可发动奋力一击、追加发动必杀技\\n*敌方有「大会参赛者」类别的角色时*\\n‧回避率20%{passiveImg:up_g}\", \"passiveSkillName\": \"锐利的武器\", \"passiveSkillSetId\": 4216}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('72043a6444ce4ca4', 1011901, '比克', 7, '聪明的战士', 100, '12', 42, 4, 140, 12234, 9497, 6735, 4177, '*基本效果*\n‧气力+1\n‧ATK与DEF200%{passiveImg:up_g}\n‧我方全体「大会参赛者」类别的气力+1、ATK与DEF30%{passiveImg:up_g}，\n若有包含「第7宇宙代表」类别，气力再+1、DEF再30%{passiveImg:up_g}\n*HP80%以下*\n‧攻击必中敌人\n*攻击时HP80%以下*\n‧封锁攻击过的敌人的必杀技\n*气力值12以上攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n*参加攻击中的我方除了自己以外，\n有「第7宇宙代表」类别的角色时*\n‧ATK与DEF100%{passiveImg:up_g}\n*参加攻击中的我方全体皆属于「第7宇宙代表」类别时*\n‧防御所有攻击', 1011901, '知属性的气力+3、HP、ATK、DEF提升100%', '2024-11-20 16:00:00', '{\"leaderSkill\": \"知属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011901, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+1\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧我方全体「大会参赛者」类别的气力+1、ATK与DEF30%{passiveImg:up_g}，\\n若有包含「第7宇宙代表」类别，气力再+1、DEF再30%{passiveImg:up_g}\\n*HP80%以下*\\n‧攻击必中敌人\\n*攻击时HP80%以下*\\n‧封锁攻击过的敌人的必杀技\\n*气力值12以上攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*参加攻击中的我方除了自己以外，\\n有「第7宇宙代表」类别的角色时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*参加攻击中的我方全体皆属于「第7宇宙代表」类别时*\\n‧防御所有攻击\", \"passiveSkillName\": \"赌上全部的凝聚力\", \"passiveSkillSetId\": 4177}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
