INSERT INTO `eza_card` VALUES ('73b7d0d7257f4b94', 1009831, '超级赛亚人4贝吉达', 8, '至高无上的超级赛亚人', 100, '10', 58, 4, 140, 14807, 13320, 6914, 4669, '*基本效果*\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\n‧必可发动追加攻击且超高机率发动必杀技\n*参加攻击中的我方每多1名超系的角色*\n‧ATK与DEF100%{passiveImg:up_g}\n‧伤害减轻率10%{passiveImg:up_g}\n*敌方有极系的角色时，\n或是参加攻击中的我方除了自己以外，\n有「GT HERO」类别的角色时*\n‧我方全体的DEF40%{passiveImg:up_g}\n‧必可发动奋力一击\n*气力值12以上攻击时*\n‧ATK100%{passiveImg:up_g}\n*处于该回合第二或是第三攻击顺位时*\n‧ATK与DEF100%{passiveImg:up_g}\n*受到敌人的必杀技攻击时*\n‧暂时使DEF100%{passiveImg:up_g}\n‧高机率使其无效，并以超绝大威力反击', 1009831, '超速属性的气力+3、HP、ATK、DEF提升130% & \n极速属性的气力+3、HP、ATK、DEF提升90%', '2025-07-28 16:00:00', '{\"leaderSkill\": \"超速属性的气力+3、HP、ATK、DEF提升130% & \\n极速属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1009831, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\\n‧必可发动追加攻击且超高机率发动必杀技\\n*参加攻击中的我方每多1名超系的角色*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧伤害减轻率10%{passiveImg:up_g}\\n*敌方有极系的角色时，\\n或是参加攻击中的我方除了自己以外，\\n有「GT HERO」类别的角色时*\\n‧我方全体的DEF40%{passiveImg:up_g}\\n‧必可发动奋力一击\\n*气力值12以上攻击时*\\n‧ATK100%{passiveImg:up_g}\\n*处于该回合第二或是第三攻击顺位时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*受到敌人的必杀技攻击时*\\n‧暂时使DEF100%{passiveImg:up_g}\\n‧高机率使其无效，并以超绝大威力反击\", \"passiveSkillName\": \"另一个秘策\", \"passiveSkillSetId\": 4669}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('73dc46cc4dea4469', 1014141, '维黛尔', 7, '飞翔的心', 100, '12', 15, 4, 140, 9535, 9218, 5441, 2558, '*基本效果*\n‧使攻击过的敌人2回合内ATK与DEF20%{passiveImg:down_y}\n‧以造成敌方伤害的20%回复自身HP\n*队伍里每多1名「活泼女孩」类别的角色*\n‧ATK与DEF20%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧DEF80%{passiveImg:up_g}', 1014141, '知与力属性的气力+3、HP、ATK、DEF提升90%', '2022-01-09 16:00:00', '{\"leaderSkill\": \"知与力属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1014141, \"passiveSkillDesc\": \"*基本效果*\\n‧使攻击过的敌人2回合内ATK与DEF20%{passiveImg:down_y}\\n‧以造成敌方伤害的20%回复自身HP\\n*队伍里每多1名「活泼女孩」类别的角色*\\n‧ATK与DEF20%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧DEF80%{passiveImg:up_g}\", \"passiveSkillName\": \"值得信赖的实力\", \"passiveSkillSetId\": 2558}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
