INSERT INTO `eza_card` VALUES ('743c988ad12245d1', 1026841, '超级赛亚人孙悟饭(未来)', 7, '突破困境的力量', 100, '12', 32, 4, 140, 12596, 11725, 6631, 4606, '*基本效果*\n‧ATK与DEF200%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK与DEF120%{passiveImg:up_g}\n*敌方有「未来篇」或是「人造人」类别的角色时*\n‧气力+2\n‧ATK与DEF120%{passiveImg:up_g}\n‧超高机率使攻击过的敌人晕眩\n*我方队伍除了自己以外，有「未来篇」类别的角色时*\n‧气力+2\n‧发动奋力一击的机率与伤害减轻率30%{passiveImg:up_g}\n‧气力值12以上攻击时ATK120%{passiveImg:up_g}\n*队伍里有名称含有「特南克斯」的角色时*\n‧气力+2\n‧发动奋力一击的机率与伤害减轻率30%{passiveImg:up_g}\n‧气力值12以上攻击时DEF120%{passiveImg:up_g}', 1026842, '超知属性的气力+3、HP、ATK、DEF提升120%', '2025-05-08 16:00:00', '{\"leaderSkill\": \"超知属性的气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1026842, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF200%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK与DEF120%{passiveImg:up_g}\\n*敌方有「未来篇」或是「人造人」类别的角色时*\\n‧气力+2\\n‧ATK与DEF120%{passiveImg:up_g}\\n‧超高机率使攻击过的敌人晕眩\\n*我方队伍除了自己以外，有「未来篇」类别的角色时*\\n‧气力+2\\n‧发动奋力一击的机率与伤害减轻率30%{passiveImg:up_g}\\n‧气力值12以上攻击时ATK120%{passiveImg:up_g}\\n*队伍里有名称含有「特南克斯」的角色时*\\n‧气力+2\\n‧发动奋力一击的机率与伤害减轻率30%{passiveImg:up_g}\\n‧气力值12以上攻击时DEF120%{passiveImg:up_g}\", \"passiveSkillName\": \"拥有羁绊之人\", \"passiveSkillSetId\": 4606}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
