INSERT INTO `eza_card` VALUES ('756ee0c0a91f4d24', 1024631, '黑悟空', 7, '残酷无情的裁断', 200, '23', 36, 4, 140, 12619, 11976, 4646, 4547, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n‧队伍里我方全体「未来篇」类别的\n气力+1、ATK与DEF20%{passiveImg:up_g}\n‧队伍里我方全体「超越时空之人」类别的\n气力+1、ATK与DEF20%{passiveImg:up_g}\n*每次受到攻击时*\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\n*敌方有超系的角色时*\n‧攻击时ATK100%{passiveImg:up_g}\n*若队伍里有极属性的全属性角色*\n‧自身的进攻回合内\n我方全体的ATK20%{passiveImg:up_g}\n‧攻击时DEF100%{passiveImg:up_g}、防御所有攻击\n*参加攻击中的我方除了自己以外，\n有名称含有「扎马斯」或是「黑悟空」的角色时*\n‧ATK与DEF200%{passiveImg:up_g}\n‧超高机率发动奋力一击\n‧我方全体的DEF20%{passiveImg:up_g}', 1024632, '极力属性的气力+3、HP、ATK、DEF提升120%', '2025-03-20 16:00:00', '{\"leaderSkill\": \"极力属性的气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1024632, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧队伍里我方全体「未来篇」类别的\\n气力+1、ATK与DEF20%{passiveImg:up_g}\\n‧队伍里我方全体「超越时空之人」类别的\\n气力+1、ATK与DEF20%{passiveImg:up_g}\\n*每次受到攻击时*\\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\\n*敌方有超系的角色时*\\n‧攻击时ATK100%{passiveImg:up_g}\\n*若队伍里有极属性的全属性角色*\\n‧自身的进攻回合内\\n我方全体的ATK20%{passiveImg:up_g}\\n‧攻击时DEF100%{passiveImg:up_g}、防御所有攻击\\n*参加攻击中的我方除了自己以外，\\n有名称含有「扎马斯」或是「黑悟空」的角色时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧超高机率发动奋力一击\\n‧我方全体的DEF20%{passiveImg:up_g}\", \"passiveSkillName\": \"粉碎的历史\", \"passiveSkillSetId\": 4547}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('759e02d959df41de', 1015241, '超级机械利尔德', 7, '猛烈的集中攻击', 200, '20', 42, 4, 140, 13340, 13106, 6704, 4017, '*基本效果*\n‧我方全体速属性的气力+3、ATK与DEF10%{passiveImg:up_g}\n‧我方全体极速属性的ATK与DEF50%{passiveImg:up_g}\n‧随机气珠变化：速气珠以外的任一属性气珠→速气珠\n*每取得1个气珠*\n‧ATK与DEF50%{passiveImg:up_g}\n*每取得1个速气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n‧发动奋力一击的机率10%{passiveImg:up_g}\n*我方队伍除了自己以外，有2名以上极系的角色时*\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→速气珠\n*我方队伍除了自己以外，有3名以上速属性的角色时*\n‧登场后4回合内防御所有攻击', 1015241, '极速属性的气力+4、HP、ATK、DEF提升150%', '2024-04-11 16:00:00', '{\"leaderSkill\": \"极速属性的气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015241, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体速属性的气力+3、ATK与DEF10%{passiveImg:up_g}\\n‧我方全体极速属性的ATK与DEF50%{passiveImg:up_g}\\n‧随机气珠变化：速气珠以外的任一属性气珠→速气珠\\n*每取得1个气珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n*每取得1个速气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n‧发动奋力一击的机率10%{passiveImg:up_g}\\n*我方队伍除了自己以外，有2名以上极系的角色时*\\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→速气珠\\n*我方队伍除了自己以外，有3名以上速属性的角色时*\\n‧登场后4回合内防御所有攻击\", \"passiveSkillName\": \"将军的号令\", \"passiveSkillSetId\": 4017}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('75eba057233d43e6', 1019691, '贝吉特', 7, '无法迎击的威力', 100, '10', 40, 4, 140, 10995, 10477, 7269, 4152, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n‧我方全体超系的ATK与DEF30%{passiveImg:up_g}，且队伍里每多\n1名「魔人普乌篇」类别的角色，ATK与DEF再3%{passiveImg:up_g}\n‧必可发动追加攻击且高机率发动必杀技\n*处于该回合第一顺位时*\n‧气力+2\n‧ATK与DEF150%{passiveImg:up_g}\n‧超高机率回避敌人的攻击\n*敌方有「魔人普乌篇」类别的角色时*\n‧追加发动必杀技\n*攻击时*\n‧ATK50%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高100%)', 1019692, '速属性的气力+3、HP、ATK、DEF提升100%', '2024-07-18 16:00:00', '{\"leaderSkill\": \"速属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019692, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧我方全体超系的ATK与DEF30%{passiveImg:up_g}，且队伍里每多\\n1名「魔人普乌篇」类别的角色，ATK与DEF再3%{passiveImg:up_g}\\n‧必可发动追加攻击且高机率发动必杀技\\n*处于该回合第一顺位时*\\n‧气力+2\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧超高机率回避敌人的攻击\\n*敌方有「魔人普乌篇」类别的角色时*\\n‧追加发动必杀技\\n*攻击时*\\n‧ATK50%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高100%)\", \"passiveSkillName\": \"不同级别\", \"passiveSkillSetId\": 4152}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('764c2c5d27e14a0f', 4017791, '比克大魔王', 3, '压倒性威力的复活', 200, '21', 99, 5, 150, 12878, 13870, 9537, 4274, '*基本效果*\n‧{passiveImg:once}HP回复59%\n‧气力+6\n‧DEF100%{passiveImg:up_g}\n‧随机气珠变化：技气珠以外的任一属性气珠→技气珠\n*每取得1个气珠*\n‧ATK66%{passiveImg:up_g}\n*取得3个以上技气珠*\n‧高机率发动奋力一击\n‧自第4个开始起算，每取得1个技气珠发动奋力一击的机率6%{passiveImg:up_g}\n*登场后6回合内*\n‧伤害减轻率66%{passiveImg:up_g}\n*登场后第7回合起*\n‧每取得1个气珠伤害减轻率10%{passiveImg:up_g}(最高66%)\n*处于该回合第一顺位时*\n‧DEF100%{passiveImg:up_g}\n*处于该回合第二或是第三顺位时*\n‧必可发动追加攻击且高机率发动必杀技\n‧回避率30%{passiveImg:up_g}\n*参加攻击中的我方全体皆属于极系时*\n‧DEF66%{passiveImg:up_g}\n‧回避率30%{passiveImg:up_g}', 1017781, '「恐怖的征服者」类别的\n气力+4、HP、ATK、DEF提升150%', NULL, '{\"leaderSkill\": \"「恐怖的征服者」类别的\\n气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1017781, \"passiveSkillDesc\": \"*基本效果*\\n‧{passiveImg:once}HP回复59%\\n‧气力+6\\n‧DEF100%{passiveImg:up_g}\\n‧随机气珠变化：技气珠以外的任一属性气珠→技气珠\\n*每取得1个气珠*\\n‧ATK66%{passiveImg:up_g}\\n*取得3个以上技气珠*\\n‧高机率发动奋力一击\\n‧自第4个开始起算，每取得1个技气珠发动奋力一击的机率6%{passiveImg:up_g}\\n*登场后6回合内*\\n‧伤害减轻率66%{passiveImg:up_g}\\n*登场后第7回合起*\\n‧每取得1个气珠伤害减轻率10%{passiveImg:up_g}(最高66%)\\n*处于该回合第一顺位时*\\n‧DEF100%{passiveImg:up_g}\\n*处于该回合第二或是第三顺位时*\\n‧必可发动追加攻击且高机率发动必杀技\\n‧回避率30%{passiveImg:up_g}\\n*参加攻击中的我方全体皆属于极系时*\\n‧DEF66%{passiveImg:up_g}\\n‧回避率30%{passiveImg:up_g}\", \"passiveSkillName\": \"满溢的威能\", \"passiveSkillSetId\": 4274}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('7679fb5cd92e4bcb', 1018661, '普乌先生', 7, '畅快自在的身体能力', 100, '11', 40, 4, 140, 13744, 9927, 6644, 4104, '*基本效果*\n‧ATK与DEF120%{passiveImg:up_g}\n‧气珠变化：知气珠→彩虹珠\n‧随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\n*气力值12以上攻击时*\n‧ATK120%{passiveImg:up_g}\n*每取得1个彩虹珠*\n‧ATK与DEF50%{passiveImg:up_g}\n‧HP回复30000\n*取得2个以上彩虹珠*\n‧伤害减轻率50%{passiveImg:up_g}\n‧自第3个开始起算，每取得1个彩虹珠伤害减轻率再10%{passiveImg:up_g}', 1018662, '全属性的气力+3、HP、ATK、DEF提升70%', '2024-06-27 16:00:00', '{\"leaderSkill\": \"全属性的气力+3、HP、ATK、DEF提升70%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1018662, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF120%{passiveImg:up_g}\\n‧气珠变化：知气珠→彩虹珠\\n‧随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\\n*气力值12以上攻击时*\\n‧ATK120%{passiveImg:up_g}\\n*每取得1个彩虹珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧HP回复30000\\n*取得2个以上彩虹珠*\\n‧伤害减轻率50%{passiveImg:up_g}\\n‧自第3个开始起算，每取得1个彩虹珠伤害减轻率再10%{passiveImg:up_g}\", \"passiveSkillName\": \"多样的变化\", \"passiveSkillSetId\": 4104}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('772bf8169c0e4d48', 1020811, '乌普(少年期)', 7, '惊人的转生', 100, '14', 32, 4, 140, 10481, 9179, 6095, 2244, '*每当回合开始时*\n‧{passiveImg:forever}气力+1(最高+4)\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高120%)\n*受到攻击后*\n‧ATK100%{passiveImg:up_g}\n*敌方有「天下第一武道大会」类别或是名称含有\n「孙悟空」的角色时(不包含少年期、奇纽、Jr.等)*\n‧防御所有攻击', 1020812, '「地球人」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是体属性的气力+3、HP、ATK、DEF提升50%', '2020-09-24 16:00:00', '{\"leaderSkill\": \"「地球人」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是体属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020812, \"passiveSkillDesc\": \"*每当回合开始时*\\n‧{passiveImg:forever}气力+1(最高+4)\\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高120%)\\n*受到攻击后*\\n‧ATK100%{passiveImg:up_g}\\n*敌方有「天下第一武道大会」类别或是名称含有\\n「孙悟空」的角色时(不包含少年期、奇纽、Jr.等)*\\n‧防御所有攻击\", \"passiveSkillName\": \"正式上场时的实力\", \"passiveSkillSetId\": 2244}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('78156aa405234152', 1011681, '超级赛亚人神SS贝吉特', 3, '孤注一掷的一决胜负', 100, '13', 99, 5, 150, 13613, 14090, 8894, 2937, '*基本效果*\n‧ATK与DEF100%{passiveImg:up_g}\n‧中等机率使气力+5\n*每次发动必杀技时*\n‧{passiveImg:forever}ATK与DEF10%{passiveImg:up_g}(最高50%)\n*剩余HP越少*\n‧气力{passiveImg:up_g}(最高+10)\n*气力值18以上攻击时*\n‧必可发动追加攻击且高机率发动必杀技\n*参加攻击中的我方除了自己以外，有「未来篇」类别的角色时*\n‧气力+2\n‧攻击时使敌方防御无效', 1011681, '超系的气力+4、HP、ATK、DEF提升120%', '2022-10-19 16:00:00', '{\"leaderSkill\": \"超系的气力+4、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011681, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧中等机率使气力+5\\n*每次发动必杀技时*\\n‧{passiveImg:forever}ATK与DEF10%{passiveImg:up_g}(最高50%)\\n*剩余HP越少*\\n‧气力{passiveImg:up_g}(最高+10)\\n*气力值18以上攻击时*\\n‧必可发动追加攻击且高机率发动必杀技\\n*参加攻击中的我方除了自己以外，有「未来篇」类别的角色时*\\n‧气力+2\\n‧攻击时使敌方防御无效\", \"passiveSkillName\": \"神级数的合体能量\", \"passiveSkillSetId\": 2937}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('781ef63fe13841a6', 1020341, '超级赛亚人神SS贝吉达(进化)', 3, '真正的战斗民族', 100, '12', 77, 5, 150, 16688, 14850, 10719, 4060, '*基本效果*\n‧ATK与DEF200%{passiveImg:up_g}\n‧必可发动追加攻击且有77%的机率发动必杀技\n‧伤害减轻率50%{passiveImg:up_g}\n*登场后1回合内*\n‧气力+7\n‧防御所有攻击\n*每次受到攻击或是回避敌人的攻击时*\n‧该回合伤害减轻率10%{passiveImg:up_g}(最高30%)\n*每次发动攻击时*\n‧{passiveImg:forever}气力+3(最高+10)\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高120%)\n*发动主动技能时，或是气力值24时*\n‧ATK77%{passiveImg:up_g}\n‧必可发动奋力一击\n*战斗中自身受到5次以上攻击后下一个自身的进攻\n回合起，参加攻击中的我方角色(包含自身)被KO*\n‧{passiveImg:once}复活并回复HP77%\n*自身或是我方的复活技能发动后*\n‧{passiveImg:forever}气力+7\n‧{passiveImg:forever}ATK与DEF77%{passiveImg:up_g}\n*自身的复活技能发动后*\n‧下一个进攻回合内防御所有攻击', 1020341, '「再起的力量」或是「第7宇宙代表」类别的\n气力+3、HP、ATK、DEF提升180%', '2024-07-30 16:00:00', '{\"leaderSkill\": \"「再起的力量」或是「第7宇宙代表」类别的\\n气力+3、HP、ATK、DEF提升180%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1020341, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧必可发动追加攻击且有77%的机率发动必杀技\\n‧伤害减轻率50%{passiveImg:up_g}\\n*登场后1回合内*\\n‧气力+7\\n‧防御所有攻击\\n*每次受到攻击或是回避敌人的攻击时*\\n‧该回合伤害减轻率10%{passiveImg:up_g}(最高30%)\\n*每次发动攻击时*\\n‧{passiveImg:forever}气力+3(最高+10)\\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高120%)\\n*发动主动技能时，或是气力值24时*\\n‧ATK77%{passiveImg:up_g}\\n‧必可发动奋力一击\\n*战斗中自身受到5次以上攻击后下一个自身的进攻\\n回合起，参加攻击中的我方角色(包含自身)被KO*\\n‧{passiveImg:once}复活并回复HP77%\\n*自身或是我方的复活技能发动后*\\n‧{passiveImg:forever}气力+7\\n‧{passiveImg:forever}ATK与DEF77%{passiveImg:up_g}\\n*自身的复活技能发动后*\\n‧下一个进攻回合内防御所有攻击\", \"passiveSkillName\": \"为了遵守约定的力量\", \"passiveSkillSetId\": 4060}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
