INSERT INTO `eza_card` VALUES ('7d0938768a8a4539', 1019001, '布罗利&琪莱&雷莫', 3, '在班帕的新生活', 200, '24', 77, 5, 150, 21575, 15275, 7744, 4005, '*基本效果*\n‧取得气珠时气力再+2\n‧高机率回避敌人的攻击\n*每取得1个气珠*\n‧ATK与DEF30%{passiveImg:up_g}\n*每取得1个体气珠*\n‧ATK与DEF10%{passiveImg:up_g}\n*取得速气珠或是力气珠时*\n‧我方全体的气力+2、ATK39%{passiveImg:up_g}\n*取得技气珠或是知气珠时*\n‧我方全体的气力+2、DEF39%{passiveImg:up_g}\n*取得彩虹珠时*\n‧我方全体的气力+2、ATK与DEF15%{passiveImg:up_g}\n*气力值12以上攻击时*\n‧ATK39%{passiveImg:up_g}\n*气力值24攻击时*\n‧必可追加发动必杀技\n‧我方全体「剧场版BOSS」或是\n「超BOSS」类别的伤害减轻率10%{passiveImg:up_g}\n*取得7个以上气珠*\n‧必可回避敌人的攻击\n*HP60%以下*\n‧随机气珠变化：体气珠以外的任一属性气珠→体气珠\n*HP39%以下*\n‧{passiveImg:once}气珠变化：全部气珠→体气珠', 1019001, '「剧场版BOSS」类别的\n气力+4、HP、ATK、DEF提升150%，\n或是极体属性的气力+4、HP、ATK、DEF提升100%', '2024-07-17 16:00:00', '{\"leaderSkill\": \"「剧场版BOSS」类别的\\n气力+4、HP、ATK、DEF提升150%，\\n或是极体属性的气力+4、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019001, \"passiveSkillDesc\": \"*基本效果*\\n‧取得气珠时气力再+2\\n‧高机率回避敌人的攻击\\n*每取得1个气珠*\\n‧ATK与DEF30%{passiveImg:up_g}\\n*每取得1个体气珠*\\n‧ATK与DEF10%{passiveImg:up_g}\\n*取得速气珠或是力气珠时*\\n‧我方全体的气力+2、ATK39%{passiveImg:up_g}\\n*取得技气珠或是知气珠时*\\n‧我方全体的气力+2、DEF39%{passiveImg:up_g}\\n*取得彩虹珠时*\\n‧我方全体的气力+2、ATK与DEF15%{passiveImg:up_g}\\n*气力值12以上攻击时*\\n‧ATK39%{passiveImg:up_g}\\n*气力值24攻击时*\\n‧必可追加发动必杀技\\n‧我方全体「剧场版BOSS」或是\\n「超BOSS」类别的伤害减轻率10%{passiveImg:up_g}\\n*取得7个以上气珠*\\n‧必可回避敌人的攻击\\n*HP60%以下*\\n‧随机气珠变化：体气珠以外的任一属性气珠→体气珠\\n*HP39%以下*\\n‧{passiveImg:once}气珠变化：全部气珠→体气珠\", \"passiveSkillName\": \"为朋友而战\", \"passiveSkillSetId\": 4005}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
