INSERT INTO `eza_card` VALUES ('7ddc98a82cda4c09', 1005051, '超级邪念波', 7, '地狱的罗刹鬼', 200, '22', 42, 4, 140, 9215, 11685, 4495, 1368, '*基本效果*\n‧ATK与DEF70%{passiveImg:up_g}\n‧防御所有攻击\n*防御成功后*\n‧该回合中等机率回避敌人的攻击\n‧4回合内ATK40%{passiveImg:up_g}', 1005051, '知属性的气力+3、HP、ATK、DEF提升90%', '2019-08-18 16:00:00', '{\"leaderSkill\": \"知属性的气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1005051, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF70%{passiveImg:up_g}\\n‧防御所有攻击\\n*防御成功后*\\n‧该回合中等机率回避敌人的攻击\\n‧4回合内ATK40%{passiveImg:up_g}\", \"passiveSkillName\": \"空间的支配\", \"passiveSkillSetId\": 1368}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('7e0cb08591294f32', 1012681, '比尔斯', 7, '桀骜不逊的神', 100, '12', 40, 4, 140, 11586, 10613, 6061, 3398, '*气力值12以上攻击时*\n‧ATK与DEF150%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}ATK30%{passiveImg:up_g}(最高150%)\n*参加攻击中的我方除了自己以外，有「师徒的羁绊」类别的角色时*\n‧气力+1\n‧必可发动追加攻击且高机率发动必杀技\n*攻击时目标的状态：{passiveImg:atk_down}或是{passiveImg:def_down}或是{passiveImg:stun}或是{passiveImg:astute}*\n‧对全属性造成属性克制伤害', 1012681, '知属性每取得1个知气珠，ATK提升35%', '2023-03-22 16:00:00', '{\"leaderSkill\": \"知属性每取得1个知气珠，ATK提升35%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1012681, \"passiveSkillDesc\": \"*气力值12以上攻击时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}ATK30%{passiveImg:up_g}(最高150%)\\n*参加攻击中的我方除了自己以外，有「师徒的羁绊」类别的角色时*\\n‧气力+1\\n‧必可发动追加攻击且高机率发动必杀技\\n*攻击时目标的状态：{passiveImg:atk_down}或是{passiveImg:def_down}或是{passiveImg:stun}或是{passiveImg:astute}*\\n‧对全属性造成属性克制伤害\", \"passiveSkillName\": \"神的决定事项\", \"passiveSkillSetId\": 3398}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
