INSERT INTO `eza_card` VALUES ('8108cb93ee484d17', 4017971, '超级赛亚人神SS悟吉达', 3, '究极最强的融合', 100, '13', 77, 5, 150, 19025, 17230, 6575, 3373, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n*登场后1回合内*\n‧回避敌人的攻击\n*处于该回合第一或是第二攻击顺位时*\n‧气力+5\n‧必可发动2次追加攻击且中等机率发动必杀技\n‧对全属性造成属性克制伤害\n*处于该回合第三攻击顺位时*\n‧气力+7\n‧追加发动必杀技\n‧超高机率回避敌人的攻击\n*每次发动攻击时*\n‧{passiveImg:forever}气力+1(最高+5)\n‧{passiveImg:forever}ATK与DEF22%{passiveImg:up_g}(最高88%)\n*发动主动技能时，或是气力值24攻击时*\n‧必可发动奋力一击', 1018621, '「最后的杀手锏」或是「融合」类别的\n气力+3、HP、ATK、DEF提升170%', NULL, '{\"leaderSkill\": \"「最后的杀手锏」或是「融合」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1018621, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*登场后1回合内*\\n‧回避敌人的攻击\\n*处于该回合第一或是第二攻击顺位时*\\n‧气力+5\\n‧必可发动2次追加攻击且中等机率发动必杀技\\n‧对全属性造成属性克制伤害\\n*处于该回合第三攻击顺位时*\\n‧气力+7\\n‧追加发动必杀技\\n‧超高机率回避敌人的攻击\\n*每次发动攻击时*\\n‧{passiveImg:forever}气力+1(最高+5)\\n‧{passiveImg:forever}ATK与DEF22%{passiveImg:up_g}(最高88%)\\n*发动主动技能时，或是气力值24攻击时*\\n‧必可发动奋力一击\", \"passiveSkillName\": \"好惊人的力量！！！\", \"passiveSkillSetId\": 3373}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
