INSERT INTO `eza_card` VALUES ('8b8f8992dfbb4fde', 1008801, '人造人17号&18号', 3, '无穷尽的能量', 200, '20', 99, 5, 150, 13200, 13100, 7100, 2673, '*基本效果*\n‧我方全体极系的气力+4、DEF50%{passiveImg:up_g}\n‧敌方全体超系的DEF78%{passiveImg:down_y}\n*气力值12以上攻击时*\n‧ATK与DEF78%{passiveImg:up_g}\n*攻击超系的敌人后*\n‧气力+3、ATK78%{passiveImg:up_g}\n‧必可发动追加攻击且中等机率发动必杀技', 1008801, '全属性的气力+4、HP、ATK、DEF提升80%', '2022-01-31 16:00:00', '{\"leaderSkill\": \"全属性的气力+4、HP、ATK、DEF提升80%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1008801, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体极系的气力+4、DEF50%{passiveImg:up_g}\\n‧敌方全体超系的DEF78%{passiveImg:down_y}\\n*气力值12以上攻击时*\\n‧ATK与DEF78%{passiveImg:up_g}\\n*攻击超系的敌人后*\\n‧气力+3、ATK78%{passiveImg:up_g}\\n‧必可发动追加攻击且中等机率发动必杀技\", \"passiveSkillName\": \"人造人的实力\", \"passiveSkillSetId\": 2673}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('8bb2907ff0544d5b', 1028081, '卡莉芙拉', 7, '显现而出的素质', 100, '12', 36, 4, 140, 10121, 11576, 6394, 4704, '*基本效果*\n‧ATK与DEF160%{passiveImg:up_g}\n*队伍里每多1名「第6宇宙」或是\n「活泼女孩」类别的角色\n(以其中人数较多之类别计算)*\n‧ATK与DEF30%{passiveImg:up_g}\n‧发动奋力一击的机率6%{passiveImg:up_g}\n*队伍里有名称含有「凯露」的角色时*\n‧ATK160%{passiveImg:up_g}\n‧超高机率回避敌人的攻击\n‧追加发动必杀技\n*参加攻击中的我方有名称含有「凯露」的角色时*\n‧回避率10%{passiveImg:up_g}\n*登场后1回合内*\n‧回避率10%{passiveImg:up_g}\n*每次回避敌人的攻击时*\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高90%)\n*战斗中自身发动6次以上攻击后*\n‧{passiveImg:forever}必可发动追加攻击且超高机率发动必杀技', 1028082, '超知属性的气力+3、HP、ATK、DEF提升120%', '2025-08-21 16:00:00', '{\"leaderSkill\": \"超知属性的气力+3、HP、ATK、DEF提升120%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1028082, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF160%{passiveImg:up_g}\\n*队伍里每多1名「第6宇宙」或是\\n「活泼女孩」类别的角色\\n(以其中人数较多之类别计算)*\\n‧ATK与DEF30%{passiveImg:up_g}\\n‧发动奋力一击的机率6%{passiveImg:up_g}\\n*队伍里有名称含有「凯露」的角色时*\\n‧ATK160%{passiveImg:up_g}\\n‧超高机率回避敌人的攻击\\n‧追加发动必杀技\\n*参加攻击中的我方有名称含有「凯露」的角色时*\\n‧回避率10%{passiveImg:up_g}\\n*登场后1回合内*\\n‧回避率10%{passiveImg:up_g}\\n*每次回避敌人的攻击时*\\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高90%)\\n*战斗中自身发动6次以上攻击后*\\n‧{passiveImg:forever}必可发动追加攻击且超高机率发动必杀技\", \"passiveSkillName\": \"激昂感激发的力量\", \"passiveSkillSetId\": 4704}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('8bba2c14a0b1480b', 1023591, '一星龙', 7, '无情的制裁', 200, '21', 40, 4, 140, 13226, 12152, 5986, 4681, '*基本效果*\n‧随机气珠变化：技气珠以外的任一属性气珠→彩虹珠\n‧气力+2、ATK与DEF150%{passiveImg:up_g}\n‧高机率发动奋力一击\n‧高机率追加发动必杀技\n*登场后1回合内*\n‧伤害减轻率40%{passiveImg:up_g}\n*攻击时*\n‧使敌方防御无效\n‧每取得1个气珠ATK与DEF50%{passiveImg:up_g}(最高350%)\n*取得2个以上气珠*\n‧伤害减轻率20%{passiveImg:up_g}\n*取得3个以上气珠*\n‧发动奋力一击的机率20%{passiveImg:up_g}\n*取得4个以上气珠*\n‧伤害减轻率20%{passiveImg:up_g}\n*取得5个以上气珠*\n‧发动奋力一击的机率30%{passiveImg:up_g}\n*取得6个以上气珠*\n‧追加发动必杀技\n*取得7个以上气珠*\n‧使攻击过的敌人2回合内ATK与DEF20%{passiveImg:down_y}', 1023591, '「GT BOSS」类别的\n气力+3、HP、ATK、DEF提升150%', '2025-07-28 16:00:00', '{\"leaderSkill\": \"「GT BOSS」类别的\\n气力+3、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023591, \"passiveSkillDesc\": \"*基本效果*\\n‧随机气珠变化：技气珠以外的任一属性气珠→彩虹珠\\n‧气力+2、ATK与DEF150%{passiveImg:up_g}\\n‧高机率发动奋力一击\\n‧高机率追加发动必杀技\\n*登场后1回合内*\\n‧伤害减轻率40%{passiveImg:up_g}\\n*攻击时*\\n‧使敌方防御无效\\n‧每取得1个气珠ATK与DEF50%{passiveImg:up_g}(最高350%)\\n*取得2个以上气珠*\\n‧伤害减轻率20%{passiveImg:up_g}\\n*取得3个以上气珠*\\n‧发动奋力一击的机率20%{passiveImg:up_g}\\n*取得4个以上气珠*\\n‧伤害减轻率20%{passiveImg:up_g}\\n*取得5个以上气珠*\\n‧发动奋力一击的机率30%{passiveImg:up_g}\\n*取得6个以上气珠*\\n‧追加发动必杀技\\n*取得7个以上气珠*\\n‧使攻击过的敌人2回合内ATK与DEF20%{passiveImg:down_y}\", \"passiveSkillName\": \"邪恶放流\", \"passiveSkillSetId\": 4681}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
