INSERT INTO `eza_card` VALUES ('8d9fa47936824502', 1016511, '超级赛亚人贝吉达', 7, '无限的战斗力', 100, '14', 58, 4, 140, 14002, 16091, 7154, 3858, '*基本效果*\n‧ATK与DEF110%{passiveImg:up_g}\n‧超高机率使气珠变化：力气珠→体气珠\n*气力值12以上攻击时*\n‧DEF30%{passiveImg:up_g}\n*每取得1个气珠*\n‧ATK15%{passiveImg:up_g}\n*取得7个以上气珠*\n‧必可追加发动必杀技\n*战斗开始后第3回合起*\n‧进行变身', 1016511, '「纯粹赛亚人」类别的\n气力+3、HP、ATK、DEF提升170%，\n或是超系的气力+3、HP、ATK、DEF提升130%', '2024-01-09 16:00:00', '{\"leaderSkill\": \"「纯粹赛亚人」类别的\\n气力+3、HP、ATK、DEF提升170%，\\n或是超系的气力+3、HP、ATK、DEF提升130%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1016511, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF110%{passiveImg:up_g}\\n‧超高机率使气珠变化：力气珠→体气珠\\n*气力值12以上攻击时*\\n‧DEF30%{passiveImg:up_g}\\n*每取得1个气珠*\\n‧ATK15%{passiveImg:up_g}\\n*取得7个以上气珠*\\n‧必可追加发动必杀技\\n*战斗开始后第3回合起*\\n‧进行变身\", \"passiveSkillName\": \"这就是超级赛亚人\", \"passiveSkillSetId\": 3858}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
