INSERT INTO `eza_card` VALUES ('95699220b1154ee1', 1021671, '传说的超级赛亚人布罗利', 7, '依循本能的破坏', 200, '22', 58, 4, 140, 16534, 15945, 8117, 4211, '*基本效果*\n‧气力+3\n‧ATK与DEF260%{passiveImg:up_g}\n‧伤害减轻率与发动奋力一击的机率26%{passiveImg:up_g}\n‧必可发动追加攻击且高机率发动必杀技\n*攻击时*\n‧ATK与DEF26%{passiveImg:up_g}\n*敌方有「纯粹赛亚人」或是「混血赛亚人」\n或是「剧场版HERO」类别的角色时*\n‧气力+3\n‧必可发动追加攻击且超高机率发动必杀技\n‧攻击时伤害减轻率与发动奋力一击的机率18%{passiveImg:up_g}\n*敌方有名称含有「孙悟空」的角色时(不包含奇纽、Jr.等)*\n‧必可追加发动必杀技\n‧攻击时伤害减轻率与发动奋力一击的机率15%{passiveImg:up_g}', 1021671, '「行星破坏」或是「剧场版BOSS」类别的\n气力+3、HP、ATK、DEF提升170%', '2024-09-02 16:00:00', '{\"leaderSkill\": \"「行星破坏」或是「剧场版BOSS」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1021671, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3\\n‧ATK与DEF260%{passiveImg:up_g}\\n‧伤害减轻率与发动奋力一击的机率26%{passiveImg:up_g}\\n‧必可发动追加攻击且高机率发动必杀技\\n*攻击时*\\n‧ATK与DEF26%{passiveImg:up_g}\\n*敌方有「纯粹赛亚人」或是「混血赛亚人」\\n或是「剧场版HERO」类别的角色时*\\n‧气力+3\\n‧必可发动追加攻击且超高机率发动必杀技\\n‧攻击时伤害减轻率与发动奋力一击的机率18%{passiveImg:up_g}\\n*敌方有名称含有「孙悟空」的角色时(不包含奇纽、Jr.等)*\\n‧必可追加发动必杀技\\n‧攻击时伤害减轻率与发动奋力一击的机率15%{passiveImg:up_g}\", \"passiveSkillName\": \"凶恶的破坏\", \"passiveSkillSetId\": 4211}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
