INSERT INTO `eza_card` VALUES ('991669917cfe4b74', 1024511, '黄金弗力札', 3, '帝王的崭新力量', 200, '20', 77, 5, 150, 16475, 15955, 9444, 4722, '*自身登场时，发动登场时动画*\n‧{passiveImg:once}1回合内防御所有攻击\n‧{passiveImg:once}3回合内DEF100%{passiveImg:up_g}\n‧{passiveImg:once}{passiveImg:forever}发动奋力一击的机率与伤害减轻率90%{passiveImg:up_g}\n‧{passiveImg:forever}每经过2回合\n发动奋力一击的机率与伤害减轻率10%{passiveImg:down_r}(最高60%)\n*基本效果*\n‧气力+6、ATK与DEF200%{passiveImg:up_g}\n*HP50%以上*\n‧ATK与DEF200%{passiveImg:up_g}\n‧必可追加发动必杀技\n*每次发动必杀技时*\n‧{passiveImg:forever}气力+1(最高+3)\n‧{passiveImg:forever}DEF30%{passiveImg:up_g}(最高150%)\n*每次受到攻击时*\n‧{passiveImg:forever}气力+1(最高+3)\n‧{passiveImg:forever}ATK30%{passiveImg:up_g}(最高150%)\n*战斗开始后第3回合起*\n‧{passiveImg:once}HP50%以下时\nATK300%{passiveImg:up_g}、必可发动奋力一击\n*战斗开始后第5回合起*\n‧处于该回合第二或是第三顺位并发动攻击后\nATK与DEF100%{passiveImg:up_g}\n*战斗开始后第7回合起*\n‧处于该回合第三顺位并发动攻击后\nATK与DEF100%{passiveImg:up_g}', 1024511, '「复活战士」或是「行星破坏」类别的\n气力+4、HP、ATK、DEF提升170%', '2025-09-02 16:00:00', '{\"leaderSkill\": \"「复活战士」或是「行星破坏」类别的\\n气力+4、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1024511, \"passiveSkillDesc\": \"*自身登场时，发动登场时动画*\\n‧{passiveImg:once}1回合内防御所有攻击\\n‧{passiveImg:once}3回合内DEF100%{passiveImg:up_g}\\n‧{passiveImg:once}{passiveImg:forever}发动奋力一击的机率与伤害减轻率90%{passiveImg:up_g}\\n‧{passiveImg:forever}每经过2回合\\n发动奋力一击的机率与伤害减轻率10%{passiveImg:down_r}(最高60%)\\n*基本效果*\\n‧气力+6、ATK与DEF200%{passiveImg:up_g}\\n*HP50%以上*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧必可追加发动必杀技\\n*每次发动必杀技时*\\n‧{passiveImg:forever}气力+1(最高+3)\\n‧{passiveImg:forever}DEF30%{passiveImg:up_g}(最高150%)\\n*每次受到攻击时*\\n‧{passiveImg:forever}气力+1(最高+3)\\n‧{passiveImg:forever}ATK30%{passiveImg:up_g}(最高150%)\\n*战斗开始后第3回合起*\\n‧{passiveImg:once}HP50%以下时\\nATK300%{passiveImg:up_g}、必可发动奋力一击\\n*战斗开始后第5回合起*\\n‧处于该回合第二或是第三顺位并发动攻击后\\nATK与DEF100%{passiveImg:up_g}\\n*战斗开始后第7回合起*\\n‧处于该回合第三顺位并发动攻击后\\nATK与DEF100%{passiveImg:up_g}\", \"passiveSkillName\": \"新型态的魄力\", \"passiveSkillSetId\": 4722}', 'system', '