INSERT INTO `eza_card` VALUES ('9c5301cfb19440e8', 1020041, '杰克张(威力全开)', 7, '威力全开的解决方式', 100, '14', 36, 4, 140, 8733, 11728, 5213, 4551, '*基本效果*\n‧气力+3、ATK与DEF100%{passiveImg:up_g}\n‧我方全体的气力+3\n‧我方全体「龟派气功」类别的ATK40%{passiveImg:up_g}\n‧我方全体「少年篇」类别的DEF40%{passiveImg:up_g}\n‧我方全体「地球人」类别的\n发动奋力一击的机率5%{passiveImg:up_g}\n*每当回合开始时*\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\n*气力值12以上攻击时*\n‧ATK与DEF150%{passiveImg:up_g}\n*队伍里有「龟仙流」类别的角色时*\n‧随机气珠变化：体气珠以外的任一属性气珠→彩虹珠\n*每取得1个彩虹珠*\n‧伤害减轻率10%{passiveImg:up_g}\n*HP50%以下*\n‧{passiveImg:once}气珠变化：体气珠→彩虹珠\n‧{passiveImg:once}ATK150%{passiveImg:up_g}\n‧{passiveImg:once}高机率发动奋力一击\n‧{passiveImg:once}3回合内我方全体的ATK与DEF20%{passiveImg:up_g}', 1020042, '体属性的气力+3、HP、ATK、DEF提升100%', '2025-03-20 16:00:00', '{\"leaderSkill\": \"体属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020042, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3、ATK与DEF100%{passiveImg:up_g}\\n‧我方全体的气力+3\\n‧我方全体「龟派气功」类别的ATK40%{passiveImg:up_g}\\n‧我方全体「少年篇」类别的DEF40%{passiveImg:up_g}\\n‧我方全体「地球人」类别的\\n发动奋力一击的机率5%{passiveImg:up_g}\\n*每当回合开始时*\\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\\n*气力值12以上攻击时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*队伍里有「龟仙流」类别的角色时*\\n‧随机气珠变化：体气珠以外的任一属性气珠→彩虹珠\\n*每取得1个彩虹珠*\\n‧伤害减轻率10%{passiveImg:up_g}\\n*HP50%以下*\\n‧{passiveImg:once}气珠变化：体气珠→彩虹珠\\n‧{passiveImg:once}ATK150%{passiveImg:up_g}\\n‧{passiveImg:once}高机率发动奋力一击\\n‧{passiveImg:once}3回合内我方全体的ATK与DEF20%{passiveImg:up_g}\", \"passiveSkillName\": \"阻止骚动的能量\", \"passiveSkillSetId\": 4551}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
