INSERT INTO `eza_card` VALUES ('9da9d03baab44a37', 1018061, '沙维扎(克维拉机甲战队)', 7, '华丽的亲卫队', 200, '24', 40, 4, 140, 11711, 12368, 6465, 2972, '*队伍里每多1名「恐怖的征服者」类别的角色*\n‧ATK与DEF40%{passiveImg:up_g}\n*队伍里有名称含有「克维拉」的角色时(不包含克维拉机甲战队)*\n‧气力+3\n‧必可发动2次追加攻击且中等机率发动必杀技\n*敌方有名称含有「孙悟空」的角色时(不包含少年期、奇纽、Jr.等)*\n‧中等机率回避敌人的攻击\n‧中等机率防御所有攻击', 1018061, '「恐怖的征服者」类别的\n气力+3、HP、ATK、DEF提升140%', '2022-09-21 16:00:00', '{\"leaderSkill\": \"「恐怖的征服者」类别的\\n气力+3、HP、ATK、DEF提升140%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1018061, \"passiveSkillDesc\": \"*队伍里每多1名「恐怖的征服者」类别的角色*\\n‧ATK与DEF40%{passiveImg:up_g}\\n*队伍里有名称含有「克维拉」的角色时(不包含克维拉机甲战队)*\\n‧气力+3\\n‧必可发动2次追加攻击且中等机率发动必杀技\\n*敌方有名称含有「孙悟空」的角色时(不包含少年期、奇纽、Jr.等)*\\n‧中等机率回避敌人的攻击\\n‧中等机率防御所有攻击\", \"passiveSkillName\": \"机甲战队的实力\", \"passiveSkillSetId\": 2972}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('9df33ed021224033', 1007121, '魔人普乌(善)', 7, '魔人的大暴走', 200, '24', 36, 4, 140, 11335, 9513, 7110, 2226, '*基本效果*\n‧ATK与DEF66%{passiveImg:up_g}\n*每次受到攻击时*\n‧{passiveImg:forever}气力+1(最高+3)\n‧{passiveImg:forever}ATK与DEF22%{passiveImg:up_g}(最高66%)\n*回合开始时HP40%以下*\n‧HP回复30%', 1007121, '全属性的气力+3、HP、ATK、DEF提升60%', '2020-11-22 16:00:00', '{\"leaderSkill\": \"全属性的气力+3、HP、ATK、DEF提升60%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1007121, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF66%{passiveImg:up_g}\\n*每次受到攻击时*\\n‧{passiveImg:forever}气力+1(最高+3)\\n‧{passiveImg:forever}ATK与DEF22%{passiveImg:up_g}(最高66%)\\n*回合开始时HP40%以下*\\n‧HP回复30%\", \"passiveSkillName\": \"绝望的后续\", \"passiveSkillSetId\": 2226}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
