INSERT INTO `eza_card` VALUES ('9e21fc402e6f456a', 1003211, '超级赛亚人3孙悟空', 7, '最强的奥义', 100, '10', 42, 4, 140, 12527, 11111, 5796, 1023, '*基本效果*\n‧DEF70%{passiveImg:up_g}\n*登场后7回合内*\n‧ATK120%{passiveImg:up_g}', 1003211, '速属性的气力+3、HP、ATK、DEF提升70%', '2018-03-15 16:00:00', '{\"leaderSkill\": \"速属性的气力+3、HP、ATK、DEF提升70%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1003211, \"passiveSkillDesc\": \"*基本效果*\\n‧DEF70%{passiveImg:up_g}\\n*登场后7回合内*\\n‧ATK120%{passiveImg:up_g}\", \"passiveSkillName\": \"胜负的判明\", \"passiveSkillSetId\": 1023}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('9e38128445ef446c', 1026331, '撒旦先生', 7, '荣耀的一击', 100, '14', 32, 4, 140, 10314, 10355, 5713, 3223, '*基本效果*\n‧DEF200%{passiveImg:up_g}\n‧高机率使敌方全体的ATK与DEF20%{passiveImg:down_y}\n*气力值12以上攻击时*\n‧ATK150%{passiveImg:up_g}\n*敌方或是参加攻击中的我方除自身以外，\n有「天下第一武道大会」类别的角色时*\n‧气力+3\n‧ATK与DEF50%{passiveImg:up_g}\n‧封锁攻击过的敌人的必杀技\n*攻击时目标的状态：{passiveImg:atk_down}或是{passiveImg:def_down}*\n‧高机率追加发动必杀技\n*攻击时目标的状态：{passiveImg:astute}*\n‧必可发动奋力一击\n*战斗开始后第6回合起自身被KO*\n‧{passiveImg:once}高机率复活并回复HP50%', 1026332, '「地球长大的战士」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是体属性的气力+3、HP、ATK、DEF提升50%', '2023-07-30 16:00:00', '{\"leaderSkill\": \"「地球长大的战士」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是体属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1026332, \"passiveSkillDesc\": \"*基本效果*\\n‧DEF200%{passiveImg:up_g}\\n‧高机率使敌方全体的ATK与DEF20%{passiveImg:down_y}\\n*气力值12以上攻击时*\\n‧ATK150%{passiveImg:up_g}\\n*敌方或是参加攻击中的我方除自身以外，\\n有「天下第一武道大会」类别的角色时*\\n‧气力+3\\n‧ATK与DEF50%{passiveImg:up_g}\\n‧封锁攻击过的敌人的必杀技\\n*攻击时目标的状态：{passiveImg:atk_down}或是{passiveImg:def_down}*\\n‧高机率追加发动必杀技\\n*攻击时目标的状态：{passiveImg:astute}*\\n‧必可发动奋力一击\\n*战斗开始后第6回合起自身被KO*\\n‧{passiveImg:once}高机率复活并回复HP50%\", \"passiveSkillName\": \"撒旦先生的毅力！\", \"passiveSkillSetId\": 3223}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
