INSERT INTO `eza_card` VALUES ('9ffc9e87564c4445', 1019071, '扎马斯(孙悟空)', 4, '漆黑正义的开端', 200, '23', 59, 5, 150, 13386, 13066, 7024, 4653, '*基本效果*\n‧ATK与DEF159%{passiveImg:up_g}\n‧气珠变化：体气珠→力气珠\n‧必可发动追加攻击且高机率发动必杀技\n‧敌方全体超系的ATK与DEF30%{passiveImg:down_y}\n‧我方全体极系的ATK与DEF40%{passiveImg:up_g}\n*登场后4回合内*\n‧伤害减轻率20%{passiveImg:up_g}\n*敌方有「未来篇」类别的角色时，\n或是参加攻击中的我方全体皆属于极系时*\n‧气力+3\n‧发动奋力一击的机率与伤害减轻率40%{passiveImg:up_g}\n‧追加发动必杀技\n*每次受到攻击时*\n‧{passiveImg:forever}气力+2(最高+10)\n*气力值12以上攻击时*\n‧ATK与DEF159%{passiveImg:up_g}\n*气力值18以上攻击时*\n‧DEF159%{passiveImg:up_g}\n*攻击时目标的状态：HP59%以下或是{passiveImg:atk_down}或是{passiveImg:def_down}*\n‧ATK159%{passiveImg:up_g}\n‧必可发动奋力一击\n*给予敌人致命一击后*\n‧{passiveImg:forever}ATK、DEF、回避率59%{passiveImg:up_g}', 1019071, '「超越时空之人」类别的\n气力+3、HP、ATK、DEF提升100%', '2025-07-06 16:00:00', '{\"leaderSkill\": \"「超越时空之人」类别的\\n气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019071, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF159%{passiveImg:up_g}\\n‧气珠变化：体气珠→力气珠\\n‧必可发动追加攻击且高机率发动必杀技\\n‧敌方全体超系的ATK与DEF30%{passiveImg:down_y}\\n‧我方全体极系的ATK与DEF40%{passiveImg:up_g}\\n*登场后4回合内*\\n‧伤害减轻率20%{passiveImg:up_g}\\n*敌方有「未来篇」类别的角色时，\\n或是参加攻击中的我方全体皆属于极系时*\\n‧气力+3\\n‧发动奋力一击的机率与伤害减轻率40%{passiveImg:up_g}\\n‧追加发动必杀技\\n*每次受到攻击时*\\n‧{passiveImg:forever}气力+2(最高+10)\\n*气力值12以上攻击时*\\n‧ATK与DEF159%{passiveImg:up_g}\\n*气力值18以上攻击时*\\n‧DEF159%{passiveImg:up_g}\\n*攻击时目标的状态：HP59%以下或是{passiveImg:atk_down}或是{passiveImg:def_down}*\\n‧ATK159%{passiveImg:up_g}\\n‧必可发动奋力一击\\n*给予敌人致命一击后*\\n‧{passiveImg:forever}ATK、DEF、回避率59%{passiveImg:up_g}\", \"passiveSkillName\": \"人类0计划启动\", \"passiveSkillSetId\": 4653}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
