INSERT INTO `eza_card` VALUES ('aa3c4ed1815145c8', 1021641, '克林&人造人18号', 7, '契合度超群的夫妇之力', 100, '12', 32, 4, 140, 10092, 10932, 5103, 2365, '*基本效果*\n‧气珠变化：体气珠→知气珠\n*取得5个以上知气珠*\n‧必可追加发动必杀技\n*每次发动攻击时*\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高180%)', 1021642, '「组合」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是知属性的气力+3、HP、ATK、DEF提升50%', '2021-07-29 16:00:00', '{\"leaderSkill\": \"「组合」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是知属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1021642, \"passiveSkillDesc\": \"*基本效果*\\n‧气珠变化：体气珠→知气珠\\n*取得5个以上知气珠*\\n‧必可追加发动必杀技\\n*每次发动攻击时*\\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高180%)\", \"passiveSkillName\": \"夫妇协力两人三脚\", \"passiveSkillSetId\": 2365}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
