INSERT INTO `eza_card` VALUES ('af5c3a2b16e548fa', 1011461, '人造人18号(未来)', 7, '凄惨之毁灭', 200, '20', 40, 4, 140, 13709, 10460, 5943, 3544, '*基本效果*\n‧气珠变化：体气珠→速气珠\n‧ATK与DEF150%{passiveImg:up_g}\n‧中等机率回避敌人的攻击\n*HP78%以下*\n‧气珠变化：知气珠→体气珠\n‧必可发动追加攻击且高机率发动必杀技\n*每取得1个速气珠*\n‧ATK20%{passiveImg:up_g}\n‧DEF30%{passiveImg:up_g}\n*每取得1个速气珠以外的气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n*参加攻击中的我方除自身以外，每多1名「未来篇」类别的角色*\n‧气力+1、ATK与DEF50%{passiveImg:up_g}\n‧回避率18%{passiveImg:up_g}', 1011461, '速属性的气力+3、HP、ATK、DEF提升100%', '2023-12-18 16:00:00', '{\"leaderSkill\": \"速属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011461, \"passiveSkillDesc\": \"*基本效果*\\n‧气珠变化：体气珠→速气珠\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧中等机率回避敌人的攻击\\n*HP78%以下*\\n‧气珠变化：知气珠→体气珠\\n‧必可发动追加攻击且高机率发动必杀技\\n*每取得1个速气珠*\\n‧ATK20%{passiveImg:up_g}\\n‧DEF30%{passiveImg:up_g}\\n*每取得1个速气珠以外的气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n*参加攻击中的我方除自身以外，每多1名「未来篇」类别的角色*\\n‧气力+1、ATK与DEF50%{passiveImg:up_g}\\n‧回避率18%{passiveImg:up_g}\", \"passiveSkillName\": \"绝佳位置\", \"passiveSkillSetId\": 3544}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
