INSERT INTO `eza_card` VALUES ('b954f8493b3c4f6b', 1011301, '超级赛亚人4悟吉达', 7, '天下无双的光芒', 100, '11', 58, 4, 140, 14599, 15345, 5909, 2754, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n‧敌方全体极系的ATK与DEF20%{passiveImg:down_y}\n‧高机率对全属性造成属性克制伤害\n*每次发动必杀技时*\n‧5回合内ATK与DEF25%{passiveImg:up_g}(最高50%)\n*受到敌人的必杀技攻击时*\n‧超高机率使其无效，并以超绝大威力反击', 1011301, '「融合」类别的\n气力+3、HP、ATK、DEF提升170%，\n或是技属性的气力+3、HP、ATK、DEF提升100%', '2022-07-18 16:00:00', '{\"leaderSkill\": \"「融合」类别的\\n气力+3、HP、ATK、DEF提升170%，\\n或是技属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1011301, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n‧敌方全体极系的ATK与DEF20%{passiveImg:down_y}\\n‧高机率对全属性造成属性克制伤害\\n*每次发动必杀技时*\\n‧5回合内ATK与DEF25%{passiveImg:up_g}(最高50%)\\n*受到敌人的必杀技攻击时*\\n‧超高机率使其无效，并以超绝大威力反击\", \"passiveSkillName\": \"正义的正向能源\", \"passiveSkillSetId\": 2754}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('b97f402fa79b4b70', 1015001, '孙悟饭(幼年期)', 7, '愤怒的呐喊', 100, '12', 42, 4, 140, 15747, 11962, 6928, 4011, '*基本效果*\n‧我方全体知属性的气力+3、ATK与DEF10%{passiveImg:up_g}\n‧我方全体超知属性的ATK与DEF50%{passiveImg:up_g}\n‧随机气珠变化：知气珠以外的任一属性气珠→知气珠\n*每取得1个气珠*\n‧ATK与DEF50%{passiveImg:up_g}\n*每取得1个知气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n‧发动奋力一击的机率10%{passiveImg:up_g}\n*我方队伍除了自己以外，有2名以上超系的角色时*\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→知气珠\n*我方队伍除了自己以外，有3名以上知属性的角色时*\n‧登场后4回合内防御所有攻击', 1015001, '超知属性的气力+4、HP、ATK、DEF提升150%', '2024-04-11 16:00:00', '{\"leaderSkill\": \"超知属性的气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015001, \"passiveSkillDesc\": \"*基本效果*\\n‧我方全体知属性的气力+3、ATK与DEF10%{passiveImg:up_g}\\n‧我方全体超知属性的ATK与DEF50%{passiveImg:up_g}\\n‧随机气珠变化：知气珠以外的任一属性气珠→知气珠\\n*每取得1个气珠*\\n‧ATK与DEF50%{passiveImg:up_g}\\n*每取得1个知气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n‧发动奋力一击的机率10%{passiveImg:up_g}\\n*我方队伍除了自己以外，有2名以上超系的角色时*\\n‧{passiveImg:once}HP50%以下时气珠变化：全部气珠→知气珠\\n*我方队伍除了自己以外，有3名以上知属性的角色时*\\n‧登场后4回合内防御所有攻击\", \"passiveSkillName\": \"怒火冲天\", \"passiveSkillSetId\": 4011}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
