INSERT INTO `eza_card` VALUES ('c00db757dbef41b8', 1023091, '希特&超级赛亚人神孙悟空', 3, '超绝光速战斗爆发', 200, '23', 77, 5, 150, 18175, 15360, 9338, 4592, '*基本效果*\n‧气力+5、ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率20%{passiveImg:up_g}\n‧攻击必中敌人\n‧必可发动追加攻击且超高机率发动必杀技\n‧高机率回避敌人的攻击\n*HP67%以上*\n‧伤害减轻率10%{passiveImg:up_g}\n*攻击时*\n‧ATK与DEF67%{passiveImg:up_g}\n‧使敌方防御无效\n*处于该回合第一或是第二顺位时*\n‧气力+6、ATK与DEF160%{passiveImg:up_g}\n‧回避率与伤害减轻率16%{passiveImg:up_g}\n*每次处于该回合第一或是第二顺位\n并受到攻击或是回避敌人的攻击时*\n‧{passiveImg:forever}ATK20%{passiveImg:up_g}(最高100%)\n*处于该回合第三攻击顺位时*\n‧气力+7、ATK170%{passiveImg:up_g}\n‧追加发动必杀技\n‧使攻击过的敌人行动中断\n*每次处于该回合第三攻击顺位时*\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高100%)', 1023091, '「高速战斗」或是「宇宙生存篇」类别的\n气力+4、HP、ATK、DEF提升170%', '2025-05-07 16:00:00', '{\"leaderSkill\": \"「高速战斗」或是「宇宙生存篇」类别的\\n气力+4、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1023091, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+5、ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率20%{passiveImg:up_g}\\n‧攻击必中敌人\\n‧必可发动追加攻击且超高机率发动必杀技\\n‧高机率回避敌人的攻击\\n*HP67%以上*\\n‧伤害减轻率10%{passiveImg:up_g}\\n*攻击时*\\n‧ATK与DEF67%{passiveImg:up_g}\\n‧使敌方防御无效\\n*处于该回合第一或是第二顺位时*\\n‧气力+6、ATK与DEF160%{passiveImg:up_g}\\n‧回避率与伤害减轻率16%{passiveImg:up_g}\\n*每次处于该回合第一或是第二顺位\\n并受到攻击或是回避敌人的攻击时*\\n‧{passiveImg:forever}ATK20%{passiveImg:up_g}(最高100%)\\n*处于该回合第三攻击顺位时*\\n‧气力+7、ATK170%{passiveImg:up_g}\\n‧追加发动必杀技\\n‧使攻击过的敌人行动中断\\n*每次处于该回合第三攻击顺位时*\\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高100%)\", \"passiveSkillName\": \"光速优势\", \"passiveSkillSetId\": 4592}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
