INSERT INTO `eza_card` VALUES ('d370609eee994043', 1025631, '杰克张', 3, '天下第一武道大会的最后高潮', 100, '12', 99, 5, 150, 15083, 13355, 9078, 4796, '*基本效果*\n‧气力+4、ATK与DEF180%{passiveImg:up_g}\n‧我方全体「天下第一武道大会」或是「智谋交锋」类别的\n气力+3、ATK与DEF50%{passiveImg:up_g}\n‧对全属性造成属性克制伤害\n*参加攻击中的我方除了自己以外，\n有「天下第一武道大会」或是「智谋交锋」类别的角色时*\n‧必可发动追加攻击且超高机率发动必杀技\n*每次发动必杀技时*\n‧{passiveImg:forever}气力+1(最高+4)\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\n*每次受到攻击或是回避敌人的攻击时*\n‧{passiveImg:forever}气力+1(最高+4)\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\n*发动主动技能时，\n或是气力值24攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n*受到被超必杀技命中的敌人的攻击时*\n‧DEF100%{passiveImg:up_g}\n‧伤害减轻率50%{passiveImg:up_g}', 1025631, '「天下第一武道大会」类别的\n气力+4、HP、ATK、DEF提升150%', '2025-12-11 16:00:00', '{\"leaderSkill\": \"「天下第一武道大会」类别的\\n气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1025631, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+4、ATK与DEF180%{passiveImg:up_g}\\n‧我方全体「天下第一武道大会」或是「智谋交锋」类别的\\n气力+3、ATK与DEF50%{passiveImg:up_g}\\n‧对全属性造成属性克制伤害\\n*参加攻击中的我方除了自己以外，\\n有「天下第一武道大会」或是「智谋交锋」类别的角色时*\\n‧必可发动追加攻击且超高机率发动必杀技\\n*每次发动必杀技时*\\n‧{passiveImg:forever}气力+1(最高+4)\\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\\n*每次受到攻击或是回避敌人的攻击时*\\n‧{passiveImg:forever}气力+1(最高+4)\\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高150%)\\n*发动主动技能时，\\n或是气力值24攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*受到被超必杀技命中的敌人的攻击时*\\n‧DEF100%{passiveImg:up_g}\\n‧伤害减轻率50%{passiveImg:up_g}\", \"passiveSkillName\": \"符合决赛水准的战斗\", \"passiveSkillSetId\": 4796}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
