INSERT INTO `eza_card` VALUES ('d534ca3dae5140c6', 1020671, '超级赛亚人4布罗利', 7, '暴虐的狂战士', 200, '21', 42, 4, 140, 18670, 15324, 7825, 3945, '*气力值12以上攻击时*\n‧ATK与DEF150%{passiveImg:up_g}\n*参加攻击中的我方除了自己以外，有「巨猿力量」类别的角色时*\n‧气力+2\n‧必可发动追加攻击且高机率发动必杀技\n*参加攻击中的我方全体皆属于「巨猿力量」类别时*\n‧追加发动必杀技\n*每次发动必杀技时*\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高150%)', 1020671, '「巨猿力量」类别的\n气力+3、HP、ATK、DEF提升150%', '2023-11-21 16:00:00', '{\"leaderSkill\": \"「巨猿力量」类别的\\n气力+3、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020671, \"passiveSkillDesc\": \"*气力值12以上攻击时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*参加攻击中的我方除了自己以外，有「巨猿力量」类别的角色时*\\n‧气力+2\\n‧必可发动追加攻击且高机率发动必杀技\\n*参加攻击中的我方全体皆属于「巨猿力量」类别时*\\n‧追加发动必杀技\\n*每次发动必杀技时*\\n‧{passiveImg:forever}ATK与DEF30%{passiveImg:up_g}(最高150%)\", \"passiveSkillName\": \"恶魔的暴走加剧\", \"passiveSkillSetId\": 3945}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('d55e2c6c45ab4a8e', 1019711, '卡莉芙拉', 7, '散发光芒的可能性', 100, '11', 15, 4, 140, 10221, 11656, 6191, 4056, '*基本效果*\n‧ATK与DEF160%{passiveImg:up_g}\n*队伍里每多1名「第6宇宙」、「活泼女孩」类别的角色*\n‧ATK、DEF、回避率8%{passiveImg:up_g}\n*敌方有「宇宙生存篇」、「纯粹赛亚人」类别的角色时*\n‧必可回避敌人的攻击\n*队伍里有6名以上「第6宇宙」类别的角色时*\n‧战斗中成功回避敌人的攻击6次以上\n后，2回合内我方全体的ATK16%{passiveImg:up_g}\n*参加攻击中的我方有名称含有「凯露」的角色时*\n‧ATK160%{passiveImg:up_g}\n‧必可追加发动必杀技', 1019711, '「第6宇宙」或是「活泼女孩」类别的\n气力+3、HP、ATK、DEF提升130%', '2024-02-22 16:00:00', '{\"leaderSkill\": \"「第6宇宙」或是「活泼女孩」类别的\\n气力+3、HP、ATK、DEF提升130%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1019711, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF160%{passiveImg:up_g}\\n*队伍里每多1名「第6宇宙」、「活泼女孩」类别的角色*\\n‧ATK、DEF、回避率8%{passiveImg:up_g}\\n*敌方有「宇宙生存篇」、「纯粹赛亚人」类别的角色时*\\n‧必可回避敌人的攻击\\n*队伍里有6名以上「第6宇宙」类别的角色时*\\n‧战斗中成功回避敌人的攻击6次以上\\n后，2回合内我方全体的ATK16%{passiveImg:up_g}\\n*参加攻击中的我方有名称含有「凯露」的角色时*\\n‧ATK160%{passiveImg:up_g}\\n‧必可追加发动必杀技\", \"passiveSkillName\": \"感性扩大\", \"passiveSkillSetId\": 4056}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('d5649916777b4b85', 1027191, '魔少年', 7, '憎恨和平的一闪', 200, '20', 36, 4, 140, 10097, 10046, 6633, 4795, '*基本效果*\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\n‧必可发动追加攻击且高机率发动必杀技\n‧高机率发动奋力一击\n*敌方有「大会参赛者」或是「龟仙流」\n类别的角色时*\n‧气力+2、ATK与DEF150%{passiveImg:up_g}\n*只有1名敌人时*\n‧追加发动必杀技\n‧防御所有攻击\n*气力值12以上攻击前*\n‧该回合超高机率回避敌人的攻击\n*气力值12以上攻击时*\n‧ATK与DEF200%{passiveImg:up_g}\n*登场后第3回合起，气力值12以上攻击时*\n‧{passiveImg:once}ATK250%{passiveImg:up_g}、DEF150%{passiveImg:up_g}\n‧{passiveImg:once}必可发动奋力一击\n‧{passiveImg:once}使攻击过的敌人晕眩2回合\n*登场后第6回合起，气力值12以上攻击时*\n‧{passiveImg:once}ATK200%{passiveImg:up_g}、DEF100%{passiveImg:up_g}\n‧{passiveImg:once}必可发动奋力一击\n‧{passiveImg:once}封锁攻击过的敌人的必杀技2回合\n*登场后第9回合起，气力值12以上攻击时*\n‧ATK150%{passiveImg:up_g}、DEF50%{passiveImg:up_g}\n‧封锁攻击过的敌人的必杀技', 1027192, '速属性的气力+3、HP、ATK、DEF提升100%', '2025-12-11 16:00:00', '{\"leaderSkill\": \"速属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1027192, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2、ATK与DEF200%{passiveImg:up_g}\\n‧必可发动追加攻击且高机率发动必杀技\\n‧高机率发动奋力一击\\n*敌方有「大会参赛者」或是「龟仙流」\\n类别的角色时*\\n‧气力+2、ATK与DEF150%{passiveImg:up_g}\\n*只有1名敌人时*\\n‧追加发动必杀技\\n‧防御所有攻击\\n*气力值12以上攻击前*\\n‧该回合超高机率回避敌人的攻击\\n*气力值12以上攻击时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n*登场后第3回合起，气力值12以上攻击时*\\n‧{passiveImg:once}ATK250%{passiveImg:up_g}、DEF150%{passiveImg:up_g}\\n‧{passiveImg:once}必可发动奋力一击\\n‧{passiveImg:once}使攻击过的敌人晕眩2回合\\n*登场后第6回合起，气力值12以上攻击时*\\n‧{passiveImg:once}ATK200%{passiveImg:up_g}、DEF100%{passiveImg:up_g}\\n‧{passiveImg:once}必可发动奋力一击\\n‧{passiveImg:once}封锁攻击过的敌人的必杀技2回合\\n*登场后第9回合起，气力值12以上攻击时*\\n‧ATK150%{passiveImg:up_g}、DEF50%{passiveImg:up_g}\\n‧封锁攻击过的敌人的必杀技\", \"passiveSkillName\": \"魔族的咒缚\", \"passiveSkillSetId\": 4795}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
