INSERT INTO `eza_card` VALUES ('d734d7c500b74a89', 1015181, '亚姆&普尔', 3, '狼的觉醒', 100, '14', 99, 5, 150, 14715, 14384, 7975, 4100, '*基本效果*\n‧气力+5\n‧必可发动追加攻击且高机率发动必杀技\n*气力值12以上攻击时*\n‧ATK与DEF150%{passiveImg:up_g}\n*气力值18以上攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n*参加攻击中的我方除了自己以外，有「组合」类别的角色时*\n‧必可发动追加攻击且高机率发动必杀技\n*敌方有「活泼女孩」类别的角色时*\n‧DEF150%{passiveImg:up_g}\n‧自身必定晕眩\n*敌方无「活泼女孩」类别的角色时*\n‧气力+3、ATK150%{passiveImg:up_g}\n‧高机率回避敌人的攻击', 1015181, '「组合」类别的\n气力+4、HP、ATK、DEF提升150%', '2024-06-27 16:00:00', '{\"leaderSkill\": \"「组合」类别的\\n气力+4、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1015181, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+5\\n‧必可发动追加攻击且高机率发动必杀技\\n*气力值12以上攻击时*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*气力值18以上攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*参加攻击中的我方除了自己以外，有「组合」类别的角色时*\\n‧必可发动追加攻击且高机率发动必杀技\\n*敌方有「活泼女孩」类别的角色时*\\n‧DEF150%{passiveImg:up_g}\\n‧自身必定晕眩\\n*敌方无「活泼女孩」类别的角色时*\\n‧气力+3、ATK150%{passiveImg:up_g}\\n‧高机率回避敌人的攻击\", \"passiveSkillName\": \"狼的弱点！？\", \"passiveSkillSetId\": 4100}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
