INSERT INTO `eza_card` VALUES ('eabb0de03c2d4190', 4018781, '魔人贝吉达', 7, '不顾一切的斗志', 200, '21', 58, 4, 140, 14644, 16717, 9060, 4459, '*基本效果*\n‧气力+3、ATK与DEF200%{passiveImg:up_g}\n‧伤害减轻率33%{passiveImg:up_g}\n*剩余HP越多*\n‧ATK{passiveImg:up_g}(最高150%)\n*HP50%以上*\n‧必可追加发动必杀技\n*剩余HP越少*\n‧DEF{passiveImg:up_g}(最高150%)\n*HP50%以下*\n‧防御所有攻击\n*敌方或是参加攻击中的我方除自身以\n外，有「魔人普乌篇」类别的角色时*\n‧随机气珠变化：任一属性气珠→彩虹珠\n*取得1个以上彩虹珠*\n‧伤害减轻率33%{passiveImg:up_g}\n*取得3个以上气珠*\n‧对全属性造成属性克制伤害\n‧攻击时ATK与DEF130%{passiveImg:up_g}\n*取得6个以上气珠*\n‧防御所有攻击\n‧攻击时ATK与DEF66%{passiveImg:up_g}', 1017421, '「超级赛亚人2」或是「复活战士」类别的\n气力+3、HP、ATK、DEF提升170%', NULL, '{\"leaderSkill\": \"「超级赛亚人2」或是「复活战士」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1017421, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3、ATK与DEF200%{passiveImg:up_g}\\n‧伤害减轻率33%{passiveImg:up_g}\\n*剩余HP越多*\\n‧ATK{passiveImg:up_g}(最高150%)\\n*HP50%以上*\\n‧必可追加发动必杀技\\n*剩余HP越少*\\n‧DEF{passiveImg:up_g}(最高150%)\\n*HP50%以下*\\n‧防御所有攻击\\n*敌方或是参加攻击中的我方除自身以\\n外，有「魔人普乌篇」类别的角色时*\\n‧随机气珠变化：任一属性气珠→彩虹珠\\n*取得1个以上彩虹珠*\\n‧伤害减轻率33%{passiveImg:up_g}\\n*取得3个以上气珠*\\n‧对全属性造成属性克制伤害\\n‧攻击时ATK与DEF130%{passiveImg:up_g}\\n*取得6个以上气珠*\\n‧防御所有攻击\\n‧攻击时ATK与DEF66%{passiveImg:up_g}\", \"passiveSkillName\": \"威胁的变化\", \"passiveSkillSetId\": 4459}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('eb270bcf9b7f4eb4', 1011211, '杰克张', 7, '霸气的优胜宣言', 100, '12', 36, 4, 140, 10097, 9773, 6974, 4108, '*基本效果*\n‧气力+2、ATK与DEF100%{passiveImg:up_g}\n‧低机率回避敌人的攻击\n*气力值12以上攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n*每次受到攻击时*\n‧{passiveImg:forever}ATK30%{passiveImg:up_g}(最高150%)\n‧{passiveImg:forever}回避率20%{passiveImg:up_g}(最高60%)\n*每次回避敌人的攻击时*\n‧{passiveImg:forever}DEF30%{passiveImg:up_g}(最高150%)\n‧{passiveImg:forever}发动奋力一击的机率20%{passiveImg:up_g}(最高60%)\n*受到敌人的攻击时HP10%以上*\n‧可承受致命伤害(该回合最多1次)', 1011212, '「天下第一武道大会」类别的\n气力+3、HP、ATK、DEF提升90%', '2024-06-27 16:00:00', '{\"leaderSkill\": \"「天下第一武道大会」类别的\\n气力+3、HP、ATK、DEF提升90%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011212, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+2、ATK与DEF100%{passiveImg:up_g}\\n‧低机率回避敌人的攻击\\n*气力值12以上攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n*每次受到攻击时*\\n‧{passiveImg:forever}ATK30%{passiveImg:up_g}(最高150%)\\n‧{passiveImg:forever}回避率20%{passiveImg:up_g}(最高60%)\\n*每次回避敌人的攻击时*\\n‧{passiveImg:forever}DEF30%{passiveImg:up_g}(最高150%)\\n‧{passiveImg:forever}发动奋力一击的机率20%{passiveImg:up_g}(最高60%)\\n*受到敌人的攻击时HP10%以上*\\n‧可承受致命伤害(该回合最多1次)\", \"passiveSkillName\": \"师父的自尊\", \"passiveSkillSetId\": 4108}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('eb8554edd3124735', 1018651, '贝吉特', 3, '究极无敌的合体', 100, '11', 77, 5, 150, 19875, 16720, 6788, 3374, '*基本效果*\n‧ATK与DEF140%{passiveImg:up_g}\n*攻击时*\n‧气力+4\n‧DEF100%{passiveImg:up_g}\n*处于该回合第一或是第二攻击顺位时*\n‧必可发动追加攻击且超高机率发动必杀技\n*处于该回合第三攻击顺位时*\n‧追加发动必杀技\n‧超高机率回避敌人的攻击\n*战斗开始后第4回合起*\n‧进行变身', 1018651, '「最后的杀手锏」或是「波特拉」类别的\n气力+3、HP、ATK、DEF提升170%', '2023-08-01 16:00:00', '{\"leaderSkill\": \"「最后的杀手锏」或是「波特拉」类别的\\n气力+3、HP、ATK、DEF提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1018651, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF140%{passiveImg:up_g}\\n*攻击时*\\n‧气力+4\\n‧DEF100%{passiveImg:up_g}\\n*处于该回合第一或是第二攻击顺位时*\\n‧必可发动追加攻击且超高机率发动必杀技\\n*处于该回合第三攻击顺位时*\\n‧追加发动必杀技\\n‧超高机率回避敌人的攻击\\n*战斗开始后第4回合起*\\n‧进行变身\", \"passiveSkillName\": \"给我去死吧！！\", \"passiveSkillSetId\": 3374}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
