INSERT INTO `eza_card` VALUES ('ed70d3af0ec84e35', 1025201, '金属克维拉[体]', 7, '钢铁战鬼', 200, '24', 32, 4, 140, 10376, 10013, 5106, 2999, '*基本效果*\n‧以造成敌方伤害的15%回复自身HP\n*回合开始时，处于该回合第一顺位时*\n‧气珠变化：知气珠→彩虹珠\n*队伍里每多1名「最凶恶的一族」类别的角色*\n‧ATK与DEF40%{passiveImg:up_g}(最高200%)\n*参加攻击中的我方除了自己以外，有\n名称含有「金属克维拉」的角色时*\n‧每取得1个气珠DEF25%{passiveImg:up_g}\n‧取得3个以上彩虹珠时以造成敌方伤害的5%回复自身HP', 1025202, '「复仇」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是全属性的气力+3、HP、ATK、DEF提升40%', '2022-09-21 16:00:00', '{\"leaderSkill\": \"「复仇」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是全属性的气力+3、HP、ATK、DEF提升40%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1025202, \"passiveSkillDesc\": \"*基本效果*\\n‧以造成敌方伤害的15%回复自身HP\\n*回合开始时，处于该回合第一顺位时*\\n‧气珠变化：知气珠→彩虹珠\\n*队伍里每多1名「最凶恶的一族」类别的角色*\\n‧ATK与DEF40%{passiveImg:up_g}(最高200%)\\n*参加攻击中的我方除了自己以外，有\\n名称含有「金属克维拉」的角色时*\\n‧每取得1个气珠DEF25%{passiveImg:up_g}\\n‧取得3个以上彩虹珠时以造成敌方伤害的5%回复自身HP\", \"passiveSkillName\": \"共鸣现象\", \"passiveSkillSetId\": 2999}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
