INSERT INTO `eza_card` VALUES ('f08b781bb1ca436a', 1010661, '超级赛亚人孙悟空(天使)(超级界王拳)', 7, '全力燃烧', 100, '14', 42, 4, 140, 11986, 11195, 6138, 4587, '*基本效果*\n‧气力+4、ATK与DEF200%{passiveImg:up_g}\n‧高机率回避敌人的攻击\n‧随机气珠变化：知气珠→知气珠以外的任一属性气珠\n*受到敌人的攻击时*\n‧可承受致命伤害(该回合最多1次)\n*HP80%以上*\n‧DEF100%{passiveImg:up_g}\n*HP80%以下*\n‧气珠变化：体气珠→力气珠\n*气力值12以上攻击时*\n‧ATK与DEF100%{passiveImg:up_g}\n‧若HP为80%以下，ATK与DEF再50%{passiveImg:up_g}\n*取得力气珠或是体气珠时*\n‧追加发动2次必杀技\n*每取得1个力气珠或是体气珠*\n‧ATK40%{passiveImg:up_g}\n‧发动奋力一击的机率10%{passiveImg:up_g}\n*取得速气珠或是技气珠或是知气珠时*\n‧防御所有攻击\n*每取得1个速气珠或是技气珠或是知气珠*\n‧ATK与DEF20%{passiveImg:up_g}\n‧回避率5%{passiveImg:up_g}', 1010661, '体属性的气力+3、HP、ATK、DEF提升100%', '2025-04-09 16:00:00', '{\"leaderSkill\": \"体属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1010661, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+4、ATK与DEF200%{passiveImg:up_g}\\n‧高机率回避敌人的攻击\\n‧随机气珠变化：知气珠→知气珠以外的任一属性气珠\\n*受到敌人的攻击时*\\n‧可承受致命伤害(该回合最多1次)\\n*HP80%以上*\\n‧DEF100%{passiveImg:up_g}\\n*HP80%以下*\\n‧气珠变化：体气珠→力气珠\\n*气力值12以上攻击时*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧若HP为80%以下，ATK与DEF再50%{passiveImg:up_g}\\n*取得力气珠或是体气珠时*\\n‧追加发动2次必杀技\\n*每取得1个力气珠或是体气珠*\\n‧ATK40%{passiveImg:up_g}\\n‧发动奋力一击的机率10%{passiveImg:up_g}\\n*取得速气珠或是技气珠或是知气珠时*\\n‧防御所有攻击\\n*每取得1个速气珠或是技气珠或是知气珠*\\n‧ATK与DEF20%{passiveImg:up_g}\\n‧回避率5%{passiveImg:up_g}\", \"passiveSkillName\": \"沸腾的斗气\", \"passiveSkillSetId\": 4587}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('f1efacc57ec147ec', 1020391, '超级赛亚人2卡莉芙拉', 7, '为了获胜的强大', 100, '13', 40, 4, 140, 11798, 9687, 6405, 2616, '*队伍里每多1名「宇宙生存篇」类别的角色*\n‧ATK与DEF30%{passiveImg:up_g}(最高160%)\n‧回避率15%{passiveImg:up_g}(最高60%)\n*队伍里有名称含有「凯露」的角色时*\n‧ATK70%{passiveImg:up_g}\n‧若在参加攻击的队列中，必可发动追加攻击且中等机率发动必杀技', 1020392, '「急遽成长」类别的\n气力+3、HP、ATK、DEF提升77%，\n或是力属性的气力+3、HP、ATK、DEF提升50%', '2021-12-14 16:00:00', '{\"leaderSkill\": \"「急遽成长」类别的\\n气力+3、HP、ATK、DEF提升77%，\\n或是力属性的气力+3、HP、ATK、DEF提升50%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020392, \"passiveSkillDesc\": \"*队伍里每多1名「宇宙生存篇」类别的角色*\\n‧ATK与DEF30%{passiveImg:up_g}(最高160%)\\n‧回避率15%{passiveImg:up_g}(最高60%)\\n*队伍里有名称含有「凯露」的角色时*\\n‧ATK70%{passiveImg:up_g}\\n‧若在参加攻击的队列中，必可发动追加攻击且中等机率发动必杀技\", \"passiveSkillName\": \"超激进\", \"passiveSkillSetId\": 2616}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('f2244ca79c50426b', 1024751, '琪莱', 7, '开朗的发掘人才活动', 200, '22', 18, 4, 140, 11597, 10165, 7379, 4698, '*基本效果*\n‧气力+3\n‧DEF339%{passiveImg:up_g}\n‧看穿敌方必杀技\n‧随机气珠变化：任一属性气珠→彩虹珠\n‧超高机率回避敌人的攻击\n‧除自身以外的我方全体的气力+3、ATK与DEF39%{passiveImg:up_g}、\n发动奋力一击的机率20%{passiveImg:up_g}\n*每次回避敌人的攻击时*\n‧该回合DEF139%{passiveImg:up_g}\n*战斗中每次回避敌人的攻击3次时*\n‧回合结束时HP回复39%(最多3次)\n*战斗中成功回避敌人的攻击6次以上后*\n‧{passiveImg:once}3回合内除自身以外的我方全体的ATK与DEF39%{passiveImg:up_g}\n*受到敌人的普通攻击时*\n‧暂时使DEF139%{passiveImg:up_g}\n*受到敌人的必杀技攻击时*\n‧暂时使回避率10%{passiveImg:up_g}', 1024751, '「挚友的羁绊」类别的\n气力+3、HP、ATK、DEF提升150%', '2025-08-17 16:00:00', '{\"leaderSkill\": \"「挚友的羁绊」类别的\\n气力+3、HP、ATK、DEF提升150%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1024751, \"passiveSkillDesc\": \"*基本效果*\\n‧气力+3\\n‧DEF339%{passiveImg:up_g}\\n‧看穿敌方必杀技\\n‧随机气珠变化：任一属性气珠→彩虹珠\\n‧超高机率回避敌人的攻击\\n‧除自身以外的我方全体的气力+3、ATK与DEF39%{passiveImg:up_g}、\\n发动奋力一击的机率20%{passiveImg:up_g}\\n*每次回避敌人的攻击时*\\n‧该回合DEF139%{passiveImg:up_g}\\n*战斗中每次回避敌人的攻击3次时*\\n‧回合结束时HP回复39%(最多3次)\\n*战斗中成功回避敌人的攻击6次以上后*\\n‧{passiveImg:once}3回合内除自身以外的我方全体的ATK与DEF39%{passiveImg:up_g}\\n*受到敌人的普通攻击时*\\n‧暂时使DEF139%{passiveImg:up_g}\\n*受到敌人的必杀技攻击时*\\n‧暂时使回避率10%{passiveImg:up_g}\", \"passiveSkillName\": \"琪莱的体贴\", \"passiveSkillSetId\": 4698}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
