INSERT INTO `eza_card` VALUES ('f26f6b1bd9db490c', 1017801, '机械桃白白', 7, '凌厉的杀意', 200, '21', 40, 4, 140, 9415, 10955, 5837, 4168, '*气力值12以上攻击时*\n‧ATK与DEF200%{passiveImg:up_g}\n‧攻击必中敌人\n*受到被必杀技命中的敌人的攻击时*\n‧伤害减轻率50%{passiveImg:up_g}\n*每次受到攻击时*\n‧{passiveImg:forever}气力+1(最高+4)\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高200%)\n*敌方有「地球人」或是「大会参赛者」类别的角色时*\n‧气力+1\n‧ATK与DEF100%{passiveImg:up_g}\n*敌方有「龟仙流」类别的角色时*\n‧必可发动奋力一击', 1017802, '技属性的气力+3、HP、ATK、DEF提升100%', '2024-08-15 16:00:00', '{\"leaderSkill\": \"技属性的气力+3、HP、ATK、DEF提升100%\", \"carnivalFlag\": false, \"freeCardFlag\": true, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1017802, \"passiveSkillDesc\": \"*气力值12以上攻击时*\\n‧ATK与DEF200%{passiveImg:up_g}\\n‧攻击必中敌人\\n*受到被必杀技命中的敌人的攻击时*\\n‧伤害减轻率50%{passiveImg:up_g}\\n*每次受到攻击时*\\n‧{passiveImg:forever}气力+1(最高+4)\\n‧{passiveImg:forever}ATK与DEF50%{passiveImg:up_g}(最高200%)\\n*敌方有「地球人」或是「大会参赛者」类别的角色时*\\n‧气力+1\\n‧ATK与DEF100%{passiveImg:up_g}\\n*敌方有「龟仙流」类别的角色时*\\n‧必可发动奋力一击\", \"passiveSkillName\": \"缜密的计算\", \"passiveSkillSetId\": 4168}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
