INSERT INTO `eza_card` VALUES ('fd00514cf5d842bf', 1018151, '超级赛亚人特南克斯(未来)', 7, '未来的胜利者', 100, '11', 40, 4, 140, 11435, 12313, 6670, 3580, '*基本效果*\n‧ATK与DEF150%{passiveImg:up_g}\n*每次发动攻击时*\n‧{passiveImg:forever}ATK、DEF、发动奋力一击的机率25%{passiveImg:up_g}(最高50%)\n*队伍里有名称含有「孙悟饭(未来)」的角色时*\n‧气力+3、ATK与DEF100%{passiveImg:up_g}\n*敌方有「人造人」或是「未来篇」类别的角色时*\n‧气力+6\n‧必可发动奋力一击\n*敌方有名称含有「赛鲁」的角色时(不包含赛鲁Jr.等)*\n‧ATK100%{passiveImg:up_g}', 1018151, '「师徒的羁绊」类别的\n气力+3、HP、ATK、DEF提升130%', '2023-09-07 16:00:00', '{\"leaderSkill\": \"「师徒的羁绊」类别的\\n气力+3、HP、ATK、DEF提升130%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1018151, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF150%{passiveImg:up_g}\\n*每次发动攻击时*\\n‧{passiveImg:forever}ATK、DEF、发动奋力一击的机率25%{passiveImg:up_g}(最高50%)\\n*队伍里有名称含有「孙悟饭(未来)」的角色时*\\n‧气力+3、ATK与DEF100%{passiveImg:up_g}\\n*敌方有「人造人」或是「未来篇」类别的角色时*\\n‧气力+6\\n‧必可发动奋力一击\\n*敌方有名称含有「赛鲁」的角色时(不包含赛鲁Jr.等)*\\n‧ATK100%{passiveImg:up_g}\", \"passiveSkillName\": \"为了未来的和平\", \"passiveSkillSetId\": 3580}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
