INSERT INTO `eza_card` VALUES ('fe7856076c8c43e6', 1011371, '超级赛亚人2孙悟饭(青年期)', 7, '头号战士的真正价值', 100, '14', 40, 4, 140, 11695, 11268, 5690, 2491, '*基本效果*\n‧ATK与DEF100%{passiveImg:up_g}\n‧我方全体的气力+2、ATK与DEF35%{passiveImg:up_g}\n*战斗中自身发动3次以上必杀技后*\n‧{passiveImg:forever}中等机率发动奋力一击\n‧{passiveImg:forever}中等机率回避敌人的攻击', 1011371, '全属性的气力+3、HP、ATK、DEF提升60%', '2021-11-24 16:00:00', '{\"leaderSkill\": \"全属性的气力+3、HP、ATK、DEF提升60%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1011371, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK与DEF100%{passiveImg:up_g}\\n‧我方全体的气力+2、ATK与DEF35%{passiveImg:up_g}\\n*战斗中自身发动3次以上必杀技后*\\n‧{passiveImg:forever}中等机率发动奋力一击\\n‧{passiveImg:forever}中等机率回避敌人的攻击\", \"passiveSkillName\": \"燃烧的士气\", \"passiveSkillSetId\": 2491}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('fec7c697fb4647e7', 4022391, '超级赛亚人神SS孙悟空\n&超级赛亚人神SS贝吉达', 3, '无限力量的神战士', 100, '11', 77, 5, 150, 16475, 16675, 8169, 4521, '*基本效果*\n‧{passiveImg:once}1回合内伤害减轻率77%{passiveImg:up_g}\n‧ATK与DEF300%{passiveImg:up_g}\n‧取得气珠时气力再+2\n‧对全属性造成属性克制伤害\n‧防御所有攻击\n‧高机率发动奋力一击\n‧中等机率回避敌人的攻击\n‧气珠变化：知气珠→彩虹珠\n*登场后4回合内*\n‧随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\n*每取得1个气珠*\n‧ATK与DEF10%{passiveImg:up_g}(最高100%)\n*每取得1个彩虹珠*\n‧发动奋力一击的机率与回避率10%{passiveImg:up_g}\n*取得7个以上气珠*\n‧追加发动必杀技\n*气力值20以上攻击时*\n‧追加发动必杀技\n*发动主动技能时，\n或是气力值24攻击时*\n‧ATK50%{passiveImg:up_g}\n*攻击时*\n‧{passiveImg:once}若敌人的HP为50%以上，\n必可发动奋力一击、追加发动必杀技\n*受到攻击时*\n‧{passiveImg:once}若自身的HP为50%以下，\n回避敌人的攻击', 1022381, '「超越超级赛亚人之力」或是「剧场版HERO」\n类别的气力+3、HP、ATK、DEF提升170%，\n若有包含「龟派气功」类别，\n气力再+1、HP、ATK、DEF再提升30%', NULL, '{\"leaderSkill\": \"「超越超级赛亚人之力」或是「剧场版HERO」\\n类别的气力+3、HP、ATK、DEF提升170%，\\n若有包含「龟派气功」类别，\\n气力再+1、HP、ATK、DEF再提升30%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1022381, \"passiveSkillDesc\": \"*基本效果*\\n‧{passiveImg:once}1回合内伤害减轻率77%{passiveImg:up_g}\\n‧ATK与DEF300%{passiveImg:up_g}\\n‧取得气珠时气力再+2\\n‧对全属性造成属性克制伤害\\n‧防御所有攻击\\n‧高机率发动奋力一击\\n‧中等机率回避敌人的攻击\\n‧气珠变化：知气珠→彩虹珠\\n*登场后4回合内*\\n‧随机气珠变化：知气珠以外的任一属性气珠→彩虹珠\\n*每取得1个气珠*\\n‧ATK与DEF10%{passiveImg:up_g}(最高100%)\\n*每取得1个彩虹珠*\\n‧发动奋力一击的机率与回避率10%{passiveImg:up_g}\\n*取得7个以上气珠*\\n‧追加发动必杀技\\n*气力值20以上攻击时*\\n‧追加发动必杀技\\n*发动主动技能时，\\n或是气力值24攻击时*\\n‧ATK50%{passiveImg:up_g}\\n*攻击时*\\n‧{passiveImg:once}若敌人的HP为50%以上，\\n必可发动奋力一击、追加发动必杀技\\n*受到攻击时*\\n‧{passiveImg:once}若自身的HP为50%以下，\\n回避敌人的攻击\", \"passiveSkillName\": \"超级赛亚人蓝变身！\", \"passiveSkillSetId\": 4521}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('ff03ec70973c402a', 1020831, '黑假面的赛亚人', 7, '假面带来的力量提升', 200, '20', 32, 4, 140, 11170, 12594, 6469, 3954, '*攻击时*\n‧气力+3、ATK与DEF160%{passiveImg:up_g}\n*我方队伍除了自己以外，有3名以上「跨界」类别的角色时*\n‧ATK与DEF120%{passiveImg:up_g}\n‧必可发动追加攻击且高机率发动必杀技\n‧高机率发动奋力一击\n*敌方有名称含有「孙悟空」的角色时(不包含奇纽、Jr.等)*\n‧必可发动奋力一击', 1020831, '「七龙珠英雄」类别\n或是极速属性的气力+3、HP、ATK、DEF提升130%', '2023-11-21 16:00:00', '{\"leaderSkill\": \"「七龙珠英雄」类别\\n或是极速属性的气力+3、HP、ATK、DEF提升130%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": false, \"leaderSkillSetId\": 1020831, \"passiveSkillDesc\": \"*攻击时*\\n‧气力+3、ATK与DEF160%{passiveImg:up_g}\\n*我方队伍除了自己以外，有3名以上「跨界」类别的角色时*\\n‧ATK与DEF120%{passiveImg:up_g}\\n‧必可发动追加攻击且高机率发动必杀技\\n‧高机率发动奋力一击\\n*敌方有名称含有「孙悟空」的角色时(不包含奇纽、Jr.等)*\\n‧必可发动奋力一击\", \"passiveSkillName\": \"黑假面破坏者\", \"passiveSkillSetId\": 3954}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
INSERT INTO `eza_card` VALUES ('ff9d0ef428124c4e', 1013831, '超级赛亚人神SS贝吉达', 7, '恪守骄傲', 100, '10', 58, 4, 140, 16153, 13179, 8063, 2802, '*基本效果*\n‧ATK150%{passiveImg:up_g}\n‧DEF100%{passiveImg:up_g}\n‧必可发动2次追加攻击且低机率发动必杀技\n*每次发动攻击时*\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高100%)\n*战斗开始后第4回合起*\n‧有40%的机率进化', 1013831, '「纯粹赛亚人」类别的\n气力+3、HP、DEF、ATK提升170%', '2022-03-22 16:00:00', '{\"leaderSkill\": \"「纯粹赛亚人」类别的\\n气力+3、HP、DEF、ATK提升170%\", \"carnivalFlag\": false, \"freeCardFlag\": false, \"dokkanFesFlag\": true, \"leaderSkillSetId\": 1013831, \"passiveSkillDesc\": \"*基本效果*\\n‧ATK150%{passiveImg:up_g}\\n‧DEF100%{passiveImg:up_g}\\n‧必可发动2次追加攻击且低机率发动必杀技\\n*每次发动攻击时*\\n‧{passiveImg:forever}DEF20%{passiveImg:up_g}(最高100%)\\n*战斗开始后第4回合起*\\n‧有40%的机率进化\", \"passiveSkillName\": \"受到刺激的尊严\", \"passiveSkillSetId\": 2802}', 'system', '2026-01-04 16:46:23', 'system', '2026-01-04 16:46:23');
